package com.trawlingplus;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(TrawlingPlusDebugConfig.GROUP)
public interface TrawlingPlusDebugConfig extends Config
{
	String GROUP = "trawling-plus-debug";

	@ConfigSection(
		name = "Debug: timing",
		description = "Time Trawling Plus's main overlay",
		position = 0
	)
	String timingSection = "timing";

	@ConfigItem(
		keyName = "showRenderTiming",
		name = "Show draw time",
		description = "Show how long the main overlay takes to draw<br>each frame, over the last few seconds.",
		position = 1,
		section = timingSection
	)
	default boolean showRenderTiming()
	{
		return true;
	}

	@ConfigSection(
		name = "Debug: curiosities",
		description = "Fake finds for the trawling log's Curiosities pages",
		position = 2
	)
	String curiositiesSection = "curiosities";

	String FAKE_CURIOSITIES_KEY = "fakeCuriosities";

	@ConfigItem(
		keyName = FAKE_CURIOSITIES_KEY,
		name = "Fake finds",
		description = "Turning on gives this account a random mix of found<br>and not found curiosities, some by"
			+ " crewmates and<br>some from before the log was kept. Turning off<br>clears them all.",
		position = 3,
		section = curiositiesSection
	)
	default boolean fakeCuriosities()
	{
		return false;
	}

	String FAKE_MESSAGE_KEY = "fakeCuriosityMessage";

	@ConfigItem(
		keyName = FAKE_MESSAGE_KEY,
		name = "Fake message",
		description = "Picking one puts that game message in the chatbox,<br>only on this client, as if it had"
			+ " happened. A rare<br>catch also counts as one fish caught.",
		position = 4,
		section = curiositiesSection
	)
	default FakeMessage fakeCuriosityMessage()
	{
		return FakeMessage.NONE;
	}

	enum FakeMessage
	{
		NONE(null),
		PLAYER_MARLIN("You catch a swift marlin!"),
		CREW_KRILL("Jolly Jim catches a giant blue krill!"),
		PLAYER_ORANGEFIN("You catch a orangefin!"),
		PAINT("You've received some paint!"),
		LOG_HADDOCK("New item added to your collection log: <col=ef1020>Golden haddock</col>");

		final String message;

		FakeMessage(String message)
		{
			this.message = message;
		}
	}
}

package com.trawlingplus;

import com.google.inject.Provides;
import java.time.LocalDate;
import java.util.Random;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Dev-only tools for Trawling Plus, loaded by the dev client and never part of the released plugin: times its main
 * overlay through the package-private drawTimer hook, and fakes Curiosities finds.
 */
@PluginDescriptor(
	name = "Trawling Plus Debug",
	description = "Debug tools for Trawling Plus",
	developerPlugin = true
)
public class TrawlingPlusDebugPlugin extends Plugin
{
	// Crewmates' names, from the game's crew.
	private static final String[] CREW = {"Jolly Jim", "Jobless Jim", "Jittery Jim", "Sailor Jakob",
		"Adventurer Ada", "Bosun Zarah", "Oarswoman Olga", "Ex-Captain Siad", "Spotter Virginia",
		"Cabin Boy Jenkins"};

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TrawlingPlusDebugTimingOverlay timingOverlay;

	@Inject
	private ConfigManager configManager;

	@Inject
	private TrawlingPlusDebugConfig config;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Provides
	TrawlingPlusDebugConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TrawlingPlusDebugConfig.class);
	}

	@Override
	protected void startUp()
	{
		TrawlingPlusOverlay.drawTimer = timingOverlay;
		overlayManager.add(timingOverlay);
	}

	@Override
	protected void shutDown()
	{
		TrawlingPlusOverlay.drawTimer = null;
		overlayManager.remove(timingOverlay);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!TrawlingPlusDebugConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (TrawlingPlusDebugConfig.FAKE_MESSAGE_KEY.equals(event.getKey()))
		{
			fakeMessage();
			return;
		}
		if (!TrawlingPlusDebugConfig.FAKE_CURIOSITIES_KEY.equals(event.getKey()))
		{
			return;
		}
		boolean on = Boolean.parseBoolean(event.getNewValue());
		Random random = new Random();
		for (Curiosity curiosity : Curiosity.values())
		{
			configManager.unsetRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.foundKey());
			configManager.unsetRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.finderKey());
			if (!on || random.nextInt(3) == 0)
			{
				// Left not found.
				continue;
			}
			String date = random.nextInt(4) == 0 ? Curiosity.FROM_LOG
				: LocalDate.now().minusDays(random.nextInt(365)).toString();
			configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.foundKey(), date);
			if (!Curiosity.FROM_LOG.equals(date) && curiosity.getCrewEntry() != null && random.nextBoolean())
			{
				configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.finderKey(),
					CREW[random.nextInt(CREW.length)]);
			}
			else if (!Curiosity.FROM_LOG.equals(date) && curiosity.getElsewhereEntry() != null && random.nextBoolean())
			{
				configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.finderKey(),
					Curiosity.FOUND_ELSEWHERE);
			}
		}
	}

	/** Puts the picked game message in this client's chatbox only, then sets the pick back to none. */
	private void fakeMessage()
	{
		String message = config.fakeCuriosityMessage().message;
		if (message == null)
		{
			return;
		}
		clientThread.invokeLater(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null));
		configManager.setConfiguration(TrawlingPlusDebugConfig.GROUP, TrawlingPlusDebugConfig.FAKE_MESSAGE_KEY,
			TrawlingPlusDebugConfig.FakeMessage.NONE);
	}
}

package com.trawlingplus;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * How long Trawling Plus's main overlay takes to draw, over the last WINDOW frames, as average / median in
 * milliseconds: the whole overlay, the route line within it, and the line split into building it (placing its points
 * and working out the fade near the boat) and stroking it (Java2D drawing the path).
 */
class TrawlingPlusDebugTimingOverlay extends OverlayPanel implements TrawlingPlusOverlay.DrawTimer
{
	// About five seconds at 120 frames a second.
	private static final int WINDOW = 600;

	private final TrawlingPlusDebugConfig config;
	private final long[] total = new long[WINDOW];
	private final long[] line = new long[WINDOW];
	private final long[] stroke = new long[WINDOW];
	private int count;
	private int next;

	@Inject
	TrawlingPlusDebugTimingOverlay(TrawlingPlusDebugConfig config)
	{
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/**
	 * Takes one frame's timings. Called on the client thread, as the overlay draws.
	 */
	@Override
	public void took(long totalNanos, long lineNanos, long strokeNanos)
	{
		total[next] = totalNanos;
		line[next] = lineNanos;
		stroke[next] = strokeNanos;
		next = (next + 1) % WINDOW;
		count = Math.min(count + 1, WINDOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showRenderTiming() || count == 0)
		{
			return null;
		}

		long[] build = new long[count];
		for (int i = 0; i < count; i++)
		{
			build[i] = line[i] - stroke[i];
		}

		panelComponent.getChildren().add(TitleComponent.builder().text("Trawling Plus draw").build());
		row("Frames", Integer.toString(count));
		row("", "avg / median");
		row("Overlay", times(total));
		row("Route line", times(line));
		row("- build", times(build));
		row("- stroke", times(stroke));
		long[] sorted = sorted(total);
		row("Overlay 1%", millis(sorted[(int) (count * 0.99)]));
		return super.render(graphics);
	}

	private String times(long[] samples)
	{
		long[] sorted = sorted(samples);
		long sum = 0;
		for (long sample : sorted)
		{
			sum += sample;
		}
		return millis((double) sum / count) + " / " + millis(sorted[count / 2]);
	}

	private long[] sorted(long[] samples)
	{
		long[] sorted = Arrays.copyOf(samples, count);
		Arrays.sort(sorted);
		return sorted;
	}

	private void row(String left, String right)
	{
		panelComponent.getChildren().add(LineComponent.builder().left(left).right(right).build());
	}

	private static String millis(double nanos)
	{
		return String.format("%.3f", nanos / 1e6);
	}
}

package com.trawlingplus;

import java.util.List;
import lombok.Value;

/**
 * One page of the hold book: a title and its lines, and maybe a name signed at its foot, an item's picture above its
 * number, or a tab for the section it starts. A line is text, wrapped to the page and either left aligned or centred,
 * a centred heading in faded ink, a row with a name on the left and a value on the right, or a blank line. Pages are
 * compared by what they hold, so the book redraws one only when it changes.
 */
@Value
class BookPage
{
	String title;
	List<Line> lines;
	// Signed at the foot of the page beside a wax seal, or null for none.
	String signature;
	// An item drawn just above the page number, or 0 for none.
	int picture;
	// The picture as a faint shape only, for an item not yet found.
	boolean silhouette;
	// For the first page of a section, the section's name, shown on a tab under the page; null for none.
	String tab;

	BookPage(String title, List<Line> lines)
	{
		this(title, lines, null);
	}

	BookPage(String title, List<Line> lines, String signature)
	{
		this(title, lines, signature, 0, false);
	}

	BookPage(String title, List<Line> lines, String signature, int picture, boolean silhouette)
	{
		this(title, lines, signature, picture, silhouette, null);
	}

	private BookPage(String title, List<Line> lines, String signature, int picture, boolean silhouette, String tab)
	{
		this.title = title;
		this.lines = lines;
		this.signature = signature;
		this.picture = picture;
		this.silhouette = silhouette;
		this.tab = tab;
	}

	/** The same page, starting a section with this name on its tab. */
	BookPage withTab(String name)
	{
		return new BookPage(title, lines, signature, picture, silhouette, name);
	}

	@Value
	static class Line
	{
		String left;
		// Null for a line of text.
		String right;
		boolean centred;
		// Drawn in the faded ink of the page numbers, for a heading over the lines below it.
		boolean faded;
		// Shown while the mouse is over the line, or null for none.
		String tooltip;
		// For a row, how many star milestones it has reached (three stars, each bronze, silver then gold), drawn in a
		// column after the name; -1 for a row without stars.
		int stars;
		// Wrapped so its lines come out about even, a line break starting a new paragraph: left aligned in a block
		// centred on the page, or each line centred.
		boolean balanced;

		/** The same line, with a tooltip shown while the mouse is over it. */
		Line tip(String text)
		{
			return new Line(left, right, centred, faded, text, stars, balanced);
		}

		/** The same row, with stars for this many milestones reached. */
		Line withStars(int reached)
		{
			return new Line(left, right, centred, faded, tooltip, reached, balanced);
		}
	}

	static Line text(String text)
	{
		return new Line(text, null, false, false, null, -1, false);
	}

	static Line centred(String text)
	{
		return new Line(text, null, true, false, null, -1, false);
	}

	static Line heading(String text)
	{
		return new Line(text, null, true, true, null, -1, false);
	}

	static Line blank()
	{
		return new Line("", null, false, false, null, -1, false);
	}

	static Line row(String name, String value)
	{
		return new Line(name, value, false, false, null, -1, false);
	}

	/** A journal entry: balanced lines, left aligned in a block centred on the page. */
	static Line entry(String text)
	{
		return new Line(text, null, false, false, null, -1, true);
	}

	/** A hint in faded ink: balanced lines, each centred. */
	static Line hint(String text)
	{
		return new Line(text, null, true, true, null, -1, true);
	}
}

package com.trawlingplus;

import java.awt.Color;
import java.util.Arrays;
import net.runelite.api.gameval.ItemID;

/**
 * What one boat's cargo hold holds of the sea spot catches, and how many of its slots the
 * rest of its cargo takes out of how many. Only known once its screen has been opened, the only time the game
 * sends it, and kept up to date after by what is deposited or withdrawn as it is shut. Every fish takes a slot of
 * its own, since fish don't stack, so the slots left for them are what the rest doesn't take.
 */
final class CargoHold
{
	// The six sea spot catches, which are only caught from a boat, and what the hold's display
	// calls each, in the same order.
	static final int[] SEA_FISH = {
		ItemID.RAW_SHRIMP, ItemID.RAW_ANCHOVIES, ItemID.RAW_SARDINE, ItemID.RAW_HERRING, ItemID.RAW_MACKEREL,
		ItemID.RAW_COD, ItemID.RAW_BASS, ItemID.RAW_SHARK, ItemID.RAW_LOBSTER, ItemID.RAW_TUNA, ItemID.RAW_SWORDFISH,
		ItemID.TBWT_RAW_KARAMBWAN, ItemID.RAW_ANGLERFISH, ItemID.RAW_MONKFISH
	};
	static final String[] SEA_FISH_NAMES = {
		"Shrimps", "Anchovies", "Sardine", "Herring", "Mackerel",
		"Cod", "Bass", "Shark", "Lobster", "Tuna", "Swordfish",
		"Karambwan", "Anglerfish", "Monkfish"
	};
	// The colour each is listed in: its item picture's own colour, lifted to read on the dark display.
	static final Color[] SEA_FISH_COLOURS = {
		new Color(0xdc8d7c), new Color(0x8b8ebf), new Color(0x74d975), new Color(0xd9cbcb), new Color(0xd9d76b),
		new Color(0xa8a8d9), new Color(0xd97a6e), new Color(0xd9c3c3), new Color(0xd95c00), new Color(0xe6d8d5),
		new Color(0xcc86d9), new Color(0x72bf3f), new Color(0x6bbf52), new Color(0xd97b5b)
	};

	// How many of each, by SEA_FISH, and the slots taken by everything else, such as bait, planks, salvage and
	// trawled fish, and there are, or -1 before the screen has shown them.
	private final int[] fish = new int[SEA_FISH.length];
	private int others = -1;
	private int capacity = -1;
	// How many trawled fish it holds, from its screen or the nets emptied into it since, or -1 if not known.
	private int trawled = -1;
	// How many times any of those has changed, which the display goes by to only write its lines out again then.
	private int changes;
	// Which went in most recently: by SEA_FISH, the number of the deposit that last brought each, or 0 if none has
	// been seen; how many deposits there have been, those on the same tick counting as one; and the last one's tick.
	private final int[] lastDeposit = new int[SEA_FISH.length];
	private int deposits;
	private int depositTick = -1;
	// Whether the display at the helm warns that it is full: found without room when the nets were last emptied
	// into it, or showing no free slots when last opened, until it is known to have room again.
	private boolean fullWarning;

	int changes()
	{
		return changes;
	}

	/**
	 * The number of the deposit that last brought this kind, higher for more recent ones, or 0 if none has been seen.
	 */
	int lastDeposit(int kind)
	{
		return lastDeposit[kind];
	}

	boolean fullWarning()
	{
		return fullWarning;
	}

	void setFullWarning(boolean full)
	{
		fullWarning = full;
	}

	int fish(int kind)
	{
		return fish[kind];
	}

	/**
	 * How many trawled fish it holds, or -1 if not known.
	 */
	int trawled()
	{
		return trawled;
	}

	void setTrawled(int count)
	{
		trawled = count;
	}

	/**
	 * Notes fish from the nets going in: at least that many trawled fish, even if it wasn't known before.
	 */
	void addTrawled(int count)
	{
		trawled = Math.max(0, trawled) + count;
	}

	/**
	 * How many sea spot catches it holds, all kinds together.
	 */
	int caught()
	{
		int caught = 0;
		for (int count : fish)
		{
			caught += count;
		}
		return caught;
	}

	/**
	 * How many of those catches it has slots for, counting the ones in it: all of its slots but those the rest of
	 * its cargo takes.
	 */
	int room()
	{
		return capacity - others;
	}

	/**
	 * Whether its slots are known, which they are once its screen has been opened.
	 */
	boolean known()
	{
		return others >= 0 && capacity > 0;
	}

	boolean full()
	{
		return known() && caught() >= room();
	}

	/**
	 * Whether at least a share of its slots, 0.9 being 90%, are taken, by anything, once known.
	 */
	boolean fullTo(double share)
	{
		return known() && capacity - room() + caught() >= capacity * share;
	}

	/**
	 * Takes how many of a kind its screen shows, on the tick it showed them. More than it was known to hold were just
	 * deposited; before its contents are known, there is nothing to say which went in last.
	 */
	void setFish(int kind, int count, int tick)
	{
		if (fish[kind] != count)
		{
			if (count > fish[kind] && known())
			{
				noteDeposit(kind, tick);
			}
			fish[kind] = count;
			changes++;
		}
	}

	/**
	 * Takes the slots taken and there are from its screen, once its catches are counted: those not taken by them
	 * are taken by the rest.
	 */
	void setSlots(int taken, int capacity)
	{
		int others = Math.max(0, taken - caught());
		if (others != this.others || capacity != this.capacity)
		{
			this.others = others;
			this.capacity = capacity;
			changes++;
		}
	}

	/**
	 * Adds fish put in without the screen sending them, as when deposited just as it is shut.
	 */
	void deposit(int kind, int count, int tick)
	{
		fish[kind] += count;
		noteDeposit(kind, tick);
		changes++;
	}

	private void noteDeposit(int kind, int tick)
	{
		if (tick != depositTick)
		{
			depositTick = tick;
			deposits++;
		}
		lastDeposit[kind] = deposits;
	}

	/**
	 * Takes away fish taken out without the screen sending it, as when withdrawn just as it is shut.
	 */
	void withdraw(int kind, int count)
	{
		fish[kind] = Math.max(0, fish[kind] - count);
		changes++;
	}

	/**
	 * Everything taken out at once, as when the crew move it all to the bank from the dock.
	 */
	void empty()
	{
		Arrays.fill(fish, 0);
		trawled = 0;
		changes++;
		if (others >= 0)
		{
			others = 0;
		}
		fullWarning = false;
	}
}

package com.trawlingplus;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.function.BooleanSupplier;
import java.util.function.IntSupplier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.ui.overlay.infobox.InfoBox;
import net.runelite.client.util.QuantityFormatter;

/**
 * A count of fish: of one kind caught, of every kind caught, or in the nets. A count below 0 is not known. The
 * caught ones also give the account's lifetime count in their tooltip.
 */
class CatchInfoBox extends InfoBox
{
	private final String label;
	private final IntSupplier count;
	// How many have been caught in the account's lifetime, or null for a box with no lifetime count.
	private final IntSupplier lifetime;
	private final BooleanSupplier shown;

	CatchInfoBox(BufferedImage image, Plugin plugin, String label, IntSupplier count, IntSupplier lifetime,
		BooleanSupplier shown)
	{
		super(image, plugin);
		this.label = label;
		this.count = count;
		this.lifetime = lifetime;
		this.shown = shown;
	}

	@Override
	public String getText()
	{
		int fish = count.getAsInt();
		return fish < 0 ? "?" : QuantityFormatter.quantityToStackSize(fish);
	}

	@Override
	public Color getTextColor()
	{
		return Color.WHITE;
	}

	@Override
	public String getTooltip()
	{
		int fish = count.getAsInt();
		String tooltip = label + ": " + (fish < 0 ? "unknown" : QuantityFormatter.formatNumber(fish));
		return lifetime == null ? tooltip
			: tooltip + "</br>Lifetime: " + QuantityFormatter.formatNumber(lifetime.getAsInt());
	}

	@Override
	public boolean render()
	{
		return shown.getAsBoolean();
	}
}

package com.trawlingplus;

import lombok.Getter;
import net.runelite.api.gameval.ItemID;

/**
 * The rare finds written up at the back of the trawling log, a page each: the item, its name before it is found, its
 * journal entry for the player and for a crewmate (who names it first), and a hint while it is still to be found.
 */
@Getter
enum Curiosity
{
	GIANT_BLUE_KRILL(ItemID.POH_TROPHYDROP_GIANT_KRILL, "Giant blue krill", "Rare giant krill",
		"I caught a curious blue krill today. The crew almost started a mutiny over cooking and eating it!"
			+ "\nI didn't let them.",
		" caught a curious blue krill today. They almost started a mutiny over cooking and eating it!"
			+ "\nI didn't let them.",
		"It's rumoured that strangely coloured krill hide in shimmering shoals."),
	GOLDEN_HADDOCK(ItemID.POH_TROPHYDROP_HADDOCK, "Golden haddock", "Rare haddock",
		"I caught a haddock that glimmered like gold in the sunlight today. The crew wanted to sell it at the next"
			+ " port! I'm keeping it.",
		" caught a haddock that glimmered like gold in the sunlight today. They wanted to sell it at the next"
			+ " port! I'm keeping it.",
		"Merchants say there's a haddock worth its weight in gold hiding in shimmering shoals."),
	ORANGEFIN(ItemID.POH_TROPHYDROP_YELLOWFIN, "Orangefin", "Rare yellowfin",
		"I caught a yellowfin dyed like the setting sun today. The crew have argued over what to call it ever"
			+ " since!\nI settled on Orangefin.",
		" caught a yellowfin dyed like the setting sun. The crew argued over what to call it!"
			+ "\nI settled on Orangefin.",
		"Legends say the sun once sank into a glistening shoal, and a yellowfin swallowed its light."),
	HUGE_HALIBUT(ItemID.POH_TROPHYDROP_HALIBUT, "Huge halibut", "Rare halibut",
		"I caught a huge halibut today. It took the whole crew to haul it over the side!\nIt nearly sank the boat.",
		" caught a huge halibut today. They needed my help to haul it over the side!\nIt nearly sank the boat.",
		"Old fishermen's tales tell of a halibut that's truly a whopper, hiding in glistening shoals."),
	PURPLEFIN(ItemID.POH_TROPHYDROP_BLUEFIN, "Purplefin", "Rare bluefin",
		"I caught a purple bluefin today. The crew swore it was cursed and wouldn't go near it!\nI think it's lucky.",
		" caught a purple bluefin today. They swore it was cursed and tried to throw it back!\nI think it's lucky.",
		"Sailors whisper of a cursed bluefin, sometimes glimpsed in vibrant shoals."),
	SWIFT_MARLIN(ItemID.POH_TROPHYDROP_MARLIN, "Swift marlin", "Rare marlin",
		"I caught the swiftest marlin I've ever seen today. The crew think it would look good as a figurehead.",
		" caught the swiftest marlin I've ever seen today. They suggested it would look good as a figurehead.",
		"Lookouts swear a marlin faster than the wind itself cuts through vibrant shoals."),
	// Only the player's own net brings up paint, and Soup follows only the player.
	ANGLERS_PAINT(ItemID.SAILING_PAINT_ANGLERS, "Angler's paint", "Rare paint",
		"I hauled up a pot of paint in my nets today, still sealed!"
			+ "\nThe crew can't agree on which part of the boat to paint first.",
		null,
		"Sometimes the junk brought up in the nets hides something useful."),
	SOUP(ItemID.SKILLPETSAILING, "Soup", "A new friend?",
		"I found a sea turtle trapped in my nets, he seems to have taken a liking to me and has followed me ever"
			+ " since! I named him Soup.",
		null,
		"Even in the lonely sea, you can find a new friend.",
		"A sea turtle climbed aboard today and refused to leave. The crew have grown fond of him."
			+ "\nI named him Soup.");

	// The saved date of a find known only from the collection log, and the date line its page shows instead.
	static final String FROM_LOG = "log";
	static final String BEFORE_THE_LOG = "Before this log was kept";
	// Saved as the finder of a find made away from the nets, for which the page tells its elsewhere entry.
	static final String FOUND_ELSEWHERE = "elsewhere";

	private final int itemId;
	private final String name;
	private final String unfoundTitle;
	private final String entry;
	// The crew's entry, after the crewmate's name, or null for a find only the player makes.
	private final String crewEntry;
	private final String hint;
	// The entry for one found away from the nets, or null for a find only the nets give.
	private final String elsewhereEntry;

	Curiosity(int itemId, String name, String unfoundTitle, String entry, String crewEntry, String hint)
	{
		this(itemId, name, unfoundTitle, entry, crewEntry, hint, null);
	}

	Curiosity(int itemId, String name, String unfoundTitle, String entry, String crewEntry, String hint,
		String elsewhereEntry)
	{
		this.itemId = itemId;
		this.name = name;
		this.unfoundTitle = unfoundTitle;
		this.entry = entry;
		this.crewEntry = crewEntry;
		this.hint = hint;
		this.elsewhereEntry = elsewhereEntry;
	}

	/** The profile key holding the date it was first found ("2026-11-12"), or "log" when known only from the log. */
	String foundKey()
	{
		return "curiosityFound_" + itemId;
	}

	/**
	 * The profile key holding the name of the crewmate who found it, or "elsewhere" when found away from the nets,
	 * unset when the player found it in the nets.
	 */
	String finderKey()
	{
		return "curiosityFinder_" + itemId;
	}

	/**
	 * Its entry: the crewmate's, after their name, when one found it, or the player's; the elsewhere entry when found
	 * away from the nets, or before the log was kept, as the log can't say where; told as long ago ("I once
	 * caught...") when found before the log was kept.
	 */
	String entryFor(String finder, boolean beforeTheLog)
	{
		boolean elsewhere = FOUND_ELSEWHERE.equals(finder);
		if (finder != null && !elsewhere && crewEntry != null)
		{
			return finder + crewEntry;
		}
		String text = elsewhereEntry != null && (elsewhere || beforeTheLog) ? elsewhereEntry : entry;
		return beforeTheLog ? text.replace(" today", "").replaceFirst("^I ", "I once ") : text;
	}
}

package com.trawlingplus;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;

/**
 * Notes when each curiosity is first found, for the trawling log's Curiosities pages, per account: from the catch
 * lines and the paint and pet messages as they happen, from the "New item added to your collection log" line, and,
 * for anything found before, from the collection log's own screen whenever the player opens a page of it showing
 * them, checked once a tick while it is open. It only reads; nothing is sent to the game.
 */
@Slf4j
@Singleton
class CuriosityTracker
{
	// The curiosities caught in the nets.
	private static final Curiosity[] RARE_FISH = {Curiosity.GIANT_BLUE_KRILL, Curiosity.GOLDEN_HADDOCK,
		Curiosity.ORANGEFIN, Curiosity.HUGE_HALIBUT, Curiosity.PURPLEFIN, Curiosity.SWIFT_MARLIN};
	// How a catch line of each ends, " purplefin!", checked before the pattern runs.
	private static final String[] RARE_ENDINGS = new String[RARE_FISH.length];
	// "You catch a giant blue krill!", "Jolly Jim catches an orangefin!" (the game says "a orangefin" for the player),
	// naming only the rare fish.
	private static final Pattern RARE_CATCH;

	static
	{
		StringBuilder names = new StringBuilder();
		for (int i = 0; i < RARE_FISH.length; i++)
		{
			String name = RARE_FISH[i].getName().toLowerCase();
			RARE_ENDINGS[i] = " " + name + "!";
			names.append(i == 0 ? "" : "|").append(Pattern.quote(name));
		}
		RARE_CATCH = Pattern.compile("^(?:You catch|(.+) catches) an? (" + names + ")!$");
	}
	private static final String PAINT = "You've received some paint!";
	private static final String COLLECTION_LOG = "New item added to your collection log: ";
	// A pet arriving as a follower, or into the backpack when a follower is already out. Every pet says these, so
	// the pet itself is checked for.
	private static final String PET_FOLLOWING = "You have a funny feeling like you're being followed.";
	private static final String PET_BACKPACK = "You feel something weird sneaking into your backpack.";
	// How long after a pet message the pet is looked for.
	private static final int PET_TICKS = 3;
	// Paint only comes from the player's own net catching, so it only counts this soon after one of their catches.
	private static final int PAINT_AFTER_CATCH_TICKS = 30;
	// How long after the collection log line saves a find the crewmate's catch line can still name its finder.
	private static final int FINDER_TICKS = 2;

	private final Client client;
	private final ConfigManager configManager;
	private final TrawlingPlusPlugin plugin;
	private final Map<String, Curiosity> byName = new HashMap<>();
	private final Map<Integer, Curiosity> byItem = new HashMap<>();

	// The tick the player last caught a fish, or -1.
	private int playerCatchTick = -1;
	// The tick of the last pet message, or -1, and whether it said the backpack.
	private int petTick = -1;
	private boolean petToBackpack;
	// How many Soup items were in the inventory when the pet message came.
	private int soupInInventory;
	// The find the collection log line just saved without a finder, and the tick it did, or null.
	private Curiosity awaitingFinder;
	private int awaitingFinderTick;

	@Inject
	CuriosityTracker(Client client, ConfigManager configManager, TrawlingPlusPlugin plugin)
	{
		this.client = client;
		this.configManager = configManager;
		this.plugin = plugin;
		for (Curiosity curiosity : Curiosity.values())
		{
			byName.put(curiosity.getName().toLowerCase(), curiosity);
			byItem.put(curiosity.getItemId(), curiosity);
		}
	}

	void reset()
	{
		playerCatchTick = -1;
		petTick = -1;
		awaitingFinder = null;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type != ChatMessageType.SPAM && type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.MESBOX)
		{
			return;
		}
		String message = TrawlingPlusPlugin.chatText(event.getMessage());
		int tick = client.getTickCount();
		if (message.startsWith("You catch "))
		{
			playerCatchTick = tick;
		}

		// The pattern only runs on lines ending in a rare fish's name.
		Matcher rare = RARE_CATCH.matcher(message);
		if (endsWithRareFish(message) && rare.matches())
		{
			Curiosity curiosity = byName.get(rare.group(2));
			String crewmate = rare.group(1);
			// A crewmate's catch only counts on the player's own boat, as the crew's catches do.
			if (crewmate == null || !plugin.onOtherBoat())
			{
				found(curiosity, crewmate);
			}
		}
		else if (message.equals(PAINT) && TrawlingPlusPlugin.within(playerCatchTick, tick, PAINT_AFTER_CATCH_TICKS))
		{
			found(Curiosity.ANGLERS_PAINT, null);
		}
		else if (message.startsWith(COLLECTION_LOG))
		{
			Curiosity curiosity = byName.get(message.substring(COLLECTION_LOG.length()).trim().toLowerCase());
			if (curiosity != null && found(curiosity, curiosity == Curiosity.SOUP ? soupFinder() : null)
				&& curiosity.getCrewEntry() != null)
			{
				// The catch line naming who caught it can arrive just after.
				awaitingFinder = curiosity;
				awaitingFinderTick = tick;
			}
		}
		else if (message.equals(PET_FOLLOWING) || message.equals(PET_BACKPACK))
		{
			petTick = tick;
			petToBackpack = message.equals(PET_BACKPACK);
			soupInInventory = soupInInventory();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		readCollectionLog();
		if (petTick < 0)
		{
			return;
		}
		if (!TrawlingPlusPlugin.within(petTick, client.getTickCount(), PET_TICKS))
		{
			petTick = -1;
			return;
		}
		NPC follower = client.getFollower();
		boolean soup = petToBackpack ? soupInInventory() > soupInInventory
			: follower != null && follower.getId() == NpcID.SKILLPET_SAILING;
		if (soup)
		{
			petTick = -1;
			found(Curiosity.SOUP, soupFinder());
		}
	}

	/**
	 * Soup comes from any Sailing activity, so one found with no trawling catch in the last 3 minutes is marked as
	 * found elsewhere, and its page doesn't tell of the nets.
	 */
	private String soupFinder()
	{
		return plugin.caughtRecently() ? null : Curiosity.FOUND_ELSEWHERE;
	}

	/**
	 * While a collection log page is open, any curiosity it shows as obtained, but not yet noted, was found before.
	 * Checked once a tick while it is open, as the page's items are laid out after the page itself is drawn.
	 */
	private void readCollectionLog()
	{
		Widget items = client.getWidget(InterfaceID.Collection.ITEMS);
		if (items == null || items.isHidden())
		{
			return;
		}
		List<Widget> shown = new ArrayList<>();
		collectItems(items, shown);
		for (Widget item : shown)
		{
			Curiosity curiosity = byItem.get(item.getItemId());
			// The log shows items not yet obtained faded out.
			if (curiosity != null && item.getOpacity() == 0 && foundDate(curiosity) == null)
			{
				save(curiosity, Curiosity.FROM_LOG, null);
			}
		}
	}

	/** Every widget showing an item under this one. */
	private static void collectItems(Widget widget, List<Widget> into)
	{
		for (Widget[] children : new Widget[][]{widget.getDynamicChildren(), widget.getStaticChildren(),
			widget.getNestedChildren()})
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (child.getItemId() > 0)
				{
					into.add(child);
				}
				collectItems(child, into);
			}
		}
	}

	/**
	 * Notes a curiosity found now, by a crewmate or (null) the player, unless it already has been; returns whether it
	 * was saved. A saved find is never changed, except that a crewmate's catch line arriving within a couple of ticks
	 * of the collection log line that saved it, for the same item, names its finder.
	 */
	private boolean found(Curiosity curiosity, String crewmate)
	{
		if (foundDate(curiosity) == null)
		{
			save(curiosity, LocalDate.now().toString(), crewmate);
			return true;
		}
		if (curiosity == awaitingFinder && TrawlingPlusPlugin.within(awaitingFinderTick, client.getTickCount(), FINDER_TICKS))
		{
			// Only the one catch line straight after the log line, whoever it names.
			awaitingFinder = null;
			if (crewmate != null)
			{
				log.debug("Curiosity finder: {} by {}", curiosity.getName(), crewmate);
				configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.finderKey(), crewmate);
			}
		}
		return false;
	}

	private void save(Curiosity curiosity, String date, String crewmate)
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}
		log.debug("Curiosity found: {} on {} by {}", curiosity.getName(), date, crewmate);
		configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.foundKey(), date);
		if (crewmate != null && (curiosity.getCrewEntry() != null || Curiosity.FOUND_ELSEWHERE.equals(crewmate)))
		{
			configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.finderKey(), crewmate);
		}
	}

	private static boolean endsWithRareFish(String message)
	{
		for (String ending : RARE_ENDINGS)
		{
			if (message.endsWith(ending))
			{
				return true;
			}
		}
		return false;
	}

	private String foundDate(Curiosity curiosity)
	{
		return configManager.getRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.foundKey());
	}

	private int soupInInventory()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory == null ? 0 : inventory.count(ItemID.SKILLPETSAILING);
	}
}

