	@Inject
	HoldBook(Client client, TrawlingPlusConfig config, TrawlingPlusPlugin plugin, ConfigManager configManager,
		TooltipManager tooltipManager, ItemManager itemManager)
	{
		this.itemManager = itemManager;
		this.tooltipManager = tooltipManager;
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		this.configManager = configManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGHEST);
	}

	/** Closes the book and lets go of the sprites, for when the plugin is switched off. */
	void reset()
	{
		open = false;
		anywhere = false;
		spread = 0;
		turnFrom = -1;
		leafRight = null;
		leafLeft = null;
		coverStart = 0;
		coverInside = null;
		coverOutside = null;
		openedThisSession = false;
		bookmark = null;
		seen = null;
		forgetBounds();
		frame = null;
		arrowLeft = null;
		arrowRight = null;
		close = null;
		closeHovered = null;
		icon = null;
		iconHovered = null;
		seal = null;
		cover = null;
		holdClose = null;
		spritesTriedTick = -1;
		spritesMissingLogged = false;
		overridesUsed.clear();
		overridesCheckedTick = -1;
		closeTriedTick = -1;
		pageImages.clear();
		pageTips.clear();
		pagesDrawn.clear();
		pages = Collections.emptyList();
		pagesReadTick = -1;
		pictures.clear();
		picturesAsked.clear();
		picturesChanged = false;
		bodyFont = null;
		titleFont = null;
		menuOpen = false;
		overWorld = false;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget hold = config.showHoldBook() ? client.getWidget(InterfaceID.SailingBoatCargohold.FRAME) : null;
		boolean holdUp = hold != null && !hold.isHidden();
		long now = System.currentTimeMillis();
		long swung = now - coverStart;
		boolean swinging = coverStart > 0 && swung < COVER_MILLIS;
		// Opened from anywhere, it stays up, and swings shut, without the hold's screen.
		boolean free = config.showHoldBook() && anywhere && (open || swinging);
		if (holdUp || free)
		{
			forgetChangedSprites();
		}
		if (!holdUp && !free || !loadSprites())
		{
			// Opened from the button, the book belongs to the hold's screen and closes with it, at once, letting go
			// of the images only a turn or swing draws into.
			open = false;
			anywhere = false;
			coverStart = 0;
			leafRight = null;
			leafLeft = null;
			coverInside = null;
			coverOutside = null;
			forgetBounds();
			holdClose = null;
			closeTriedTick = -1;
			return null;
		}

		Point mouse = client.getMouseCanvasPosition();
		int mouseX = mouse.getX();
		int mouseY = mouse.getY();
		menuOpen = client.isMenuOpen();
		overWorld = open && !anywhere && !menuOpen && walkingUnderMouse();
		int tick = client.getTickCount();
		if (holdUp)
		{
			drawButton(graphics, hold, tick, mouseX, mouseY);
		}
		else
		{
			buttonBounds = null;
			holdClose = null;
			closeTriedTick = -1;
		}

		if (!open && !swinging)
		{
			forgetBookBounds();
			return null;
		}

		// Over the middle of the hold's screen, which it is no bigger than, or of the game view when opened from
		// anywhere, kept inside the game view: in fixed size mode the view stops short of the side panels and chat,
		// so the book never covers them.
		int viewX = client.getViewportXOffset();
		int viewY = client.getViewportYOffset();
		Rectangle around = holdUp && !anywhere ? hold.getBounds()
			: new Rectangle(viewX, viewY, client.getViewportWidth(), client.getViewportHeight());
		int x = around.x + (around.width - BOOK_WIDTH) / 2;
		int y = around.y + (around.height - BOOK_HEIGHT) / 2;
		x = Math.max(viewX, Math.min(x, viewX + client.getViewportWidth() - BOOK_WIDTH));
		// Room is left below the book for its section tabs.
		int below = config.sectionRibbons() ? TAB_OUT : 0;
		y = Math.max(viewY, Math.min(y, viewY + client.getViewportHeight() - BOOK_HEIGHT - below));
		return drawBook(graphics, tick, now, swung, swinging, x, y, mouseX, mouseY);
	}

	/** The button on the hold's screen, just left of its close button, pulsing until the book is first opened. */
	private void drawButton(Graphics2D graphics, Widget hold, int tick, int mouseX, int mouseY)
	{
		Rectangle frameBounds = hold.getBounds();
		// Looked for again each tick until found: the game may not have built it on the screen's first frame.
		if (holdClose == null && tick != closeTriedTick)
		{
			holdClose = findClose(hold, 0);
			closeTriedTick = tick;
		}
		Rectangle closing = holdClose == null || holdClose.isHidden() ? null : holdClose.getBounds();
		Rectangle button = closing == null
			? new Rectangle(frameBounds.x + frameBounds.width - FALLBACK_RIGHT - BUTTON_GAP - FALLBACK_SIZE,
				frameBounds.y + FALLBACK_TOP, FALLBACK_SIZE, FALLBACK_SIZE)
			: new Rectangle(closing.x - BUTTON_GAP - closing.width, closing.y, closing.width, closing.height);
		// At its own size, centred on where the button goes, never scaled: the click area is the image itself.
		button = new Rectangle(button.x + (button.width - icon.getWidth()) / 2,
			button.y + (button.height - icon.getHeight()) / 2, icon.getWidth(), icon.getHeight());
		boolean lit = open || button.contains(mouseX, mouseY);
		graphics.drawImage(lit ? iconHovered : icon, button.x, button.y, null);
		if (!lit && !bookSeen())
		{
			// Until the book is first opened, the button slowly brightens to its hovered look and back.
			double phase = (System.currentTimeMillis() % BUTTON_PULSE_MILLIS) / (double) BUTTON_PULSE_MILLIS;
			float glow = (float) (0.5 - 0.5 * Math.cos(2 * Math.PI * phase));
			Composite before = graphics.getComposite();
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, glow));
			graphics.drawImage(iconHovered, button.x, button.y, null);
			graphics.setComposite(before);
		}
		buttonBounds = button;
	}

	/** The open book, or the cover swinging, at the given place. */
	private Dimension drawBook(Graphics2D graphics, int tick, long now, long swung, boolean swinging, int x, int y,
		int mouseX, int mouseY)
	{
		if (tick != pagesReadTick)
		{
			pages = plugin.bookPages();
			pagesReadTick = tick;
		}
		if (picturesChanged)
		{
			// A picture arrived: the pages showing it are drawn again.
			picturesChanged = false;
			Collections.fill(pageImages, null);
		}
		List<BookPage> showing = pages;
		int first = Math.min(spread, lastSpread(showing.size()));

		if (swinging)
		{
			// Clicks on the book while it opens do nothing, and none are kept while it closes.
			forgetBookBounds();
			bookBounds = open ? new Rectangle(x, y, BOOK_WIDTH, BOOK_HEIGHT) : null;
			double eased = eased(swung, COVER_MILLIS);
			double angle = Math.PI * (coverOpening ? eased : 1 - eased);
			drawCover(graphics, showing, first, angle, x, y);
			return null;
		}

		graphics.drawImage(frame, x, y, null);
		bookBounds = new Rectangle(x, y, BOOK_WIDTH, BOOK_HEIGHT);
		int from = turnFrom;
		long turned = now - turnStart;
		boolean turning = from >= 0 && from != first && from < showing.size() && turned < TURN_MILLIS;
		// While turning, the pages either side of the leaf: the lower spread's left page and the higher one's right.
		int lower = turning ? Math.min(from, first) : first;
		int higher = turning ? Math.max(from, first) : first;
		// The tabs of every leaf lying still; the turning leaf carries the tabs of all the leaves it turns. A new open
		// section whose tab is on the turning leaf only shows open once the leaf crosses over the spine, halfway
		// through the turn; one lying still shows open at once.
		int section = sectionOf(tabPages(showing), first);
		boolean carried = section >= 0 && leafOf(section) >= leafOf(lower + 1) && leafOf(section) <= leafOf(higher);
		int marked = turning && carried && turned < TURN_MILLIS / 2 ? from : first;
		int hoverTabX = turning || menuOpen ? NO_HOVER : mouseX;
		Map<Rectangle, Integer> tabs = turning
			? drawTabs(graphics, showing, lower, higher + 1, marked, leafOf(lower + 1), leafOf(higher), false, x, y,
				NO_HOVER, 0)
			: drawTabs(graphics, showing, lower, higher + 1, first, -1, -1, false, x, y, hoverTabX, mouseY);
		// Mid-turn the tabs keep their bounds from before it, so a click on one still never reaches the game.
		if (!turning)
		{
			tabBounds = tabs;
		}
		for (Map.Entry<Rectangle, Integer> tab : tabs.entrySet())
		{
			if (tab.getKey().contains(hoverTabX, mouseY))
			{
				tooltipManager.add(new Tooltip(showing.get(tab.getValue()).getTab()));
			}
		}
		int top = y + PAGE_TOP + TITLE_INSET;
		drawPage(graphics, showing, lower, x + LEFT_PAGE_LEFT, y + PAGE_TOP);
		drawPage(graphics, showing, higher + 1, x + RIGHT_PAGE_LEFT, y + PAGE_TOP);
		if (!menuOpen && !turning)
		{
			showTip(first, mouseX - (x + LEFT_PAGE_LEFT + TEXT_INSET), mouseY - top);
			showTip(first + 1, mouseX - (x + RIGHT_PAGE_LEFT + TEXT_INSET), mouseY - top);
		}

		// The buttons belong to their pages and turn with them, uncovering the next page's as the leaf lifts. Hovering
		// shows only while no page is turning; clicks go to the spread being turned to.
		int hoverX = turning || menuOpen ? NO_HOVER : mouseX;
		drawLeftButtons(graphics, lower, x + LEFT_PAGE_LEFT, y + PAGE_TOP, hoverX, mouseY);
		drawRightButtons(graphics, higher, showing.size(), x + RIGHT_PAGE_LEFT, y + PAGE_TOP, hoverX, mouseY);
		closeBounds = closeAt(x + RIGHT_PAGE_LEFT, y + PAGE_TOP);
		// The book opens on the cover anyway, so the first spread has no bookmark.
		bookmarkBounds = first == 0 ? null : ribbonAt(x + LEFT_PAGE_LEFT, y + PAGE_TOP);
		leftBounds = first == 0 ? null : leftArrowAt(x + LEFT_PAGE_LEFT, y + PAGE_TOP);
		rightBounds = first + 2 < showing.size() ? rightArrowAt(x + RIGHT_PAGE_LEFT, y + PAGE_TOP) : null;
		if (bookmarkBounds != null && bookmarkBounds.contains(hoverX, mouseY))
		{
			tooltipManager.add(new Tooltip(bookmarkedSpread() == first ? UNBOOKMARK_TIP : BOOKMARK_TIP));
		}

		if (turning)
		{
			double eased = eased(turned, TURN_MILLIS);
			// Lying on the right page at 0, on the left at pi.
			double angle = Math.PI * (first > from ? eased : 1 - eased);
			drawLeaf(graphics, showing, lower + 1, higher, angle, marked, x, y);
		}
		return null;
	}

	/** The leaf a page is printed on: page 0 alone on the first, then two to a leaf, front and back. */
	private static int leafOf(int page)
	{
		return (page + 1) / 2;
	}

	/**
	 * The tabs of the leaves lying as the spread with this left page has them (the page showing on the right given
	 * too), the spread whose section's tab is drawn open, leaving out a run of leaves (-1 for none) and maybe those on
	 * the left: a leaf's tab hangs below the left page once the leaf is turned past, below the right page before.
	 * Returns where each was drawn, by the page it leads to.
	 */
	private Map<Rectangle, Integer> drawTabs(Graphics2D graphics, List<BookPage> showing, int lying, int shownRight,
		int shown, int skipFrom, int skipTo, boolean rightOnly, int x, int y, int mouseX, int mouseY)
	{
		Map<Rectangle, Integer> drawn = new HashMap<>();
		if (!config.sectionRibbons())
		{
			return drawn;
		}
		List<Integer> tabs = tabPages(showing);
		int open = sectionOf(tabs, shown);
		for (int slot = 0; slot < tabs.size(); slot++)
		{
			int page = tabs.get(slot);
			int leaf = leafOf(page);
			boolean left = leaf <= lying / 2;
			if (leaf >= skipFrom && leaf <= skipTo || rightOnly && left)
			{
				continue;
			}
			int fromSpine = TAB_FIRST + slot * TAB_SPACING;
			int tabX = (int) Math.round(x + SPINE_MIDDLE + (left ? -fromSpine - TAB_WIDTH : fromSpine));
			// Over the page only while its own page shows.
			boolean over = page == open && (page == lying || page == shownRight);
			Rectangle bounds = ribbonBounds(tabX, y + PAGE_BOTTOM, page == open, over);
			drawTab(graphics, bounds, slot, page == open, over, bounds.contains(mouseX, mouseY));
			drawn.put(bounds, page);
		}
		return drawn;
	}

	/** The first page of each section, in order, a section's tab slot being its place in the list. */
	private static List<Integer> tabPages(List<BookPage> showing)
	{
		List<Integer> tabs = new ArrayList<>();
		for (int page = 0; page < showing.size(); page++)
		{
			if (showing.get(page).getTab() != null)
			{
				tabs.add(page);
			}
		}
		return tabs;
	}

	/** The first page of the section the spread with this left page is in, or -1 before the first section. */
	private static int sectionOf(List<Integer> tabs, int first)
	{
		int section = -1;
		for (int page : tabs)
		{
			if (page <= first + 1)
			{
				section = page;
			}
		}
		return section;
	}

	/**
	 * Where a ribbon goes, its left and the page's bottom edge given: hanging below the book while its section is open,
	 * ending level with the cover's edge otherwise, and coming up over the page while it is also its page that shows.
	 */
	private static Rectangle ribbonBounds(int x, int pageEdge, boolean open, boolean over)
	{
		int top = over ? pageEdge - TAB_OPEN_OVER : pageEdge;
		int bottom = pageEdge + TAB_BELOW - (open ? 0 : TAB_OUT);
		return new Rectangle(x, top, TAB_WIDTH, bottom - top);
	}

	/**
	 * A section tab's ribbon: its section's colour while that section is open, otherwise dulled (less so hovered);
	 * fading in from nothing at its top while it comes up over its page, otherwise solid.
	 */
	private static void drawTab(Graphics2D graphics, Rectangle bounds, int slot, boolean open, boolean over,
		boolean hovered)
	{
		Color colour = TAB_COLOURS[slot % TAB_COLOURS.length];
		if (open)
		{
			// Brighter and more saturated than the section's own colour.
			float[] hsb = Color.RGBtoHSB(colour.getRed(), colour.getGreen(), colour.getBlue(), null);
			colour = Color.getHSBColor(hsb[0], Math.min(1, hsb[1] * TAB_OPEN_SATURATION),
				Math.min(1, hsb[2] * TAB_OPEN_BRIGHTNESS));
			colour = hovered ? colour.darker() : colour;
		}
		else
		{
			float dulled = hovered ? TAB_DULLED_HOVERED : TAB_DULLED;
			colour = new Color(dulled(colour.getRed(), TAB_DULL.getRed(), dulled),
				dulled(colour.getGreen(), TAB_DULL.getGreen(), dulled),
				dulled(colour.getBlue(), TAB_DULL.getBlue(), dulled));
		}
		int x = bounds.x;
		int y = bounds.y;
		int bottom = y + bounds.height;
		int middle = x + TAB_WIDTH / 2;
		int[] xs = {x, x + TAB_WIDTH, x + TAB_WIDTH, middle + 1, middle, x};
		int[] ys = {y, y, bottom, bottom - TAB_NOTCH, bottom - TAB_NOTCH, bottom};
		Paint before = graphics.getPaint();

		// A slight shadow, down and to the right, fading in with the ribbon where it comes over the page.
		if (over)
		{
			graphics.translate(TAB_SHADOW_OFFSET, TAB_SHADOW_OFFSET);
			graphics.setPaint(new GradientPaint(x, y, new Color(0, 0, 0, 0), x, y + TAB_OPEN_OVER, TAB_SHADOW));
			graphics.fillPolygon(xs, ys, xs.length);
			graphics.translate(-TAB_SHADOW_OFFSET, -TAB_SHADOW_OFFSET);
		}
		else
		{
			// A ribbon starting at the page's edge has its shadow's right side start there too.
			dropShadow(graphics, xs, ys);
			graphics.fillRect(x + TAB_WIDTH, y, TAB_SHADOW_OFFSET, TAB_SHADOW_OFFSET);
		}

		if (over)
		{
			graphics.setPaint(new GradientPaint(x, y, new Color(colour.getRed(), colour.getGreen(), colour.getBlue(),
				0), x, y + TAB_OPEN_OVER, colour));
		}
		else
		{
			graphics.setColor(colour);
		}
		graphics.fillPolygon(xs, ys, xs.length);
		graphics.setPaint(before);
	}

	/** A colour channel moved this share of the way towards another, then darkened as unselected ribbons are. */
	private static int dulled(int channel, int towards, float share)
	{
		return Math.round((channel + (towards - channel) * share) * TAB_DULLED_SHADE);
	}

	/** How far through a swing this long it is, from 0 to 1, easing in and out. */
	private static double eased(long elapsed, long millis)
	{
		return (1 - Math.cos(Math.PI * elapsed / millis)) / 2;
	}

	/** A spread's left page buttons, the page's top left given: the back arrow and the bookmark, past the cover. */
	private void drawLeftButtons(Graphics2D graphics, int first, int pageX, int pageY, int mouseX, int mouseY)
	{
		if (first == 0)
		{
			return;
		}
		Rectangle arrow = leftArrowAt(pageX, pageY);
		graphics.drawImage(arrowLeft, arrow.x, arrow.y, null);
		Rectangle ribbon = ribbonAt(pageX, pageY);
		drawBookmark(graphics, ribbon.x, ribbon.y, first, ribbon.contains(mouseX, mouseY));
	}

	/** A spread's right page buttons, the page's top left given: the close button, and the next arrow if any. */
	private void drawRightButtons(Graphics2D graphics, int first, int pageCount, int pageX, int pageY, int mouseX,
		int mouseY)
	{
		Rectangle cross = closeAt(pageX, pageY);
		graphics.drawImage(cross.contains(mouseX, mouseY) ? closeHovered : close, cross.x, cross.y, null);
		if (first + 2 < pageCount)
		{
			Rectangle arrow = rightArrowAt(pageX, pageY);
			graphics.drawImage(arrowRight, arrow.x, arrow.y, null);
		}
	}

	private Rectangle closeAt(int pageX, int pageY)
	{
		return new Rectangle(pageX + PAGE_WIDTH - CORNER_INSET - close.getWidth(), pageY + CORNER_INSET,
			close.getWidth(), close.getHeight());
	}

	private static Rectangle ribbonAt(int pageX, int pageY)
	{
		return new Rectangle(pageX + RIBBON_LEFT, pageY - 1, RIBBON_WIDTH, RIBBON_HEIGHT);
	}

	private Rectangle leftArrowAt(int pageX, int pageY)
	{
		return new Rectangle(pageX + CORNER_INSET, pageY + PAGE_HEIGHT - CORNER_INSET - arrowLeft.getHeight(),
			arrowLeft.getWidth(), arrowLeft.getHeight());
	}

	private Rectangle rightArrowAt(int pageX, int pageY)
	{
		return new Rectangle(pageX + PAGE_WIDTH - CORNER_INSET - arrowRight.getWidth(),
			pageY + PAGE_HEIGHT - CORNER_INSET - arrowLeft.getHeight(), arrowRight.getWidth(), arrowRight.getHeight());
	}

	/**
	 * The turning leaf: its right side the page given lying on the right, its left side the one lying on the left. A
	 * jump of several spreads turns the leaves between with it, as a bundle, carrying all their tabs.
	 */
	private void drawLeaf(Graphics2D graphics, List<BookPage> showing, int rightPage, int leftPage, double angle,
		int marked, int x, int y)
	{
		boolean facingRight = Math.cos(angle) >= 0;
		BufferedImage face = leafSide(showing, facingRight ? rightPage : leftPage, facingRight, marked,
			leafOf(rightPage), leafOf(leftPage));
		Rectangle under = new Rectangle(x + (facingRight ? RIGHT_PAGE_LEFT : LEFT_PAGE_LEFT), y + PAGE_TOP, PAGE_WIDTH,
			PAGE_HEIGHT);
		drawSwing(graphics, face, angle, x + SPINE_MIDDLE, LEAF_GAP, y + PAGE_TOP - 1, 1, TAB_BELOW, TURN_LIFT, under,
			LEAF_SHADOW_WIDTH);
	}

	/**
	 * Opening or closing: the right half of the open book, slid towards the middle the more closed it is, with the
	 * cover swinging over the spine (0 closed, pi open), its inside the open book's left half.
	 */
	private void drawCover(Graphics2D graphics, List<BookPage> showing, int first, double angle, int x, int y)
	{
		x -= (int) Math.round(COVER_WIDTH / 2.0 * (1 + Math.cos(angle)) / 2);
		int half = (int) SPINE_MIDDLE;
		graphics.drawImage(frame, x + half, y, x + BOOK_WIDTH, y + BOOK_HEIGHT, half, 0, BOOK_WIDTH, BOOK_HEIGHT, null);
		drawPage(graphics, showing, first + 1, x + RIGHT_PAGE_LEFT, y + PAGE_TOP);
		drawRightButtons(graphics, first, showing.size(), x + RIGHT_PAGE_LEFT, y + PAGE_TOP, NO_HOVER, 0);
		drawTabs(graphics, showing, first, first + 1, first, -1, -1, true, x, y, NO_HOVER, 0);
		boolean facingRight = Math.cos(angle) >= 0;
		Rectangle under = new Rectangle(x + half, y, COVER_WIDTH, BOOK_HEIGHT);
		drawSwing(graphics, facingRight ? coverOutside(showing, first) : coverInside(showing, first), angle,
			x + SPINE_MIDDLE, 0, y, 0, TAB_OUT, COVER_LIFT, under, COVER_SHADOW_WIDTH);
	}

	/**
	 * The ribbons of the pages lying on the left, which swing with the cover, drawn into one of its sides: the inside,
	 * laid out as the open book's left half, or the outside, its spine edge at 0, where they hang only below the
	 * cover's edge.
	 */
	private void drawCoverTabs(Graphics2D g, List<BookPage> showing, int first, boolean inside)
	{
		if (!config.sectionRibbons())
		{
			return;
		}
		List<Integer> tabs = tabPages(showing);
		int open = sectionOf(tabs, first);
		for (int slot = 0; slot < tabs.size(); slot++)
		{
			int page = tabs.get(slot);
			if (leafOf(page) <= first / 2)
			{
				int fromSpine = TAB_FIRST + slot * TAB_SPACING;
				boolean over = inside && page == open && page == first;
				int tabX = inside ? COVER_WIDTH - fromSpine - TAB_WIDTH : fromSpine;
				drawTab(g, ribbonBounds(tabX, PAGE_BOTTOM, page == open, over), slot, page == open, over, false);
			}
		}
	}

	/** The outside of the cover, with the ribbons of the pages under it hanging below its edge. */
	private BufferedImage coverOutside(List<BookPage> showing, int first)
	{
		if (coverOutside == null)
		{
			coverOutside = new BufferedImage(COVER_WIDTH, BOOK_HEIGHT + TAB_OUT, BufferedImage.TYPE_INT_ARGB);
		}
		Graphics2D g = coverOutside.createGraphics();
		g.setComposite(AlphaComposite.Clear);
		g.fillRect(0, 0, COVER_WIDTH, BOOK_HEIGHT + TAB_OUT);
		g.setComposite(AlphaComposite.SrcOver);
		g.clipRect(0, BOOK_HEIGHT, COVER_WIDTH, TAB_OUT);
		drawCoverTabs(g, showing, first, false);
		g.setClip(null);
		g.drawImage(cover, 0, 0, null);
		g.dispose();
		return coverOutside;
	}

	/**
	 * The inside of the cover: the open book's left half, with the left page, its buttons and the ribbons of the pages
	 * lying on the left.
	 */
	private BufferedImage coverInside(List<BookPage> showing, int first)
	{
		if (coverInside == null)
		{
			coverInside = new BufferedImage(COVER_WIDTH, BOOK_HEIGHT + TAB_OUT, BufferedImage.TYPE_INT_ARGB);
		}
		Graphics2D g = coverInside.createGraphics();
		g.setComposite(AlphaComposite.Clear);
		g.fillRect(0, 0, COVER_WIDTH, BOOK_HEIGHT + TAB_OUT);
		g.setComposite(AlphaComposite.SrcOver);
		g.drawImage(frame, 0, 0, COVER_WIDTH, BOOK_HEIGHT, 0, 0, COVER_WIDTH, BOOK_HEIGHT, null);
		drawCoverTabs(g, showing, first, true);
		drawPage(g, showing, first, LEFT_PAGE_LEFT, PAGE_TOP);
		drawLeftButtons(g, first, LEFT_PAGE_LEFT, PAGE_TOP, NO_HOVER, 0);
		g.dispose();
		return coverInside;
	}

	/**
	 * Something swinging over the spine, a leaf or the cover: the side facing up, whose inner edge sits gap px from the
	 * spine, at the given angle (0 lying right, pi lying left), its top at top. Drawn a pixel column at a time, each
	 * column taller the further it stands off the book, up to the given share taller at its edge when upright, as if
	 * lifting towards the viewer, then shaded below its first skipped rows. Its last rows below (a leaf's tab) hang off
	 * it, growing with it but not shaded. It casts a shadow this wide beyond its edge, kept to the area under it.
	 */
	private static void drawSwing(Graphics2D graphics, BufferedImage face, double angle, double spine, double gap,
		double top, int skipped, int below, double turnLift, Rectangle under, int shadowWidth)
	{
		double cos = Math.cos(angle);
		double sin = Math.sin(angle);
		boolean facingRight = cos >= 0;
		int width = face.getWidth();
		int faceHeight = face.getHeight();
		// The leaf itself, without what hangs below it, which grows about its middle.
		int bodyHeight = faceHeight - below;
		double middleY = top + bodyHeight / 2.0;
		double reach = gap + width;
		double lift = turnLift * sin / reach;
		double hingeScale = 1 / (1 - lift * gap);
		double edgeScale = 1 / (1 - lift * reach);
		double hinge = spine + gap * cos * hingeScale;
		double edge = spine + reach * cos * edgeScale;
		float standing = (float) (1 - Math.abs(cos));

		Paint paint = graphics.getPaint();
		Shape clip = graphics.getClip();
		Object interpolation = graphics.getRenderingHint(RenderingHints.KEY_INTERPOLATION);

		// The shadow, beyond the edge, fading away from it.
		double shadowEnd = edge + (facingRight ? 1 : -1) * shadowWidth * sin;
		graphics.clip(under);
		graphics.setPaint(new GradientPaint((float) edge, 0, new Color(0, 0, 0, LEAF_SHADOW * (float) sin),
			(float) shadowEnd, 0, new Color(0, 0, 0, 0)));
		int shadowLeft = (int) Math.floor(Math.min(edge, shadowEnd));
		graphics.fillRect(shadowLeft, under.y, (int) Math.ceil(Math.max(edge, shadowEnd)) - shadowLeft, under.height);
		graphics.setClip(clip);

		// Each pixel column: how far along the leaf it shows, from where it sits off the spine.
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		int start = (int) Math.floor(Math.min(hinge, edge));
		int end = (int) Math.ceil(Math.max(hinge, edge));
		for (int column = start; column < end; column++)
		{
			double offset = column + 0.5 - spine;
			double along = offset / (cos + lift * offset);
			if (!(along >= gap && along < reach))
			{
				continue;
			}
			int source = Math.min(width - 1, (int) (along - gap));
			if (!facingRight)
			{
				source = width - 1 - source;
			}
			double scale = 1 / (1 - lift * along);
			int columnTop = (int) Math.round(middleY - bodyHeight / 2.0 * scale);
			int columnBottom = (int) Math.round(middleY + (bodyHeight / 2.0 + below) * scale);
			graphics.drawImage(face, column, columnTop, column + 1, columnBottom, source, 0, source + 1, faceHeight,
				null);
		}
		if (interpolation != null)
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, interpolation);
		}

		// Darker the more upright it stands, and darker still by the fold.
		Path2D.Double outline = new Path2D.Double();
		outline.moveTo(hinge, middleY - (bodyHeight / 2.0 - skipped) * hingeScale);
		outline.lineTo(edge, middleY - (bodyHeight / 2.0 - skipped) * edgeScale);
		outline.lineTo(edge, middleY + bodyHeight / 2.0 * edgeScale);
		outline.lineTo(hinge, middleY + bodyHeight / 2.0 * hingeScale);
		outline.closePath();
		float shade = LEAF_SHADE * standing;
		graphics.setPaint(new GradientPaint((float) hinge, 0, new Color(0, 0, 0, shade + FOLD_SHADE * (float) sin),
			(float) edge, 0, new Color(0, 0, 0, shade)));
		graphics.fill(outline);
		graphics.setPaint(paint);
	}

	/**
	 * One side of the turning leaf: the page's parchment from the frame, a row down, with the page and its buttons
	 * drawn on it, and the tabs of the leaves turning with it hanging below, only the page's own coming up over it.
	 */
	private BufferedImage leafSide(List<BookPage> showing, int page, boolean right, int marked, int firstLeaf,
		int lastLeaf)
	{
		BufferedImage side = right ? leafRight : leafLeft;
		if (side == null)
		{
			side = new BufferedImage(PAGE_WIDTH, LEAF_HEIGHT + TAB_BELOW, BufferedImage.TYPE_INT_ARGB);
			if (right)
			{
				leafRight = side;
			}
			else
			{
				leafLeft = side;
			}
		}
		Graphics2D g = side.createGraphics();
		g.setComposite(AlphaComposite.Clear);
		g.fillRect(0, 0, PAGE_WIDTH, LEAF_HEIGHT + TAB_BELOW);
		g.setComposite(AlphaComposite.SrcOver);
		int pageLeft = right ? RIGHT_PAGE_LEFT : LEFT_PAGE_LEFT;
		g.drawImage(frame, 0, 1, PAGE_WIDTH, LEAF_HEIGHT, pageLeft, PAGE_TOP, pageLeft + PAGE_WIDTH, PAGE_BOTTOM, null);
		BufferedImage content = pageImage(showing, page);
		if (content != null)
		{
			g.drawImage(content, 0, 1 + TITLE_INSET, null);
		}
		if (right)
		{
			drawRightButtons(g, page - 1, showing.size(), 0, 1, NO_HOVER, 0);
		}
		else
		{
			drawLeftButtons(g, page, 0, 1, NO_HOVER, 0);
		}
		List<Integer> tabs = config.sectionRibbons() ? tabPages(showing) : Collections.emptyList();
		int open = sectionOf(tabs, marked);
		for (int slot = 0; slot < tabs.size(); slot++)
		{
			int tabPage = tabs.get(slot);
			int leaf = leafOf(tabPage);
			if (leaf >= firstLeaf && leaf <= lastLeaf)
			{
				// The same distance from the spine as it lies still, the page's inner edge being LEAF_GAP from it.
				int fromInner = TAB_FIRST + slot * TAB_SPACING - (int) Math.round(LEAF_GAP);
				// Over the page only while its own page is the side facing up.
				boolean over = tabPage == open && tabPage == page;
				drawTab(g, ribbonBounds(right ? fromInner : PAGE_WIDTH - fromInner - TAB_WIDTH, LEAF_HEIGHT,
					tabPage == open, over), slot, tabPage == open, over, false);
			}
		}
		g.dispose();
		return side;
	}

	/**
	 * Opens the book from the hold's right-click menu, in the middle of the game view, wherever the player is: it stays
	 * up until Escape or its close button.
	 */
	void openAnywhere()
	{
		anywhere = true;
		if (!open)
		{
			openBook();
		}
	}

	/** Opens the book, at the bookmark the first time each session, and stops the button pulsing for good. */
	private void openBook()
	{
		setOpen(true);
		if (!bookSeen())
		{
			seen = true;
			configManager.setConfiguration(TrawlingPlusConfig.GROUP, SEEN_KEY, true);
		}
		if (!openedThisSession)
		{
			openedThisSession = true;
			spread = Math.max(0, bookmarkedSpread());
		}
	}

	/**
	 * Opens or closes the book, swinging the cover if animated: from where it is if it was already swinging the other
	 * way.
	 */
	private void setOpen(boolean value)
	{
		if (open == value)
		{
			return;
		}
		open = value;
		turnFrom = -1;
		if (!config.animatedBook())
		{
			coverStart = 0;
			return;
		}
		long now = System.currentTimeMillis();
		long swung = now - coverStart;
		coverStart = swung < COVER_MILLIS ? now - (COVER_MILLIS - swung) : now;
		coverOpening = value;
	}

	/** Starts turning from one spread to another, which then shows. */
	private void turn(int from, int to)
	{
		if (from == to)
		{
			return;
		}
		turnStart = System.currentTimeMillis();
		turnFrom = config.animatedBook() ? from : -1;
		spread = to;
	}

	/** The bookmark ribbon hanging from the top of a spread's left page, red when that spread is the one marked. */
	private void drawBookmark(Graphics2D graphics, int x, int y, int first, boolean hovered)
	{
		int marked = bookmarkedSpread();
		boolean set = marked == first;
		graphics.setColor(set ? (hovered ? RIBBON_SET_HOVERED : RIBBON_SET)
			: hovered ? RIBBON_HOVERED : marked >= 0 ? RIBBON_ELSEWHERE : RIBBON_UNSET);
		Color colour = graphics.getColor();
		int middle = x + RIBBON_WIDTH / 2;
		int[] xs = {x, x + RIBBON_WIDTH, x + RIBBON_WIDTH, middle + 1, middle, x};
		int[] ys = {y, y, y + RIBBON_HEIGHT, y + RIBBON_HEIGHT - RIBBON_NOTCH, y + RIBBON_HEIGHT - RIBBON_NOTCH,
			y + RIBBON_HEIGHT};
		if (set)
		{
			// Set, the same slight shadow as the section ribbons, its right side starting level with the ribbon's top.
			dropShadow(graphics, xs, ys);
			graphics.fillRect(x + RIBBON_WIDTH, y, TAB_SHADOW_OFFSET, TAB_SHADOW_OFFSET);
		}
		graphics.setColor(colour);
		graphics.fillPolygon(xs, ys, xs.length);
	}

	/** Forgets what was read from the old RuneLite profile's config, for when the user switches profiles. */
	void profileChanged()
	{
		seen = null;
		bookmark = null;
	}

	/** Whether the book has ever been opened in this RuneLite profile, read from the config the first time. */
	private boolean bookSeen()
	{
		Boolean known = seen;
		if (known == null)
		{
			known = Boolean.TRUE.equals(configManager.getConfiguration(TrawlingPlusConfig.GROUP, SEEN_KEY, Boolean.class));
			seen = known;
		}
		return known;
	}

	/** The bookmarked spread's left page, or -1 for none, read from the config the first time it is needed. */
	private int bookmarkedSpread()
	{
		Integer marked = bookmark;
		if (marked == null)
		{
			Integer saved = configManager.getConfiguration(TrawlingPlusConfig.GROUP, BOOKMARK_KEY, Integer.class);
			marked = saved != null && saved >= 0 ? saved / 2 * 2 : -1;
			bookmark = marked;
		}
		return marked;
	}

	/** The left page of the last spread for this many pages. */
	private static int lastSpread(int pageCount)
	{
		return Math.max(0, (pageCount - 1) / 2 * 2);
	}

	/** Shows the tooltip of the line on a page under the mouse, given relative to the page's top left. */
	private void showTip(int page, int x, int y)
	{
		if (page >= pageTips.size() || pageTips.get(page) == null)
		{
			return;
		}
		for (Map.Entry<Rectangle, String> tip : pageTips.get(page).entrySet())
		{
			if (tip.getKey().contains(x, y))
			{
				tooltipManager.add(new Tooltip(tip.getValue()));
				return;
			}
		}
	}

	/** A page, given its top left, its image starting under the title inset. */
	private void drawPage(Graphics2D graphics, List<BookPage> showing, int page, int pageX, int pageY)
	{
		BufferedImage image = pageImage(showing, page);
		if (image != null)
		{
			graphics.drawImage(image, pageX, pageY + TITLE_INSET, null);
		}
	}

	/** A page's image, drawn again only when the page has changed; null past the last page. */
	private BufferedImage pageImage(List<BookPage> showing, int page)
	{
		if (page >= showing.size())
		{
			return null;
		}
		while (pageImages.size() <= page)
		{
			pageImages.add(null);
			pageTips.add(null);
			pagesDrawn.add(null);
		}
		BookPage content = showing.get(page);
		if (pageImages.get(page) == null || !content.equals(pagesDrawn.get(page)))
		{
			Map<Rectangle, String> tips = new HashMap<>();
			pageImages.set(page, buildPage(content, page + 1, tips));
			pageTips.set(page, tips);
			pagesDrawn.set(page, content);
		}
		return pageImages.get(page);
	}

	/**
	 * One page: its title in the medium quill, then its lines in the small quill (text wrapped to the page, left
	 * aligned or centred, centred in faded ink for a heading, a row with its name on the left and its value against
	 * the right edge, or a blank line), and its number at the foot. Each line with a tooltip is put in tips, by where
	 * it was drawn.
	 */
	private BufferedImage buildPage(BookPage content, int number, Map<Rectangle, String> tips)
	{
		// The page's full width, side margins included, which a seal may hang over, and from under the title inset to
		// the foot; drawn to with the text's left edge at 0.
		int width = PAGE_WIDTH - 2 * TEXT_INSET;
		int height = PAGE_HEIGHT - TITLE_INSET;
		BufferedImage image = new BufferedImage(PAGE_WIDTH, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.translate(TEXT_INSET, 0);
		String title = content.getTitle();
		QuillFont heading = titleFont.width(title) <= width ? titleFont : bodyFont;
		heading.draw(g, title, (width - heading.width(title)) / 2, 0, INK);

		int lineHeight = bodyFont.height() + 2;
		// Half a blank line between the title and the first line, and for each blank line.
		int gap = lineHeight / 2;
		int line = heading.height() + 6 + gap;
		int starX = 0;
		for (BookPage.Line text : content.getLines())
		{
			if (text.getStars() >= 0)
			{
				starX = Math.max(starX, bodyFont.width(text.getLeft()) + STAR_GAP);
			}
		}
		for (BookPage.Line text : content.getLines())
		{
			if (text.isBalanced())
			{
				List<String> parts = balanced(text.getLeft(), text.isCentred(), width);
				int block = 0;
				for (String part : parts)
				{
					block = Math.max(block, bodyFont.width(part));
				}
				for (String part : parts)
				{
					int x = text.isCentred() ? (width - bodyFont.width(part)) / 2 : (width - block) / 2;
					bodyFont.draw(g, part, x, line, text.isFaded() ? FADED_INK : INK);
					line += lineHeight;
				}
			}
			else if (text.getRight() == null)
			{
				if (text.getLeft().isEmpty())
				{
					line += gap;
				}
				for (String part : wrap(text.getLeft(), bodyFont, width))
				{
					int x = text.isCentred() ? (width - bodyFont.width(part)) / 2 : 0;
					bodyFont.draw(g, part, x, line, text.isFaded() ? FADED_INK : INK);
					if (text.getTooltip() != null)
					{
						tips.put(new Rectangle(x, line, bodyFont.width(part), lineHeight), text.getTooltip());
					}
					line += lineHeight;
				}
			}
			else
			{
				bodyFont.draw(g, text.getLeft(), 0, line, INK);
				bodyFont.draw(g, text.getRight(), width - bodyFont.width(text.getRight()), line, INK);
				drawStars(g, text.getStars(), starX, line + (bodyFont.height() - STAR.length) / 2);
				if (text.getTooltip() != null)
				{
					// The whole row, name to value.
					tips.put(new Rectangle(0, line, width, lineHeight), text.getTooltip());
				}
				line += lineHeight;
			}
		}

		String page = String.valueOf(number);
		// The image runs to the foot of the page so a seal can hang below the number; the number keeps its inset.
		int numberTop = height - NUMBER_INSET - bodyFont.height();
		bodyFont.draw(g, page, (width - bodyFont.width(page)) / 2, numberTop, FADED_INK);

		if (content.getPicture() > 0)
		{
			BufferedImage picture = picture(content.getPicture());
			if (picture != null)
			{
				if (content.isSilhouette())
				{
					picture = faintShape(picture);
				}
				g.drawImage(picture, (width - picture.getWidth()) / 2,
					numberTop - picture.getHeight() - PICTURE_ABOVE_NUMBER, null);
			}
		}

		String signature = content.getSignature();
		if (signature != null)
		{
			// The name centred above the page number, with the seal off to its lower left.
			int nameX = (width - bodyFont.width(signature)) / 2;
			// As high as the middle of a seal standing on the line above the page number.
			int sealHeight = seal == null ? bodyFont.height() : seal.getHeight();
			int nameY = numberTop - lineHeight - sealHeight + (sealHeight - bodyFont.height()) / 2;
			if (seal != null)
			{
				// Kept on the page for long names, and never so low its ribbon tails run off the foot of the page.
				int sealX = Math.max(SEAL_PAGE_EDGE - TEXT_INSET, nameX - SEAL_LEFT_OF_NAME);
				int sealY = Math.min(nameY + SEAL_BELOW_NAME, height - 1 - SEAL_TAIL_LENGTH - seal.getHeight() / 2);
				int middleX = sealX + seal.getWidth() / 2;
				int middleY = sealY + seal.getHeight() / 2;
				// The same slight shadow as the ribbons under the tails and the seal.
				sealTailShadow(g, middleX - SEAL_TAIL_WIDTH - 2, middleY, -SEAL_TAIL_LEAN);
				sealTailShadow(g, middleX, middleY, SEAL_TAIL_LEAN);
				g.drawImage(silhouette(seal, TAB_SHADOW), sealX + TAB_SHADOW_OFFSET, sealY + TAB_SHADOW_OFFSET, null);
				drawSealTail(g, middleX - SEAL_TAIL_WIDTH - 2, middleY, -SEAL_TAIL_LEAN);
				drawSealTail(g, middleX, middleY, SEAL_TAIL_LEAN);
				g.drawImage(seal, sealX, sealY, null);
			}
			bodyFont.draw(g, signature, nameX, nameY, INK);
		}
		g.dispose();
		return image;
	}

	/**
	 * A row's stars for this many milestones: each star in turn goes bronze, silver then gold, and a star not yet
	 * reached isn't drawn.
	 */
	private static void drawStars(Graphics2D g, int reached, int x, int y)
	{
		for (int star = 0; star < STARS; star++)
		{
			int metal = Math.min(reached - star * STAR_METALS.length, STAR_METALS.length) - 1;
			if (metal < 0)
			{
				return;
			}
			int left = x + star * STAR_SPACING;
			for (int row = 0; row < STAR.length; row++)
			{
				for (int column = 0; column < STAR[row].length(); column++)
				{
					if (STAR[row].charAt(column) == '#')
					{
						g.setColor(STAR_METALS[metal][starEdge(row, column) ? 1 : 0]);
						g.fillRect(left + column, y + row, 1, 1);
					}
				}
			}
		}
	}

	/** Whether a star pixel is on its edge, beside a blank pixel or the mask's border. */
	private static boolean starEdge(int row, int column)
	{
		return !starPixel(row - 1, column) || !starPixel(row + 1, column) || !starPixel(row, column - 1)
			|| !starPixel(row, column + 1);
	}

	private static boolean starPixel(int row, int column)
	{
		return row >= 0 && row < STAR.length && column >= 0 && column < STAR[row].length()
			&& STAR[row].charAt(column) == '#';
	}

	/**
	 * Text wrapped so its lines come out about even, each line break starting a new paragraph: of the widths taking no
	 * more lines than the full width, the one leaving the least ragged edge (a paragraph's last line may run up to
	 * half short), the widest on a tie. An entry, left aligned, that would run past its most lines joins its
	 * paragraphs into one.
	 */
	private List<String> balanced(String text, boolean centred, int width)
	{
		if (!centred && wrapAll(text, width).size() > MAX_ENTRY_LINES)
		{
			text = text.replace('\n', ' ');
		}
		List<String> best = wrapAll(text, width);
		int lineCount = best.size();
		long bestCost = Long.MAX_VALUE;
		for (int measure = width; measure > 0; measure--)
		{
			List<List<String>> paragraphs = new ArrayList<>();
			int count = 0;
			for (String paragraph : text.split("\n"))
			{
				List<String> lines = wrap(paragraph, bodyFont, measure);
				paragraphs.add(lines);
				count += lines.size();
			}
			if (count != lineCount)
			{
				break;
			}
			long cost = raggedness(paragraphs);
			if (cost < bestCost)
			{
				bestCost = cost;
				best = new ArrayList<>();
				paragraphs.forEach(best::addAll);
			}
		}
		return best;
	}

	private List<String> wrapAll(String text, int width)
	{
		List<String> lines = new ArrayList<>();
		for (String paragraph : text.split("\n"))
		{
			lines.addAll(wrap(paragraph, bodyFont, width));
		}
		return lines;
	}

	/** How far short of the block's widest line the lines fall, squared and summed. */
	private long raggedness(List<List<String>> paragraphs)
	{
		int block = 0;
		for (List<String> lines : paragraphs)
		{
			for (String line : lines)
			{
				block = Math.max(block, bodyFont.width(line));
			}
		}
		long cost = 0;
		for (List<String> lines : paragraphs)
		{
			for (int i = 0; i < lines.size(); i++)
			{
				long slack = block - bodyFont.width(lines.get(i));
				if (i == lines.size() - 1)
				{
					// A paragraph's last line may run short, but not down to a word or two.
					slack = Math.max(0, slack - block / 2);
				}
				cost += slack * slack;
			}
		}
		return cost;
	}

	/** An item's picture, or null until the item manager has it, when the pages are drawn again. */
	private BufferedImage picture(int itemId)
	{
		BufferedImage picture = pictures.get(itemId);
		if (picture == null && picturesAsked.putIfAbsent(itemId, true) == null)
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(() ->
			{
				pictures.put(itemId, image);
				picturesChanged = true;
			});
		}
		return picture;
	}

	/** The item's own pixels, without its outline or shadow, in faint ink. */
	private static BufferedImage faintShape(BufferedImage picture)
	{
		BufferedImage shape = new BufferedImage(picture.getWidth(), picture.getHeight(), BufferedImage.TYPE_INT_ARGB);
		int ink = SILHOUETTE_ALPHA << 24 | INK.getRGB() & 0xffffff;
		for (int y = 0; y < picture.getHeight(); y++)
		{
			for (int x = 0; x < picture.getWidth(); x++)
			{
				int pixel = picture.getRGB(x, y);
				int rgb = pixel & 0xffffff;
				if (pixel >>> 24 != 0 && rgb != ITEM_SHADOW && rgb != ITEM_OUTLINE)
				{
					shape.setRGB(x, y, ink);
				}
			}
		}
		return shape;
	}

	private static List<String> wrap(String text, QuillFont font, int width)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String tried = line.length() == 0 ? word : line + " " + word;
			if (font.width(tried) > width && line.length() > 0)
			{
				lines.add(line.toString());
				line.setLength(0);
				line.append(word);
			}
			else
			{
				line.setLength(0);
				line.append(tried);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	/** The hold's close button: the one widget in its frame with a Close action. */
	private static Widget findClose(Widget widget, int depth)
	{
		String[] actions = widget.getActions();
		if (actions != null)
		{
			for (String action : actions)
			{
				if (CLOSE_ACTION.equals(action))
				{
					return widget;
				}
			}
		}
		if (depth > 4)
		{
			return null;
		}
		for (Widget[] children : new Widget[][]{widget.getDynamicChildren(), widget.getStaticChildren(),
			widget.getNestedChildren()})
		{
			for (Widget child : children == null ? new Widget[0] : children)
			{
				Widget found = child == null ? null : findClose(child, depth + 1);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	/** Repeats an image over an area, cutting the last copies short where they overrun it. */
	private static void tile(Graphics2D graphics, BufferedImage image, int x, int y, int width, int height)
	{
		int w = image.getWidth();
		int h = image.getHeight();
		for (int ty = 0; ty < height; ty += h)
		{
			for (int tx = 0; tx < width; tx += w)
			{
				int cw = Math.min(w, width - tx);
				int ch = Math.min(h, height - ty);
				graphics.drawImage(image, x + tx, y + ty, x + tx + cw, y + ty + ch, 0, 0, cw, ch, null);
			}
		}
	}

	/**
	 * Once a game tick while the hold is open, drops the built book if any sprite's resource pack replacement is not
	 * the one it was built from, so it is built again from what the game now draws. Client thread only.
	 */
	private void forgetChangedSprites()
	{
		int tick = client.getTickCount();
		if (frame == null || tick == overridesCheckedTick)
		{
			return;
		}
		overridesCheckedTick = tick;
		Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		for (Map.Entry<Integer, SpritePixels> used : overridesUsed.entrySet())
		{
			if (overrides.get(used.getKey()) != used.getValue())
			{
				log.debug("Hold book sprite {} changed by a resource pack; rebuilding", used.getKey());
				frame = null;
				spritesTriedTick = -1;
				overridesUsed.clear();
				return;
			}
		}
	}

	/** Reads the sprites the first time they are all there and builds the book's frame. Client thread only. */
	private boolean loadSprites()
	{
		if (frame != null)
		{
			return true;
		}
		int tick = client.getTickCount();
		if (tick == spritesTriedTick)
		{
			return false;
		}
		spritesTriedTick = tick;
		BufferedImage[] book = new BufferedImage[12];
		int[] ids = {CORNER_TOP_LEFT, EDGE_TOP, CLASP_TOP, CORNER_TOP_RIGHT, EDGE_LEFT, PAGE, SPINE, EDGE_RIGHT,
			CORNER_BOTTOM_LEFT, EDGE_BOTTOM, CLASP_BOTTOM, CORNER_BOTTOM_RIGHT};
		for (int i = 0; i < ids.length; i++)
		{
			book[i] = sprite(ids[i]);
		}
		BufferedImage left = sprite(ARROW_LEFT);
		BufferedImage right = sprite(ARROW_RIGHT);
		BufferedImage cross = sprite(CLOSE);
		BufferedImage crossHovered = sprite(CLOSE_HOVERED);
		// The button is two sprites drawn as one, so it always uses the game's own: a pack replacing only one of them
		// (often the skill icon) leaves a fish that doesn't match its book.
		BufferedImage buttonBook = sprite(BUTTON_BOOK, false);
		BufferedImage buttonFish = sprite(BUTTON_FISH, false);
		QuillFont body = QuillFont.load(client, BODY_FONT);
		QuillFont titles = QuillFont.load(client, TITLE_FONT);
		if (body == null || titles == null || buttonBook == null || buttonFish == null || anyMissing(book) || left == null
			|| right == null || cross == null || crossHovered == null)
		{
			if (!spritesMissingLogged)
			{
				log.debug("Hold book sprites not all loaded yet; trying again each game tick");
				spritesMissingLogged = true;
			}
			return false;
		}

		BufferedImage built = new BufferedImage(BOOK_WIDTH, BOOK_HEIGHT, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = built.createGraphics();
		int right34 = BOOK_WIDTH - TILE;
		int bottom34 = BOOK_HEIGHT - TILE;
		int middle = (COLUMNS / 2) * TILE;
		tile(g, book[5], TILE, TILE, BOOK_WIDTH - 2 * TILE, BOOK_HEIGHT - 2 * TILE);
		tile(g, book[6], middle, TILE, TILE, BOOK_HEIGHT - 2 * TILE);
		tile(g, book[1], TILE, 0, middle - TILE, TILE);
		tile(g, book[1], middle + TILE, 0, right34 - middle - TILE, TILE);
		tile(g, book[9], TILE, bottom34, middle - TILE, TILE);
		tile(g, book[9], middle + TILE, bottom34, right34 - middle - TILE, TILE);
		tile(g, book[4], 0, TILE, TILE, BOOK_HEIGHT - 2 * TILE);
		tile(g, book[7], right34, TILE, TILE, BOOK_HEIGHT - 2 * TILE);
		g.drawImage(book[0], 0, 0, null);
		g.drawImage(book[3], right34, 0, null);
		g.drawImage(book[8], 0, bottom34, null);
		g.drawImage(book[11], right34, bottom34, null);
		g.drawImage(book[2], middle, 0, null);
		g.drawImage(book[10], middle, bottom34, null);
		g.dispose();

		BufferedImage button = new BufferedImage(buttonBook.getWidth(), buttonBook.getHeight(), BufferedImage.TYPE_INT_ARGB);
		Graphics2D b = button.createGraphics();
		b.drawImage(buttonBook, 0, 0, null);
		BufferedImage fishOnly = trim(buttonFish, new Rectangle(0, FISH_TOP, buttonFish.getWidth(),
			buttonFish.getHeight() - FISH_TOP));
		BufferedImage fish = shrunk(trimmed(fishOnly), FISH_SIZE);
		b.drawImage(fish, (int) Math.round(BUTTON_COVER_X - fish.getWidth() / 2.0) + FISH_NUDGE_X,
			(int) Math.round(BUTTON_COVER_Y - fish.getHeight() / 2.0) + FISH_NUDGE_Y, null);
		b.dispose();
		// Cut down to their visible pixels, so they sit by what shows rather than by their transparent padding.
		arrowLeft = trimmed(left);
		arrowRight = trimmed(right);
		Rectangle crossShows = visible(cross).union(visible(crossHovered));
		close = trim(cross, crossShows);
		closeHovered = trim(crossHovered, crossShows);
		icon = button;
		iconHovered = brighter(button, HOVER_BRIGHTNESS);
		BufferedImage waxSeal = sprite(SEAL);
		// The Fishing icon pressed into it is the game's own, hook and all, whatever a resource pack does.
		seal = waxSeal == null ? null
			: imprinted(saturated(trimmed(waxSeal), SEAL_SATURATION), trimmed(buttonFish));
		cover = buildCover(built, titles);
		// Pages already drawn are drawn again, with the new sprites.
		pageImages.clear();
		pageTips.clear();
		pagesDrawn.clear();
		bodyFont = body;
		titleFont = titles;
		frame = built;
		return true;
	}

	/**
	 * The front cover, in the leather colours of the frame's right edge: a darker hinge along the spine, a beveled
	 * edge, a tooled panel, the frame's own corner pieces at the fore edge and the title in gold leaf.
	 */
	private BufferedImage buildCover(BufferedImage book, QuillFont titles)
	{
		int w = COVER_WIDTH;
		int h = BOOK_HEIGHT;
		// Read across the frame's right edge at its middle: its leather, the leather's highlight, then its outline.
		int middle = BOOK_HEIGHT / 2;
		Color leather = new Color(book.getRGB(BOOK_WIDTH - 5, middle));
		Color light = new Color(book.getRGB(BOOK_WIDTH - 3, middle));
		Color outline = new Color(book.getRGB(BOOK_WIDTH - 2, middle));
		Color dark = new Color((int) (leather.getRed() * COVER_DARKER), (int) (leather.getGreen() * COVER_DARKER),
			(int) (leather.getBlue() * COVER_DARKER));
		BufferedImage built = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = built.createGraphics();
		g.setColor(leather);
		g.fillRect(0, 0, w, h);
		g.setColor(dark);
		g.fillRect(0, 0, COVER_HINGE, h);
		g.drawLine(0, h - 2, w - 2, h - 2);
		g.setColor(light);
		g.drawLine(COVER_HINGE, 1, COVER_HINGE, h - 2);
		g.drawLine(0, 1, w - 2, 1);
		g.drawLine(w - 2, 1, w - 2, h - 2);
		g.setColor(outline);
		g.drawRect(0, 0, w - 1, h - 1);

		// A groove: a dark line with a light one just below and right of it.
		int panelLeft = COVER_HINGE + COVER_PANEL_INSET;
		int panelWidth = w - panelLeft - COVER_PANEL_INSET - 1;
		int panelHeight = h - 2 * COVER_PANEL_INSET - 1;
		g.setColor(dark);
		g.drawRect(panelLeft, COVER_PANEL_INSET, panelWidth, panelHeight);
		g.setColor(light);
		g.drawRect(panelLeft + 1, COVER_PANEL_INSET + 1, panelWidth, panelHeight);

		// The frame's green corner pieces, where the cover's corners lie on the open book.
		for (int corner : new int[]{0, h - TILE})
		{
			for (int fy = corner; fy < corner + TILE; fy++)
			{
				for (int fx = BOOK_WIDTH - TILE; fx < BOOK_WIDTH; fx++)
				{
					int pixel = book.getRGB(fx, fy);
					int r = pixel >> 16 & 0xff;
					int gr = pixel >> 8 & 0xff;
					int b = pixel & 0xff;
					if ((pixel >>> 24) != 0 && gr > r + 8 && gr > b)
					{
						built.setRGB(fx - (BOOK_WIDTH - w), fy, pixel);
					}
				}
			}
		}

		int middleX = (w + COVER_HINGE) / 2;
		int titleX = middleX - titles.width(COVER_TITLE) / 2;
		titles.draw(g, COVER_TITLE, titleX + 1, COVER_TITLE_Y + 1, outline);
		titles.draw(g, COVER_TITLE, titleX, COVER_TITLE_Y, GOLD_LEAF);
		g.dispose();
		return built;
	}

	/** One ribbon tail from behind the seal: its top left corner, leaning this far sideways by its notched end. */
	private static void drawSealTail(Graphics2D g, int x, int y, int lean)
	{
		int[] xs = sealTailXs(x, lean);
		int[] ys = sealTailYs(y);
		g.setColor(SEAL_TAIL);
		g.fillPolygon(xs, ys, xs.length);
		g.setColor(SEAL_TAIL_EDGE);
		g.drawPolygon(xs, ys, xs.length);
	}

	private static int[] sealTailXs(int x, int lean)
	{
		return new int[]{x, x + SEAL_TAIL_WIDTH, x + SEAL_TAIL_WIDTH + lean, x + lean + SEAL_TAIL_WIDTH / 2, x + lean};
	}

	private static int[] sealTailYs(int y)
	{
		int bottom = y + SEAL_TAIL_LENGTH;
		return new int[]{y, y, bottom, bottom - SEAL_TAIL_NOTCH, bottom};
	}

	/** A seal tail's shadow, its outline included. */
	private static void sealTailShadow(Graphics2D g, int x, int y, int lean)
	{
		int[] xs = sealTailXs(x, lean);
		int[] ys = sealTailYs(y);
		dropShadow(g, xs, ys);
		g.translate(TAB_SHADOW_OFFSET, TAB_SHADOW_OFFSET);
		g.drawPolygon(xs, ys, xs.length);
		g.translate(-TAB_SHADOW_OFFSET, -TAB_SHADOW_OFFSET);
	}

	/** A shape's slight shadow, down and to the right, left in the shadow colour. */
	private static void dropShadow(Graphics2D g, int[] xs, int[] ys)
	{
		g.setColor(TAB_SHADOW);
		g.translate(TAB_SHADOW_OFFSET, TAB_SHADOW_OFFSET);
		g.fillPolygon(xs, ys, xs.length);
		g.translate(-TAB_SHADOW_OFFSET, -TAB_SHADOW_OFFSET);
	}

	/** An image's shape in one colour, for its shadow. */
	private static BufferedImage silhouette(BufferedImage image, Color colour)
	{
		BufferedImage shape = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int alpha = image.getRGB(x, y) >>> 24;
				if (alpha != 0)
				{
					shape.setRGB(x, y, alpha * colour.getAlpha() / 255 << 24 | colour.getRGB() & 0xffffff);
				}
			}
		}
		return shape;
	}

	/**
	 * The seal with the fish pressed into its middle, drawn into it: shrunk, then each of its pixels drawn in the colour
	 * of the seal beneath, darker or lighter by how dark or light the icon is there, so it reads as a stamped impression.
	 */
	private static BufferedImage imprinted(BufferedImage seal, BufferedImage fish)
	{
		BufferedImage icon = shrunk(fish, SEAL_FISH_SIZE);
		int left = (int) Math.round(SEAL_RING_X - icon.getWidth() / 2.0);
		int top = (int) Math.round(SEAL_RING_Y - icon.getHeight() / 2.0);
		Color rim = sealColour(seal, true);
		Color shadow = sealColour(seal, false);
		float[] hsb = new float[3];
		for (int y = 0; y < icon.getHeight(); y++)
		{
			for (int x = 0; x < icon.getWidth(); x++)
			{
				int pixel = icon.getRGB(x, y);
				float alpha = (pixel >>> 24) / 255f;
				if (alpha == 0 || !inside(seal, left + x, top + y))
				{
					continue;
				}
				Color.RGBtoHSB(pixel >> 16 & 0xff, pixel >> 8 & 0xff, pixel & 0xff, hsb);
				float shade = SEAL_FISH_SHADE_DARK + (SEAL_FISH_SHADE_LIGHT - SEAL_FISH_SHADE_DARK) * hsb[2];
				int under = seal.getRGB(left + x, top + y);
				int r = blend(under >> 16 & 0xff, shade, alpha);
				int gr = blend(under >> 8 & 0xff, shade, alpha);
				int b = blend(under & 0xff, shade, alpha);
				seal.setRGB(left + x, top + y, under & 0xff000000 | r << 16 | gr << 8 | b);
			}
		}
		for (int y = 0; y < icon.getHeight(); y++)
		{
			for (int x = 0; x < icon.getWidth(); x++)
			{
				if (!fishAt(icon, x, y))
				{
					continue;
				}
				if (!fishAt(icon, x + 1, y + 1))
				{
					edge(seal, left + x + 1, top + y + 1, rim);
				}
				if (!fishAt(icon, x - 1, y - 1))
				{
					edge(seal, left + x, top + y, shadow);
				}
			}
		}
		return seal;
	}

	private static boolean inside(BufferedImage image, int x, int y)
	{
		return x >= 0 && y >= 0 && x < image.getWidth() && y < image.getHeight();
	}

	/** The seal's brightest or darkest colour, among those making up a fair share of it. */
	private static Color sealColour(BufferedImage seal, boolean brightest)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		int total = 0;
		for (int y = 0; y < seal.getHeight(); y++)
		{
			for (int x = 0; x < seal.getWidth(); x++)
			{
				int pixel = seal.getRGB(x, y);
				if ((pixel >>> 24) == 0xff)
				{
					counts.merge(pixel & 0xffffff, 1, Integer::sum);
					total++;
				}
			}
		}
		int best = -1;
		float bestBrightness = brightest ? -1 : 2;
		float[] hsb = new float[3];
		for (Map.Entry<Integer, Integer> colour : counts.entrySet())
		{
			if (colour.getValue() < total * SEAL_COLOUR_SHARE)
			{
				continue;
			}
			int rgb = colour.getKey();
			Color.RGBtoHSB(rgb >> 16 & 0xff, rgb >> 8 & 0xff, rgb & 0xff, hsb);
			if (brightest ? hsb[2] > bestBrightness : hsb[2] < bestBrightness)
			{
				bestBrightness = hsb[2];
				best = rgb;
			}
		}
		return new Color(best < 0 ? 0 : best);
	}

	/** Whether the shrunk icon is solid enough at a pixel to count as the fish; outside it never is. */
	private static boolean fishAt(BufferedImage icon, int x, int y)
	{
		return inside(icon, x, y) && (icon.getRGB(x, y) >>> 24) >= SEAL_FISH_SOLID;
	}

	/** Sets a pixel of the seal to an emboss edge's colour, if there is wax there. */
	private static void edge(BufferedImage seal, int x, int y, Color colour)
	{
		if (inside(seal, x, y) && (seal.getRGB(x, y) >>> 24) != 0)
		{
			seal.setRGB(x, y, seal.getRGB(x, y) & 0xff000000 | colour.getRGB() & 0xffffff);
		}
	}

	/** A colour channel shaded by a factor, mixed over itself by alpha. */
	private static int blend(int channel, float shade, float alpha)
	{
		float shaded = Math.min(255, channel * shade);
		return Math.round(channel + (shaded - channel) * alpha);
	}

	/** A copy with every pixel's saturation scaled, capped at full, keeping its hue, brightness and alpha. */
	private static BufferedImage saturated(BufferedImage image, float scale)
	{
		BufferedImage out = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		float[] hsb = new float[3];
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int argb = image.getRGB(x, y);
				Color.RGBtoHSB(argb >> 16 & 0xff, argb >> 8 & 0xff, argb & 0xff, hsb);
				int rgb = Color.HSBtoRGB(hsb[0], Math.min(1f, hsb[1] * scale), hsb[2]);
				out.setRGB(x, y, argb & 0xff000000 | rgb & 0xffffff);
			}
		}
		return out;
	}

	/** Shrunk to the given size on its longer side, averaging pixels rather than dropping them. */
	private static BufferedImage shrunk(BufferedImage image, int size)
	{
		double scale = (double) size / Math.max(image.getWidth(), image.getHeight());
		if (scale >= 1)
		{
			return image;
		}
		Image scaled = image.getScaledInstance((int) Math.round(image.getWidth() * scale),
			(int) Math.round(image.getHeight() * scale), Image.SCALE_AREA_AVERAGING);
		BufferedImage done = new BufferedImage(scaled.getWidth(null), scaled.getHeight(null), BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = done.createGraphics();
		g.drawImage(scaled, 0, 0, null);
		g.dispose();
		return done;
	}

	/** A copy with every colour scaled up by the given factor, keeping how see-through each pixel is. */
	private static BufferedImage brighter(BufferedImage image, float factor)
	{
		BufferedImage lit = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				int argb = image.getRGB(x, y);
				int r = Math.min(255, Math.round(((argb >> 16) & 0xff) * factor));
				int g = Math.min(255, Math.round(((argb >> 8) & 0xff) * factor));
				int bl = Math.min(255, Math.round((argb & 0xff) * factor));
				lit.setRGB(x, y, (argb & 0xff000000) | r << 16 | g << 8 | bl);
			}
		}
		return lit;
	}

	/** The smallest area holding every pixel that isn't fully see-through; the whole image if there are none. */
	private static Rectangle visible(BufferedImage image)
	{
		int left = image.getWidth();
		int top = image.getHeight();
		int right = -1;
		int bottom = -1;
		for (int y = 0; y < image.getHeight(); y++)
		{
			for (int x = 0; x < image.getWidth(); x++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					left = Math.min(left, x);
					top = Math.min(top, y);
					right = Math.max(right, x);
					bottom = Math.max(bottom, y);
				}
			}
		}
		return right < 0 ? new Rectangle(0, 0, image.getWidth(), image.getHeight())
			: new Rectangle(left, top, right - left + 1, bottom - top + 1);
	}

	/** Cut down to its visible pixels. */
	private static BufferedImage trimmed(BufferedImage image)
	{
		return trim(image, visible(image));
	}

	private static BufferedImage trim(BufferedImage image, Rectangle area)
	{
		Rectangle inside = area.intersection(new Rectangle(0, 0, image.getWidth(), image.getHeight()));
		return image.getSubimage(inside.x, inside.y, inside.width, inside.height);
	}

	private static boolean anyMissing(BufferedImage[] images)
	{
		for (BufferedImage image : images)
		{
			if (image == null)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * A sprite at its full size, with the transparent space around it that the cache trims off put back, so pieces
	 * line up as the game lays them out. A resource pack's replacement is used where there is one, if the book is set to
	 * follow resource packs.
	 */
	private BufferedImage sprite(int id)
	{
		return sprite(id, config.bookResourcePacks());
	}

	/** Builds the book again from its sprites, for when resource packs are switched on or off for it. */
	void rebuildSprites()
	{
		frame = null;
		spritesTriedTick = -1;
		overridesUsed.clear();
	}

	/** As {@link #sprite(int)}, but with packs left out when asked: then always the game's own sprite. */
	private BufferedImage sprite(int id, boolean followPacks)
	{
		SpritePixels pixels = null;
		if (followPacks)
		{
			pixels = client.getSpriteOverrides().get(id);
			overridesUsed.put(id, pixels);
		}
		if (pixels == null)
		{
			SpritePixels[] loaded = client.getSprites(client.getIndexSprites(), id, 0);
			pixels = loaded == null || loaded.length == 0 ? null : loaded[0];
		}
		if (pixels == null || pixels.getWidth() <= 0 || pixels.getHeight() <= 0)
		{
			return null;
		}
		int width = Math.max(pixels.getMaxWidth(), pixels.getOffsetX() + pixels.getWidth());
		int height = Math.max(pixels.getMaxHeight(), pixels.getOffsetY() + pixels.getHeight());
		BufferedImage full = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = full.createGraphics();
		g.drawImage(pixels.toBufferedImage(), pixels.getOffsetX(), pixels.getOffsetY(), null);
		g.dispose();
		return full;
	}

	private void forgetBounds()
	{
		buttonBounds = null;
		forgetBookBounds();
	}

	/** Forgets where the open book's parts were drawn, leaving the button's. */
	private void forgetBookBounds()
	{
		bookBounds = null;
		closeBounds = null;
		leftBounds = null;
		rightBounds = null;
		bookmarkBounds = null;
		tabBounds = Collections.emptyMap();
	}

	/** The page the section tab under the mouse leads to, or -1 for none. */
	private int tabUnder(MouseEvent event)
	{
		for (Map.Entry<Rectangle, Integer> tab : tabBounds.entrySet())
		{
			if (tab.getKey().contains(event.getPoint()))
			{
				return tab.getValue();
			}
		}
		return -1;
	}

	private static boolean inside(Rectangle bounds, MouseEvent event)
	{
		return bounds != null && bounds.contains(event.getPoint());
	}

	/** Whether the book's button shows under a point on the canvas, not hidden behind the open book. */
	boolean overButton(int x, int y)
	{
		Rectangle button = buttonBounds;
		Rectangle book = bookBounds;
		return button != null && button.contains(x, y) && !(open && book != null && book.contains(x, y));
	}

	/**
	 * The mouse, handled as the Hub's Gauntlet Chest Popup handles its popup. Only left presses count, and none while
	 * the game's right-click menu is open (as of the last frame drawn), so picking a menu option over the book still
	 * reaches the game. A left press on the button or anywhere on the open book is acted on and kept from the game;
	 * one out in the world (where the game offers walking) closes the book and still reaches the game. Releases,
	 * clicks and right presses always reach it, so right-clicking the book shows the game's menu for whatever is under
	 * it.
	 */
	final MouseListener mouse = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent event)
		{
			if (!SwingUtilities.isLeftMouseButton(event) || menuOpen)
			{
				return event;
			}
			// The open book covers the button wherever they overlap.
			if (inside(buttonBounds, event) && !(open && inside(bookBounds, event)))
			{
				if (open)
				{
					setOpen(false);
				}
				else
				{
					anywhere = false;
					openBook();
				}
				event.consume();
			}
			else if (open && (inside(bookBounds, event) || tabUnder(event) >= 0))
			{
				int tab = tabUnder(event);
				if (tab >= 0)
				{
					// To the spread the section's first page is on.
					int from = Math.min(spread, lastSpread(pages.size()));
					turn(from, Math.min(tab - tab % 2, lastSpread(pages.size())));
				}
				else if (inside(closeBounds, event))
				{
					setOpen(false);
				}
				else if (inside(leftBounds, event))
				{
					int from = Math.min(spread, lastSpread(pages.size()));
					turn(from, Math.max(0, from - 2));
				}
				else if (inside(rightBounds, event))
				{
					int from = Math.min(spread, lastSpread(pages.size()));
					turn(from, Math.min(from + 2, lastSpread(pages.size())));
				}
				else if (inside(bookmarkBounds, event))
				{
					toggleBookmark();
				}
				event.consume();
			}
			else if (open && overWorld)
			{
				setOpen(false);
			}
			return event;
		}
	};

	/** Bookmarks the spread showing, or takes the bookmark off it if it is the one marked. */
	private void toggleBookmark()
	{
		int first = Math.min(spread, lastSpread(pages.size()));
		int marked = bookmarkedSpread() == first ? -1 : first;
		bookmark = marked;
		if (marked < 0)
		{
			configManager.unsetConfiguration(TrawlingPlusConfig.GROUP, BOOKMARK_KEY);
		}
		else
		{
			configManager.setConfiguration(TrawlingPlusConfig.GROUP, BOOKMARK_KEY, marked);
		}
	}

	/** Whether the game offers walking under the mouse, by its type, so other plugins renaming it don't matter. */
	private boolean walkingUnderMouse()
	{
		for (MenuEntry entry : client.getMenu().getMenuEntries())
		{
			if (entry.getType() == MenuAction.WALK)
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public void keyTyped(KeyEvent event)
	{
	}

	/** Escape closes the book and still reaches the game, as with Gauntlet Chest Popup. */
	@Override
	public void keyPressed(KeyEvent event)
	{
		if (open && event.getKeyCode() == KeyEvent.VK_ESCAPE)
		{
			setOpen(false);
		}
	}

	@Override
	public void keyReleased(KeyEvent event)
	{
	}
}

package com.trawlingplus;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import net.runelite.api.Client;
import net.runelite.api.Point;

/**
 * Draws routes onto a map, wherever that map happens to be and at whatever scale it is drawn. Shared
 * by the minimap and the world map, which work out where a tile lands in entirely different ways.
 */
final class MapRoutes
{
	// The shape of an arrowhead on a map: half its width, and how far its back edge is notched in, as
	// fractions of its length. The length is given in pixels rather than tiles, since a map is drawn at
	// whatever scale it likes and an arrow has to stay big enough to make out without swamping the line.
	private static final double ARROW_HALF_WIDTH = 0.4;
	private static final double ARROW_NOTCH = 0.25;

	// No two arrows closer together than this on screen. Arrows sit a fixed number of tiles apart, so
	// without this they would pile into each other as a map is zoomed out. How many to leave out is
	// worked out from how far the map is zoomed, never from which of them happen to be on screen: a
	// thinning that depends on what is visible rearranges itself every time the map is panned.
	private static final int ARROW_GAP = 24;

	// How far along the route to look to see which way an arrow points, in tiles.
	private static final double ARROW_AIM = 2;

	// About how far apart the points of the drawn line should be on screen, in pixels. Closer than this
	// and they land on top of each other; further apart and a bend starts to show as a cut corner.
	private static final double LINE_STEP = 2;

	private MapRoutes()
	{
	}

	/**
	 * Turns world tile coordinates into a place on whichever map is being drawn, or null when they
	 * fall outside it.
	 */
	interface Projection
	{
		Point at(double x, double y);
	}

	/**
	 * A colour made as see-through as another.
	 */
	static Color withAlphaOf(Color colour, Color like)
	{
		return new Color(colour.getRed(), colour.getGreen(), colour.getBlue(), like.getAlpha());
	}

	/**
	 * Every so many of the route's points, chosen from how far the map is zoomed. A fixed number of
	 * them cuts the corners once the map is zoomed in far enough to see it, and wastes the work of
	 * placing points on top of each other once it is zoomed out.
	 */
	private static int stride(ShoalRoute route, double pixelsPerTile)
	{
		if (pixelsPerTile <= 0 || route.sampleCount() == 0)
		{
			return 1;
		}
		double apart = route.length() / route.sampleCount();
		return Math.max(1, (int) (LINE_STEP / (pixelsPerTile * apart)));
	}

	/**
	 * One route as a line, broken wherever it leaves the map. With a danger colour, the stretches that pass close to
	 * where sea creatures that attack boats spawn are drawn in it instead, each stretch drawn once in one colour.
	 */
	static void route(Graphics2D graphics, TrawlingPlusConfig config, ShoalRoute route, Projection onto,
		int thickness, double pixelsPerTile, double fromX, double fromY, double toX, double toY, Color dangerColour)
	{
		int stride = stride(route, pixelsPerTile);
		boolean withDanger = dangerColour != null && route.hasDanger();
		Path2D line = new Path2D.Double();
		Path2D danger = withDanger ? new Path2D.Double() : null;
		// Whether the last point placed is on the map, and which of the two paths it went into.
		boolean drawing = false;
		boolean wasDangerous = false;
		for (int block = 0; block < route.blockCount(); block++)
		{
			// Only the runs of the route that reach what is being shown. Most of a route is somewhere
			// else entirely, and a run is dismissed in four comparisons rather than by placing all the
			// points inside it and throwing them away one at a time.
			if (!route.blockWithin(block, fromX, fromY, toX, toY))
			{
				drawing = false;
				continue;
			}

			int start = route.blockFrom(block);
			for (int sample = start + (stride - start % stride) % stride; sample < route.blockTo(block);
				sample += stride)
			{
				Point at = onto.at(route.sampleX(sample), route.sampleY(sample));
				if (at == null)
				{
					// Off the map, so the line picks up again where it comes back.
					drawing = false;
					continue;
				}

				boolean dangerous = withDanger && route.dangerAt(sample);
				Path2D into = dangerous ? danger : line;
				if (drawing && dangerous != wasDangerous)
				{
					// The colour changes here: the last piece stays in the old colour, and the new one starts at
					// this point, so the two meet without a gap.
					(wasDangerous ? danger : line).lineTo(at.getX(), at.getY());
					into.moveTo(at.getX(), at.getY());
				}
				else if (drawing)
				{
					into.lineTo(at.getX(), at.getY());
				}
				else
				{
					into.moveTo(at.getX(), at.getY());
					drawing = true;
				}
				wasDangerous = dangerous;
			}
		}

		graphics.setStroke(new BasicStroke(thickness));
		graphics.setColor(config.routeColour());
		graphics.draw(line);
		if (danger != null)
		{
			graphics.setColor(dangerColour);
			graphics.draw(danger);
		}
	}

	/**
	 * The arrows showing which way round a route is swum, at the spacing set for the ones on the water
	 * but thinned out so they never crowd each other on a map drawn small. Those on a stretch marked
	 * dangerous take the danger colour instead, when one is given.
	 */
	static void arrows(Graphics2D graphics, TrawlingPlusConfig config, ShoalRoute route, Projection onto,
		int size, double pixelsPerTile, double fromX, double fromY, double toX, double toY, Color dangerColour)
	{
		if (!config.showDirectionArrows())
		{
			return;
		}

		int spacing = Math.max(TrawlingPlusConfig.MIN_ARROW_SPACING,
			Math.min(TrawlingPlusConfig.MAX_ARROW_SPACING, config.directionArrowSpacing()));

		// Every so many of the arrows, chosen so that what is left of them is far enough apart on screen.
		// They then sit at fixed places round the route and stay put however the map is moved about.
		int every = 1;
		if (pixelsPerTile > 0)
		{
			every = Math.max(1, (int) Math.ceil(ARROW_GAP / pixelsPerTile / spacing));
		}

		double apart = (double) every * spacing;
		Color arrowColour = config.directionArrowColour();
		// Read the same way the line is coloured, through the same thinned points.
		int stride = stride(route, pixelsPerTile);
		for (int block = 0; block < route.blockCount(); block++)
		{
			// The same skipping the line is drawn with. A run of the route covers one stretch of the way
			// round it, so the arrows on it are the ones whose distances fall inside that stretch, and the
			// rest are passed over without ever being worked out.
			if (!route.blockWithin(block, fromX, fromY, toX, toY))
			{
				continue;
			}

			double opens = route.sampleDistance(route.blockFrom(block));
			double closes = route.blockTo(block) < route.sampleCount()
				? route.sampleDistance(route.blockTo(block)) : route.length();

			for (int arrow = Math.max(1, (int) Math.ceil(opens / apart)); arrow * apart < closes; arrow++)
			{
				double[] point = route.pointAt(arrow * apart);
				if (point[0] < fromX || point[0] > toX || point[1] < fromY || point[1] > toY)
				{
					// Inside a run that reaches the map, but not itself on the part of it being shown.
					continue;
				}

				Point at = onto.at(point[0], point[1]);
				if (at == null)
				{
					continue;
				}

				// Which way the arrow points is read from a second place further along the route. That one
				// can be off the map while the arrow itself is on it, which happens along the edge once the
				// map is zoomed in far enough for a couple of tiles to be a long way across the screen, so
				// the place behind the arrow is taken instead and the direction turned around.
				Point ahead = onto.at(point[0] + point[2] * ARROW_AIM, point[1] + point[3] * ARROW_AIM);
				Point from = ahead != null ? at
					: onto.at(point[0] - point[2] * ARROW_AIM, point[1] - point[3] * ARROW_AIM);
				Point to = ahead != null ? ahead : at;
				if (from == null || to == null || (to.getX() == from.getX() && to.getY() == from.getY()))
				{
					// Neither way along the route could be placed, or both ends landed on the same pixel and
					// there is no direction to read from them.
					continue;
				}

				// An arrow on a stretch drawn red is red too, so it doesn't break the stretch up.
				graphics.setColor(dangerColour != null && route.dangerAtDistance(arrow * apart, stride) ? dangerColour : arrowColour);
				graphics.fill(arrowhead(at, to.getX() - from.getX(), to.getY() - from.getY(), size));
			}
		}
	}

	/**
	 * Where a shoal is right now, as a dot in the colour that marks it on the water.
	 */
	static void shoal(Graphics2D graphics, TrawlingPlusConfig config, Client client, Shoal shoal,
		Projection onto, int size)
	{
		double[] swimming = shoal.position(client);
		Point at = swimming == null ? null : onto.at(swimming[0], swimming[1]);
		if (at == null)
		{
			return;
		}

		graphics.setColor(config.shoalHeadingArrowColour());
		graphics.fillOval(at.getX() - size, at.getY() - size, size * 2, size * 2);
		// Outlined, so it stays visible whatever the map underneath it is coloured.
		graphics.setColor(Color.BLACK);
		graphics.setStroke(new BasicStroke(1));
		graphics.drawOval(at.getX() - size, at.getY() - size, size * 2, size * 2);
	}

	/**
	 * An arrowhead of the given length in pixels, centred on a point and pointing along a direction, which needn't be
	 * of any particular length but mustn't be nothing. Turned by the direction itself rather than by an angle worked
	 * out from it and back.
	 */
	private static Path2D arrowhead(Point at, double towardX, double towardY, int length)
	{
		double size = Math.sqrt(towardX * towardX + towardY * towardY);
		double sin = towardY / size;
		double cos = towardX / size;
		double half = length * ARROW_HALF_WIDTH;
		double notch = length * ARROW_NOTCH;

		// Along the arrow, then across it, for the tip, both barbs and the notch between them.
		double[][] corners = {{length / 2.0, 0}, {-length / 2.0, half}, {-length / 2.0 + notch, 0},
			{-length / 2.0, -half}};
		Path2D head = new Path2D.Double();
		for (int corner = 0; corner < corners.length; corner++)
		{
			double x = at.getX() + corners[corner][0] * cos - corners[corner][1] * sin;
			double y = at.getY() + corners[corner][0] * sin + corners[corner][1] * cos;
			if (corner == 0)
			{
				head.moveTo(x, y);
			}
			else
			{
				head.lineTo(x, y);
			}
		}
		head.closePath();
		return head;
	}
}

package com.trawlingplus;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines the ocean encounters picked in the settings.
 */
class OceanEncounterOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 2;

	private final OceanEncounters encounters;
	private final TrawlingPlusConfig config;
	private final ModelOutlineRenderer outlineRenderer;

	@Inject
	OceanEncounterOverlay(OceanEncounters encounters, TrawlingPlusConfig config, ModelOutlineRenderer outlineRenderer)
	{
		this.encounters = encounters;
		this.config = config;
		this.outlineRenderer = outlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<NPC> shown = encounters.shown();
		if (shown.isEmpty())
		{
			return null;
		}
		Color colour = config.encounterColour();
		for (NPC npc : shown)
		{
			outlineRenderer.drawOutline(npc, OUTLINE_WIDTH, colour, OUTLINE_FEATHER);
		}
		return null;
	}
}

package com.trawlingplus;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.WorldView;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.gameval.NpcID;
import net.runelite.client.Notifier;
import net.runelite.client.config.Notification;
import net.runelite.client.eventbus.Subscribe;

/**
 * Finds the giant clams, lost crates, lost caskets and clue turtles that surface around a moving boat, keeps the
 * ones picked in the settings for the outline, and notifies of each once. It only reads; nothing is sent to the game.
 */
@Singleton
class OceanEncounters
{
	// Lowest tier first, in the order of the settings' tiers.
	private static final int[] CRATES = {
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_WOOD,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_OAK,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_TEAK,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_MAHOGANY,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_CAMPHOR,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_IRONWOOD,
	};
	private static final int[] CASKETS = {
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_CASKET_BEGINNER,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_CASKET_EASY,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_CASKET_MEDIUM,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_CASKET_HARD,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_CASKET_ELITE,
		NpcID.SAILING_CHANCE_ENCOUNTER_LOST_GOODS_CASKET_MASTER,
	};

	private static final TrawlingPlusConfig.CrateTier[] CRATE_TIERS = TrawlingPlusConfig.CrateTier.values();
	private static final TrawlingPlusConfig.CasketTier[] CASKET_TIERS = TrawlingPlusConfig.CasketTier.values();

	private final Client client;
	private final TrawlingPlusConfig config;
	private final Notifier notifier;

	// Every encounter in the scene.
	private final Set<NPC> seen = new HashSet<>();
	// Those already notified of, so each notifies once.
	private final Set<NPC> notified = new HashSet<>();
	// Those picked in the settings, worked out once a tick, for the outline; two lists reused in turn.
	private List<NPC> shown = new ArrayList<>();
	private List<NPC> spare = new ArrayList<>();

	@Inject
	OceanEncounters(Client client, TrawlingPlusConfig config, Notifier notifier)
	{
		this.client = client;
		this.config = config;
		this.notifier = notifier;
	}

	List<NPC> shown()
	{
		return shown;
	}

	/**
	 * Picks up encounters already in the scene, as when the plugin is switched on at sea.
	 */
	void findExisting()
	{
		WorldView top = client.getTopLevelWorldView();
		if (top != null)
		{
			for (NPC npc : top.npcs())
			{
				add(npc);
			}
		}
	}

	void reset()
	{
		seen.clear();
		notified.clear();
		shown.clear();
		spare.clear();
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		add(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (seen.remove(npc))
		{
			notified.remove(npc);
			shown.remove(npc);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			reset();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (seen.isEmpty())
		{
			shown.clear();
			return;
		}

		TrawlingPlusConfig.CrateTier lowestCrate = config.crateTier();
		TrawlingPlusConfig.CasketTier lowestCasket = config.casketTier();
		List<NPC> wanted = spare;
		wanted.clear();
		for (NPC npc : seen)
		{
			int id = baseId(npc);
			int crate = indexOf(CRATES, id);
			int casket = indexOf(CASKETS, id);
			int formId = -1;
			Notification notification;
			if (crate >= 0)
			{
				notification = CRATE_TIERS[crate].compareTo(lowestCrate) >= 0 ? config.notifyLostCrate() : Notification.OFF;
			}
			else if (casket >= 0)
			{
				notification = CASKET_TIERS[casket].compareTo(lowestCasket) >= 0 ? config.notifyLostCasket() : Notification.OFF;
			}
			else if (id == NpcID.SAILING_CHANCE_ENCOUNTER_CLUE_TURTLE)
			{
				notification = config.notifyClueTurtle();
			}
			else
			{
				// The clam shows the player's own clam: empty, shut on an item, or offering a pearl. A shut one has
				// nothing to do.
				NPCComposition form = npc.getTransformedComposition();
				formId = form == null ? -1 : form.getId();
				if (formId != NpcID.SAILING_CHANCE_ENCOUNTERS_CLAM_OPEN && formId != NpcID.SAILING_CHANCE_ENCOUNTERS_CLAM_PEARL)
				{
					continue;
				}
				notification = config.notifyGiantClam();
			}

			if (!notification.isEnabled())
			{
				continue;
			}
			wanted.add(npc);
			if (notified.add(npc))
			{
				notifier.notify(notification, message(crate, casket, formId));
			}
		}
		spare = shown;
		shown = wanted;
	}

	/**
	 * The notification for a crate or casket by its place among them, a clam by its form, or else the clue turtle.
	 */
	private String message(int crate, int casket, int clamForm)
	{
		boolean plain = config.plainNotifications();
		if (crate >= 0)
		{
			String wood = CRATE_TIERS[crate].toString().toLowerCase();
			return plain ? "Lost " + wood + " crate nearby." : "You spot a lost " + wood + " crate drifting nearby.";
		}
		if (casket >= 0)
		{
			String tier = CASKET_TIERS[casket].toString().toLowerCase();
			return plain ? "Lost casket (" + tier + ") nearby." : "You spot a lost casket (" + tier + ") floating nearby.";
		}
		if (clamForm == NpcID.SAILING_CHANCE_ENCOUNTERS_CLAM_OPEN)
		{
			return plain ? "Giant clam nearby." : "You spot a giant clam surfacing nearby.";
		}
		if (clamForm == NpcID.SAILING_CHANCE_ENCOUNTERS_CLAM_PEARL)
		{
			return plain ? "Giant clam with a pearl nearby." : "You spot a giant clam with a pearl surfacing nearby.";
		}
		return plain ? "Clue turtle nearby." : "You spot a clue turtle swimming nearby.";
	}

	private void add(NPC npc)
	{
		int id = baseId(npc);
		if (id == NpcID.SAILING_CHANCE_ENCOUNTERS_CLAM
			|| id == NpcID.SAILING_CHANCE_ENCOUNTERS_CLAM_OPEN
			|| id == NpcID.SAILING_CHANCE_ENCOUNTERS_CLAM_CLOSED
			|| id == NpcID.SAILING_CHANCE_ENCOUNTERS_CLAM_PEARL
			|| id == NpcID.SAILING_CHANCE_ENCOUNTER_CLUE_TURTLE
			|| indexOf(CRATES, id) >= 0
			|| indexOf(CASKETS, id) >= 0)
		{
			seen.add(npc);
		}
	}

	/**
	 * The NPC's own id, before any change of form, so a clam is known whatever form it shows, or none.
	 */
	private static int baseId(NPC npc)
	{
		NPCComposition composition = npc.getComposition();
		return composition == null ? npc.getId() : composition.getId();
	}

	private static int indexOf(int[] ids, int id)
	{
		for (int i = 0; i < ids.length; i++)
		{
			if (ids[i] == id)
			{
				return i;
			}
		}
		return -1;
	}
}

package com.trawlingplus;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.nio.charset.Charset;
import net.runelite.api.Client;
import net.runelite.api.SpritePixels;

/**
 * One of the game's own fonts, drawn in an overlay from its letter sprites: the game keeps each font as a group of
 * sprites, one per character in the Windows-1252 character set. A letter is placed by its sprite's offsets within its
 * cell, and moves the pen on by its offset plus its width, as the old game fonts were measured; the game's own
 * spacing tables are not reachable from a plugin, so the spacing may differ from the game's by a pixel here and
 * there. Built and drawn on the client thread only.
 */
final class QuillFont
{
	private static final int CHARACTERS = 256;
	private static final Charset GAME_CHARSET = Charset.forName("windows-1252");

	private final BufferedImage[] glyphs = new BufferedImage[CHARACTERS];
	private final int[] offsetX = new int[CHARACTERS];
	private final int[] offsetY = new int[CHARACTERS];
	private final int[] advance = new int[CHARACTERS];
	private final int height;

	private QuillFont(SpritePixels[] sprites)
	{
		int tallest = 0;
		for (int i = 0; i < CHARACTERS && i < sprites.length; i++)
		{
			SpritePixels sprite = sprites[i];
			if (sprite == null)
			{
				continue;
			}
			tallest = Math.max(tallest, sprite.getMaxHeight());
			if (sprite.getWidth() > 0 && sprite.getHeight() > 0)
			{
				glyphs[i] = sprite.toBufferedImage();
				offsetX[i] = sprite.getOffsetX();
				offsetY[i] = sprite.getOffsetY();
				advance[i] = sprite.getOffsetX() + sprite.getWidth();
			}
		}
		height = tallest;
		// A space has no pixels to measure, so it takes the width of a narrow letter's cell, or a third of the height.
		int space = advance['i'] > 0 ? advance['i'] + 1 : Math.max(2, height / 3);
		if (advance[' '] <= 0)
		{
			advance[' '] = space;
		}
	}

	/** The font in the given sprite group, or null if the game hasn't loaded it. */
	static QuillFont load(Client client, int spriteGroup)
	{
		SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), spriteGroup, 0);
		if (sprites == null || sprites.length < 128)
		{
			return null;
		}
		QuillFont font = new QuillFont(sprites);
		return font.height > 0 ? font : null;
	}

	int height()
	{
		return height;
	}

	int width(String text)
	{
		int width = 0;
		for (int i = 0; i < text.length(); i++)
		{
			width += advance[index(text.charAt(i))];
		}
		return width;
	}

	/** Draws text with the top of its cells at y, every letter in the one colour. */
	void draw(Graphics2D graphics, String text, int x, int y, Color colour)
	{
		for (int i = 0; i < text.length(); i++)
		{
			int c = index(text.charAt(i));
			if (glyphs[c] != null)
			{
				graphics.drawImage(tint(glyphs[c], colour), x + offsetX[c], y + offsetY[c], null);
			}
			x += advance[c];
		}
	}

	/**
	 * The character's place in the font. A font with no lower case letters (the large capitals) takes the capital
	 * instead; anything the font doesn't have counts as a space.
	 */
	private int index(char character)
	{
		int c = character < 128 ? character : encode(character);
		if (c < 0 || c >= CHARACTERS)
		{
			return ' ';
		}
		if (advance[c] == 0 && Character.isLowerCase(character))
		{
			int upper = Character.toUpperCase(character);
			if (upper < CHARACTERS && advance[upper] > 0)
			{
				return upper;
			}
		}
		return advance[c] > 0 ? c : ' ';
	}

	private static int encode(char character)
	{
		byte[] bytes = String.valueOf(character).getBytes(GAME_CHARSET);
		return bytes.length == 1 && (bytes[0] != '?' || character == '?') ? bytes[0] & 0xff : -1;
	}

	/** The letter in the given colour, keeping its shape and how see-through each pixel is. */
	private static BufferedImage tint(BufferedImage glyph, Color colour)
	{
		BufferedImage tinted = new BufferedImage(glyph.getWidth(), glyph.getHeight(), BufferedImage.TYPE_INT_ARGB);
		int rgb = colour.getRGB() & 0xffffff;
		for (int y = 0; y < glyph.getHeight(); y++)
		{
			for (int x = 0; x < glyph.getWidth(); x++)
			{
				int alpha = (glyph.getRGB(x, y) >>> 24) * colour.getAlpha() / 255;
				if (alpha > 0)
				{
					tinted.setRGB(x, y, alpha << 24 | rgb);
				}
			}
		}
		return tinted;
	}
}

package com.trawlingplus;

import java.util.List;

/**
 * The shape of routes.json, which tools/generate_routes.py builds from the routes recorded in game
 * in tools/recorded_routes.json.
 */
class RouteData
{
	List<Species> species;

	static class Species
	{
		String name;
		// "any" where both fish offcuts and fine fish offcuts bait this kind of shoal, "fine" where only
		// fine fish offcuts do.
		String bait;
		List<Route> routes;
	}

	static class Route
	{
		String name;
		// How long a shoal sits at each stop on this route, in ticks, or 0 where it has not been timed
		// yet. Different species sit for very different lengths, so there is no sensible default.
		int stopTicks;
		double[][] stops;
		double[][] path;
		// Stretches marked safe by hand in routes.json despite sitting close to where a sea creature that
		// attacks boats spawns, as [x, y, tiles] circles, or null where none apply.
		double[][] safe;
		// Where sea creatures that attack boats spawn close enough to threaten this route, place by place, or
		// null where none do. From the OSRS wiki (Boat combat, each creature page), folded in by hand once
		// under the route each place is close enough to threaten; a place is never split between routes.
		List<Threat> threats;
	}

	static class Threat
	{
		String creature;
		int combat;
		int[][] points;
	}
}

package com.trawlingplus;

import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Perspective;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * A shoal in the scene and the route it has been matched to, if any.
 */
final class Shoal
{
	// How long the heading arrow takes to fade fully in or out, in milliseconds: about a game tick.
	private static final double FADE_MILLIS = 600;

	// Once the route to a new next stop has drawn itself out, how long the stop takes to fade in, in
	// milliseconds. How long the route takes to draw out is set in the config.
	private static final double STOP_REVEAL_MILLIS = 300;

	// How long a new section waits before it starts drawing out, in milliseconds. A shoal counts as
	// heading for its next stop a little before it has finished gliding into the one it is at, so this
	// gives it time to settle in first.
	private static final long REVEAL_DELAY_MILLIS = 500;

	private final WorldEntity entity;
	private ShoalRoute route;
	private int clickbox;
	// Where the shoal was last found along its route, so it can be followed past a crossing.
	private double routeDistance = -1;

	private double[] lastPosition;
	private double[] lastTarget;
	private ShoalDepth depth = ShoalDepth.UNKNOWN;
	// The last depth read off the shoal's animation rather than guessed, and whether it changed on the last read.
	private ShoalDepth animatedDepth;
	private boolean depthChanged;

	// The bar the game draws over a shoal while it sits at a stop, which empties as the stop runs out,
	// and how long a stop on this shoal's route lasts. The bar is the same length whatever the route
	// but a stop is not, so without a known length there is nothing to turn the bar into a time.
	private int barLeft = -1;
	private int barScale;
	private int barStopTicks;
	private long stopEndsMillis = -1;
	private boolean sawNoBar;

	// A bar appearing this far below full did not just appear because a stop began. A shoal's world
	// entity turns up a tick or two before the fish inside it do, so it can look as though there was
	// no bar when really there was nothing to read it from yet.
	private static final int FRESH_SLACK = 6;
	// Hidden until the shoal is seen swimming, and whenever it sits still.
	private boolean headingArrowHidden = true;
	private double headingArrowOpacity;
	private long lastFadeMillis = -1;
	// How much of the heading arrow shows near the boat: held where it was for HEADING_CLEAR_HOLD_MILLIS once the
	// boat starts to cover it, then faded down at the arrow's usual pace. Started afresh after a gap in drawing it.
	private static final long HEADING_CLEAR_HOLD_MILLIS = 1500;
	private static final long HEADING_CLEAR_GAP_MILLIS = 250;
	private double headingClearShown = 1;
	private long headingClearDropMillis = -1;
	private long lastClearMillis = -1;
	// When the shoal last moved off from a stop it was seen sitting at, for the same length of time after which the
	// boat doesn't hide the arrow at all, so it is seen setting off.
	private boolean seenStill;
	private long setOffMillis = -1;

	// The next stop the route is being drawn out to, and when that started.
	private int revealStop = -1;
	// The stop it was heading for before that, which it has just reached: kept on screen while the
	// shoal settles in there, then forgotten.
	private int arrivedStop = -1;
	private long revealStartMillis;

	Shoal(WorldEntity entity)
	{
		this.entity = entity;
	}

	ShoalRoute getRoute()
	{
		return route;
	}

	/**
	 * The clickbox object the shoal was found by, which says what species it is.
	 */
	int getClickbox()
	{
		return clickbox;
	}

	void setClickbox(int clickbox)
	{
		this.clickbox = clickbox;
	}

	void setRoute(ShoalRoute route)
	{
		if (route != this.route)
		{
			// Stop numbers belong to a route, so draw the new one out from the start.
			revealStop = -1;
			arrivedStop = -1;
			routeDistance = -1;
		}
		this.route = route;
	}

	/**
	 * Swaps in the same route with its line smoothed differently. Its stops are the same, so a next
	 * section that's drawing itself out carries on.
	 */
	void reshapeRoute(ShoalRoute route)
	{
		this.route = route;
	}

	/**
	 * Follows the shoal along its route, giving how far round it now is. Keeping hold of where it was
	 * is what stops it jumping to the other side of a crossing where a route doubles back on itself.
	 */
	double followRoute(double[] position)
	{
		routeDistance = route.project(position[0], position[1], routeDistance).distance;
		return routeDistance;
	}

	ShoalDepth getDepth()
	{
		return depth;
	}

	/**
	 * Takes the depth as read this tick, and whether it came off the shoal's animation. Only one animated depth
	 * giving way to another counts as a change, not the guessed resting depth giving way to the first one seen.
	 */
	void setDepth(ShoalDepth depth, boolean animated)
	{
		this.depth = depth;
		depthChanged = animated && animatedDepth != null && animatedDepth != depth;
		if (animated)
		{
			animatedDepth = depth;
		}
	}

	/**
	 * Whether the shoal's animation moved it to another depth on the last read.
	 */
	boolean depthChanged()
	{
		return depthChanged;
	}

	/**
	 * Takes the stop bar as it reads this tick. A bar that has gone means the shoal is on the move, and
	 * one that has gone up means it has settled at the next stop and the bar has been refilled.
	 */
	void setStopBar(int left, int scale)
	{
		if (left < 0)
		{
			// No bar, so the shoal is on the move and there is no stop to count down.
			stopEndsMillis = -1;
			sawNoBar = true;
		}
		else if (barLeft < 0 || left > barLeft)
		{
			// A stop has begun, so the clock is set running for as long as one lasts. When it began is
			// only known if the shoal was watched through the gap before it and the bar has turned up
			// full: a bar that was already part way down belongs to a stop that started before anyone
			// was looking, whether because the shoal was found mid stop or because it had not finished
			// loading, and that one is not counted at all.
			boolean fromTheStart = sawNoBar && scale > 0 && left >= scale - FRESH_SLACK;
			stopEndsMillis = fromTheStart
				? System.currentTimeMillis() + (long) barStopTicks * Constants.GAME_TICK_LENGTH
				: -1;
			sawNoBar = false;
		}

		barLeft = left;
		barScale = scale;
	}

	/**
	 * Takes how long a stop on this shoal's route lasts, in ticks, which is how long the clock is set for.
	 */
	void seedStopTicks(int ticks)
	{
		barStopTicks = ticks;
	}

	/**
	 * How full the game's bar over the shoal is at its stop, from 0 to 1 as the game has it, or -1 while it is on
	 * the move.
	 */
	double stopBarFraction()
	{
		return barLeft < 0 || barScale <= 0 ? -1 : Math.min(1, (double) barLeft / barScale);
	}

	/**
	 * How long the shoal has left at this stop, in seconds, or -1 when that is not known exactly. It is
	 * only known for a stop that was watched from its first tick: a shoal found part way through one
	 * could only be guessed at from how far down its bar is, and a guess is worse than nothing here.
	 */
	double secondsAtStop()
	{
		if (barLeft < 0 || stopEndsMillis < 0)
		{
			return -1;
		}

		return Math.max(0, (stopEndsMillis - System.currentTimeMillis()) / 1000.0);
	}

	/**
	 * Whether the shoal is sitting at a stop, as of the last tick.
	 */
	boolean stopped()
	{
		return headingArrowHidden;
	}

	/**
	 * Whether the shoal has actually been seen sitting still, as of the last tick. Unlike stopped(), a shoal that
	 * has only just come into view, with nothing yet to judge it by, doesn't count.
	 */
	boolean seenStopped()
	{
		return seenStill;
	}

	/**
	 * Tracks whether the shoal is swimming or sitting still, once per game tick. The heading arrow
	 * hides the tick the shoal stops and shows again the tick it moves off.
	 *
	 * Judged from where the shoal is heading whenever that can be read. The destination stops changing on
	 * the tick the last move is sent, and changes again the tick a new one is, where the drawn position
	 * only settles or sets off a tick later, once the client has glided it there. The position is the fallback
	 * when there is none.
	 */
	void update(double[] position, double[] target)
	{
		boolean judged = false;
		if (target != null)
		{
			if (lastTarget != null)
			{
				headingArrowHidden = target[0] == lastTarget[0] && target[1] == lastTarget[1];
				judged = true;
			}
		}
		else if (lastPosition != null)
		{
			headingArrowHidden = position[0] == lastPosition[0] && position[1] == lastPosition[1];
			judged = true;
		}
		if (judged)
		{
			if (seenStill && !headingArrowHidden)
			{
				setOffMillis = System.currentTimeMillis();
			}
			seenStill = headingArrowHidden;
		}
		lastPosition = position;
		lastTarget = target;
	}

	/**
	 * How opaque the heading arrow is right now, from 0 to 1. It moves towards shown or hidden a
	 * little on each call, so the arrow fades in and out instead of popping. Call once per frame.
	 */
	double headingArrowOpacity(long nowMillis)
	{
		if (lastFadeMillis >= 0)
		{
			double step = Math.max(0, nowMillis - lastFadeMillis) / FADE_MILLIS;
			headingArrowOpacity = headingArrowHidden
				? Math.max(0, headingArrowOpacity - step)
				: Math.min(1, headingArrowOpacity + step);
		}
		lastFadeMillis = nowMillis;

		// Smoothstep, so the fade eases in and out rather than changing at a constant rate.
		return headingArrowOpacity * headingArrowOpacity * (3 - 2 * headingArrowOpacity);
	}

	/**
	 * How much of the heading arrow to show near the boat, given how much the boat's clear area would show of it
	 * right now: the same, except that as the boat comes over it, it stays where it was for a second and a half
	 * before fading, and for a second and a half after the shoal moves off from a stop, it is not hidden at all.
	 * Coming out from under the boat shows it again at once. Call once per frame it is drawn.
	 */
	double heldClearShown(double shown, long nowMillis)
	{
		long since = lastClearMillis < 0 ? Long.MAX_VALUE : nowMillis - lastClearMillis;
		lastClearMillis = nowMillis;
		if (setOffMillis >= 0 && nowMillis - setOffMillis < HEADING_CLEAR_HOLD_MILLIS)
		{
			// Just set off from a stop, so shown whatever the boat is over.
			headingClearShown = 1;
			headingClearDropMillis = -1;
			return 1;
		}
		if (since > HEADING_CLEAR_GAP_MILLIS || shown >= headingClearShown)
		{
			headingClearShown = shown;
			headingClearDropMillis = -1;
		}
		else if (headingClearDropMillis < 0)
		{
			headingClearDropMillis = nowMillis;
		}
		else if (nowMillis - headingClearDropMillis >= HEADING_CLEAR_HOLD_MILLIS)
		{
			headingClearShown = Math.max(shown, headingClearShown - Math.max(0, since) / FADE_MILLIS);
		}
		return headingClearShown;
	}

	/**
	 * Notes the stop the shoal is heading for, once per frame. When it changes, the route to the new
	 * stop starts drawing itself out.
	 */
	void headFor(int nextStop, long nowMillis)
	{
		if (nextStop != revealStop)
		{
			arrivedStop = revealStop;
			revealStop = nextStop;
			revealStartMillis = nowMillis + REVEAL_DELAY_MILLIS;
		}
	}

	/**
	 * The stop the shoal has just reached, while it is still being shown, or -1.
	 */
	int arrivedStop()
	{
		return arrivedStop;
	}

	void clearArrivedStop()
	{
		arrivedStop = -1;
	}

	/**
	 * Whether the section to the next stop has started drawing out, rather than still waiting for the
	 * shoal to settle in.
	 */
	boolean revealStarted(long nowMillis)
	{
		return nowMillis >= revealStartMillis;
	}

	/**
	 * How much of the route to the next stop is drawn so far, from 0 to 1, when it takes the given
	 * time to draw out.
	 */
	double routeReveal(long nowMillis, long revealMillis)
	{
		double t = Math.min(1, Math.max(0, nowMillis - revealStartMillis) / (double) revealMillis);
		// Sets off gently and settles into the stop, but without creeping in, which read as dragging on:
		// it arrives at a third of its average speed rather than coming to a crawl.
		return t * t * (8 - 5 * t) / 3;
	}

	/**
	 * How opaque the next stop is, from 0 to 1. It fades in once the route has been drawn out to it.
	 */
	double nextStopReveal(long nowMillis, long revealMillis)
	{
		double t = Math.min(1, Math.max(0, nowMillis - revealStartMillis - revealMillis) / STOP_REVEAL_MILLIS);
		return t * t * (3 - 2 * t);
	}

	/**
	 * The world view the shoal swims around in, which is normally the top-level one.
	 */
	WorldView parentView(Client client)
	{
		LocalPoint local = entity.getLocalLocation();
		return local == null ? null : client.getWorldView(local.getWorldView());
	}

	/**
	 * Whether the shoal is being drawn in the world right now. Only a shoal the client is rendering
	 * may be marked on a map: a remembered position is not the plugin's to show, and one that has
	 * swum out of range is no longer the plugin's to know.
	 */
	boolean rendered(Client client)
	{
		LocalPoint local = entity.getLocalLocation();
		WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
		if (view == null)
		{
			return false;
		}

		// Inside the scene the client is drawing, rather than the wider area it has loaded around it.
		return local.getX() >= 0 && local.getY() >= 0
			&& local.getX() < view.getSizeX() * Perspective.LOCAL_TILE_SIZE
			&& local.getY() < view.getSizeY() * Perspective.LOCAL_TILE_SIZE;
	}

	/**
	 * Where the shoal is swimming to in world tiles: the spot the server last sent, which the client glides
	 * it towards until the next tick. Null when it cannot be read.
	 */
	double[] target(Client client)
	{
		LocalPoint local = entity.getTargetLocation();
		WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
		return view == null ? null : toWorld(view, local);
	}

	/**
	 * The shoal's position in world tile coordinates, including the fraction of a tile, or null.
	 */
	double[] position(Client client)
	{
		LocalPoint local = entity.getLocalLocation();
		WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
		return view == null ? null : toWorld(view, local);
	}

	private static double[] toWorld(WorldView view, LocalPoint local)
	{
		return new double[]{
			view.getBaseX() + (double) (local.getX() - Perspective.LOCAL_HALF_TILE_SIZE) / Perspective.LOCAL_TILE_SIZE,
			view.getBaseY() + (double) (local.getY() - Perspective.LOCAL_HALF_TILE_SIZE) / Perspective.LOCAL_TILE_SIZE
		};
	}
}

package com.trawlingplus;

import net.runelite.api.gameval.AnimationID;

/**
 * How deep a shoal is swimming, which trawling nets have to be set to match.
 */
enum ShoalDepth
{
	SHALLOW("Shallow", 1),
	MODERATE("Moderate", 2),
	DEEP("Deep", 3),
	UNKNOWN("Unknown", -1);

	private final String name;
	private final int netDepth;

	ShoalDepth(String name, int netDepth)
	{
		this.name = name;
		this.netDepth = netDepth;
	}

	/**
	 * The value the depth varbit of a net holds while it is set to this depth, or -1 when unknown.
	 * A raised net reads 0, which is no depth at all.
	 */
	int netDepth()
	{
		return netDepth;
	}

	@Override
	public String toString()
	{
		return name;
	}

	/**
	 * The depth an animation means, or null if it means none of them. The ripples of a shoal play the
	 * first three; the fish swimming around it play the silent versions of the same three.
	 */
	static ShoalDepth fromAnimation(int animation)
	{
		switch (animation)
		{
			case AnimationID.DEEP_SEA_TRAWLING_SHOAL_SHALLOW:
			case AnimationID.DEEP_SEA_TRAWLING_SHOAL_SHALLOW_NOSOUND:
				return SHALLOW;
			case AnimationID.DEEP_SEA_TRAWLING_SHOAL_MID:
			case AnimationID.DEEP_SEA_TRAWLING_SHOAL_MID_NOSOUND:
				return MODERATE;
			case AnimationID.DEEP_SEA_TRAWLING_SHOAL_DEEP:
			case AnimationID.DEEP_SEA_TRAWLING_SHOAL_DEEP_NOSOUND:
				return DEEP;
			default:
				return null;
		}
	}
}

package com.trawlingplus;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;

/**
 * One shoal route: a closed loop of path points with stops along it. Positions are world tile
 * coordinates, and distances are measured in tiles round the loop in the direction shoals swim,
 * which is the order routes.json lists the points in.
 */
final class ShoalRoute
{
	private static final String RESOURCE = "routes.json";

	// Longest gap between the points the overlay draws the route through, in tiles. Every gap being
	// split is already a straight piece of the finished curve, so this only ever adds points along
	// straights: bends are made of pieces shorter than this and keep exactly the points they have.
	// The line looks the same at any spacing; closer points only stop it nearer the edge of the
	// loaded map, and three tiles apart is close enough.
	private static final double SAMPLE_SPACING = 3.0;

	// Spacing of the points a route's curve is laid down as, in tiles. The line is drawn as straight
	// pieces between them, and at a quarter of a tile the corners between pieces don't show, even on
	// tight bends seen close up.
	private static final double SMOOTH_SPACING = 0.25;

	// A curve point this close to the line through the points either side of it is dropped, in tiles.
	// It makes no visible difference, and takes most of the points out of long straight stretches.
	private static final double CURVE_TOLERANCE = 0.01;

	// Before light smoothing, long straight stretches are split into points this far apart, in tiles,
	// so the curve only rounds off corners instead of swinging wide between them. On Rainbow Reef it
	// stays within a quarter of a tile of where the recorded shoal actually swam.
	private static final double CATMULL_ROM_SPACING = 6.0;

	// Heavy smoothing respaces the points this far apart all the way round, bends included, so it
	// rounds the bends off too. At 5 tiles it sits about a fifth of a tile off the recorded laps on
	// average and never more than a tile and a quarter, comfortably inside the 3 tiles a shoal may
	// stray from its route before it stops being matched to it.
	private static final double B_SPLINE_SPACING = 5.0;

	// Heavy smoothing doesn't pass through the recorded points, which left stops on tight bends most of
	// a tile off the line. The curve is pulled onto each stop, the pull easing off to nothing this far
	// either way round the route, in tiles, so the line bends gently onto the stop rather than kinking.
	// Never further than halfway to the next stop, so no stretch is pulled towards two.
	private static final double PIN_TILES = 10;

	// A shoal this close to a stop counts as sitting at it, so its next stop is the one after.
	static final double AT_STOP_TILES = 3.0;

	// How far either way along the route a shoal is looked for, once it is known roughly where it was,
	// in tiles. A shoal covers well under a tile a tick, so this is far more than it can have moved,
	// and far less than the way round to the other side of a crossing.
	private static final double FOLLOW_WINDOW = 15;

	// A position further than this from the stretch it was expected on has not been followed properly,
	// so the whole route is searched instead. The same tolerance as matching a shoal to a route.
	private static final double FOLLOW_OFFSET = 3;

	// How many points go in each run that can be skipped past in one go. Small enough that a run is a
	// short stretch of route, large enough that there are few runs to look through.
	private static final int BLOCK = 64;

	private final String species;
	private final int stopTicks;
	private final double[] pathX;
	private final double[] pathY;
	private final double[] pathDistance;
	private final double length;
	private final double[][] stops;
	private final double[] stopDistance;
	private final double[] sampleX;
	private final double[] sampleY;
	private final double[] sampleDistance;
	private final double[] blockMinX;
	private final double[] blockMinY;
	private final double[] blockMaxX;
	private final double[] blockMaxY;
	private final double minX;
	private final double minY;
	private final double maxX;
	private final double maxY;
	// Which of the drawn points pass close to where sea creatures that attack boats spawn, set by markDanger.
	private boolean[] danger = new boolean[0];
	// Whether any of the route is marked dangerous, so a route with none is passed over whole.
	private boolean anyDanger;
	// Circles of tiles, as {x, y, tiles}, marked safe by hand regardless of danger; never null.
	private final double[][] safe;
	// Where sea creatures that attack boats spawn close enough to threaten this route, place by place; never null.
	private final List<RouteData.Threat> threats;
	// Which of these threaten this route once safe circles and the danger distance are taken into account, with
	// where to place a skull and crossbones for each, set by markDanger.
	private List<DangerousThreat> dangerousThreats = new ArrayList<>();

	ShoalRoute(String species, String name, int stopTicks, double[][] path, double[][] stops, double[][] safe,
		List<RouteData.Threat> threats)
	{
		if (path.length < 2 || stops.length == 0)
		{
			throw new IllegalArgumentException(name + " needs at least two path points and a stop");
		}

		this.species = species;
		this.stopTicks = stopTicks;
		this.stops = stops;
		this.safe = safe == null ? new double[0][] : safe;
		this.threats = threats == null ? new ArrayList<>() : threats;

		int points = path.length;
		pathX = new double[points];
		pathY = new double[points];
		pathDistance = new double[points];
		double distance = 0;
		for (int i = 0; i < points; i++)
		{
			int j = (i + 1) % points;
			pathX[i] = path[i][0];
			pathY[i] = path[i][1];
			pathDistance[i] = distance;
			distance += span(path[j][0] - path[i][0], path[j][1] - path[i][1]);
		}
		length = distance;

		double lowX = Double.MAX_VALUE;
		double lowY = Double.MAX_VALUE;
		double highX = -Double.MAX_VALUE;
		double highY = -Double.MAX_VALUE;
		for (double[][] group : new double[][][]{path, stops})
		{
			for (double[] point : group)
			{
				lowX = Math.min(lowX, point[0]);
				lowY = Math.min(lowY, point[1]);
				highX = Math.max(highX, point[0]);
				highY = Math.max(highY, point[1]);
			}
		}
		minX = lowX;
		minY = lowY;
		maxX = highX;
		maxY = highY;

		stopDistance = new double[stops.length];
		for (int i = 0; i < stops.length; i++)
		{
			stopDistance[i] = project(stops[i][0], stops[i][1]).distance;
		}

		List<double[]> samples = new ArrayList<>();
		for (int i = 0; i < points; i++)
		{
			int j = (i + 1) % points;
			double segment = pathDistance(j) - pathDistance[i];
			int steps = Math.max(1, (int) Math.ceil(segment / SAMPLE_SPACING));
			for (int step = 0; step < steps; step++)
			{
				double t = (double) step / steps;
				samples.add(new double[]{
					pathX[i] + t * (pathX[j] - pathX[i]),
					pathY[i] + t * (pathY[j] - pathY[i]),
					pathDistance[i] + t * segment
				});
			}
		}

		sampleX = new double[samples.size()];
		sampleY = new double[samples.size()];
		sampleDistance = new double[samples.size()];
		for (int i = 0; i < samples.size(); i++)
		{
			sampleX[i] = samples.get(i)[0];
			sampleY[i] = samples.get(i)[1];
			sampleDistance[i] = samples.get(i)[2];
		}

		// The box each run of points fits inside, worked out once here. A route is a thousand tiles
		// round and only a stretch of it is ever on screen, so most of these can be dismissed with four
		// comparisons rather than by asking the same of every point inside them.
		int blocks = (sampleX.length + BLOCK - 1) / BLOCK;
		blockMinX = new double[blocks];
		blockMinY = new double[blocks];
		blockMaxX = new double[blocks];
		blockMaxY = new double[blocks];
		for (int block = 0; block < blocks; block++)
		{
			double westward = Double.MAX_VALUE;
			double southward = Double.MAX_VALUE;
			double eastward = -Double.MAX_VALUE;
			double northward = -Double.MAX_VALUE;
			for (int i = blockFrom(block); i < blockTo(block); i++)
			{
				westward = Math.min(westward, sampleX[i]);
				southward = Math.min(southward, sampleY[i]);
				eastward = Math.max(eastward, sampleX[i]);
				northward = Math.max(northward, sampleY[i]);
			}
			blockMinX[block] = westward;
			blockMinY[block] = southward;
			blockMaxX[block] = eastward;
			blockMaxY[block] = northward;
		}
	}

	/**
	 * How many runs of points the route is divided into for skipping past the parts of it that are
	 * nowhere near the screen.
	 */
	int blockCount()
	{
		return blockMinX.length;
	}

	int blockFrom(int block)
	{
		return block * BLOCK;
	}

	int blockTo(int block)
	{
		return Math.min(sampleX.length, (block + 1) * BLOCK);
	}

	/**
	 * Whether any of a run of points could fall inside the given stretch of the world.
	 */
	boolean blockWithin(int block, double fromX, double fromY, double toX, double toY)
	{
		return blockMaxX[block] >= fromX && blockMinX[block] <= toX
			&& blockMaxY[block] >= fromY && blockMinY[block] <= toY;
	}

	/**
	 * Reads every route from routes.json.
	 */
	static RouteData read(Gson gson) throws IOException
	{
		try (InputStream in = ShoalRoute.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing " + RESOURCE);
			}
			return gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), RouteData.class);
		}
	}

	/**
	 * Builds every route, in the order routes.json lists them, with its path smoothed as chosen.
	 */
	static List<ShoalRoute> build(RouteData data, TrawlingPlusConfig.Smoothing smoothing)
	{
		List<ShoalRoute> routes = new ArrayList<>();
		for (RouteData.Species species : data.species)
		{
			for (RouteData.Route route : species.routes)
			{
				routes.add(new ShoalRoute(species.name, route.name, route.stopTicks,
					shape(route.path, route.stops, smoothing), route.stops, route.safe, route.threats));
			}
		}
		return routes;
	}

	private static double[][] shape(double[][] path, double[][] stops, TrawlingPlusConfig.Smoothing smoothing)
	{
		switch (smoothing)
		{
			case NONE:
				return path;
			case HEAVY:
				return bSpline(path, stops);
			default:
				return catmullRom(path);
		}
	}

	/**
	 * Turns a closed loop of points into a smooth curve through all of them, as a denser loop of points.
	 * Corners are rounded off; straight stretches stay straight.
	 */
	static double[][] catmullRom(double[][] points)
	{
		if (points.length < 3)
		{
			return points;
		}

		double[][] controls = subdivide(points, CATMULL_ROM_SPACING);
		int count = controls.length;
		List<double[]> curve = new ArrayList<>();
		for (int i = 0; i < count; i++)
		{
			double[] p0 = controls[(i + count - 1) % count];
			double[] p1 = controls[i];
			double[] p2 = controls[(i + 1) % count];
			double[] p3 = controls[(i + 2) % count];

			double t1 = knot(p0, p1);
			double t2 = t1 + knot(p1, p2);
			double t3 = t2 + knot(p2, p3);
			int steps = Math.max(1, (int) Math.ceil(span(p2[0] - p1[0], p2[1] - p1[1]) / SMOOTH_SPACING));
			for (int step = 0; step < steps; step++)
			{
				curve.add(catmullRomPoint(p0, p1, p2, p3, t1, t2, t3, t1 + (t2 - t1) * step / steps));
			}
		}
		return trim(curve.toArray(new double[0][]));
	}

	/**
	 * Turns a closed loop of points into a smoother curve that doesn't have to pass through them, as a
	 * denser loop of points, then bends it onto each stop so every stop sits on the line. It irons out
	 * small wobbles and rounds bends off more; straight stretches stay straight.
	 */
	static double[][] bSpline(double[][] points, double[][] stops)
	{
		if (points.length < 3)
		{
			return points;
		}

		double total = loopLength(points);
		double[][] controls = respace(points, B_SPLINE_SPACING);
		int count = controls.length;
		double apart = total / count;
		List<double[]> curve = new ArrayList<>();
		// How far round the recorded path each curve point sits, near enough: the respaced points are
		// evenly spread along it, and the curve passes over them in order.
		List<Double> along = new ArrayList<>();
		for (int i = 0; i < count; i++)
		{
			double[] p0 = controls[(i + count - 1) % count];
			double[] p1 = controls[i];
			double[] p2 = controls[(i + 1) % count];
			double[] p3 = controls[(i + 2) % count];

			int steps = Math.max(1, (int) Math.ceil(span(p2[0] - p1[0], p2[1] - p1[1]) / SMOOTH_SPACING));
			for (int step = 0; step < steps; step++)
			{
				// Uniform cubic B-spline weights, which always add up to 1.
				double t = (double) step / steps;
				double w0 = (1 - t) * (1 - t) * (1 - t) / 6;
				double w1 = (3 * t * t * t - 6 * t * t + 4) / 6;
				double w2 = (-3 * t * t * t + 3 * t * t + 3 * t + 1) / 6;
				double w3 = t * t * t / 6;
				curve.add(new double[]{
					w0 * p0[0] + w1 * p1[0] + w2 * p2[0] + w3 * p3[0],
					w0 * p0[1] + w1 * p1[1] + w2 * p2[1] + w3 * p3[1]
				});
				along.add((i + t) * apart);
			}
		}

		double[][] shaped = curve.toArray(new double[0][]);
		double[] reached = new double[shaped.length];
		for (int i = 0; i < reached.length; i++)
		{
			reached[i] = along.get(i);
		}
		pin(shaped, reached, total, points, stops);
		return trim(shaped);
	}

	/**
	 * Moves a curve so it runs through every stop. Each stop is matched to the stretch of curve over
	 * where it sits along the recorded path, not simply the nearest point, since a route can come back
	 * past one of its stops on the way somewhere else. That stretch is moved across by however far the
	 * stop is off it, the move easing off to nothing either way.
	 */
	private static void pin(double[][] curve, double[] along, double total, double[][] path, double[][] stops)
	{
		double[] stopAlong = new double[stops.length];
		for (int stop = 0; stop < stops.length; stop++)
		{
			stopAlong[stop] = alongLoop(path, stops[stop]);
		}

		for (int stop = 0; stop < stops.length; stop++)
		{
			double radius = PIN_TILES;
			for (int other = 0; other < stops.length; other++)
			{
				if (other != stop)
				{
					radius = Math.min(radius, loopGap(stopAlong[stop], stopAlong[other], total) / 2);
				}
			}

			int nearest = -1;
			double nearestOffset = Double.MAX_VALUE;
			for (int i = 0; i < curve.length; i++)
			{
				if (loopGap(along[i], stopAlong[stop], total) > radius)
				{
					continue;
				}
				double offset = span(stops[stop][0] - curve[i][0], stops[stop][1] - curve[i][1]);
				if (offset < nearestOffset)
				{
					nearest = i;
					nearestOffset = offset;
				}
			}
			if (nearest < 0)
			{
				continue;
			}

			double dx = stops[stop][0] - curve[nearest][0];
			double dy = stops[stop][1] - curve[nearest][1];
			double centre = along[nearest];
			for (int i = 0; i < curve.length; i++)
			{
				double gap = loopGap(along[i], centre, total);
				if (gap < radius)
				{
					double weight = (1 + Math.cos(Math.PI * gap / radius)) / 2;
					curve[i][0] += dx * weight;
					curve[i][1] += dy * weight;
				}
			}
		}
	}

	/**
	 * How far round a closed loop of points the point on it nearest the given position is.
	 */
	private static double alongLoop(double[][] points, double[] position)
	{
		double bestOffset = Double.MAX_VALUE;
		double bestAlong = 0;
		double reached = 0;
		for (int i = 0; i < points.length; i++)
		{
			double[] from = points[i];
			double[] to = points[(i + 1) % points.length];
			double dx = to[0] - from[0];
			double dy = to[1] - from[1];
			double lengthSquared = dx * dx + dy * dy;
			double segmentLength = Math.sqrt(lengthSquared);
			double t = lengthSquared == 0 ? 0
				: Math.max(0, Math.min(1, ((position[0] - from[0]) * dx + (position[1] - from[1]) * dy) / lengthSquared));
			// Squared: only ever compared.
			double awayX = position[0] - (from[0] + t * dx);
			double awayY = position[1] - (from[1] + t * dy);
			double offset = awayX * awayX + awayY * awayY;
			if (offset < bestOffset)
			{
				bestOffset = offset;
				bestAlong = reached + t * segmentLength;
			}
			reached += segmentLength;
		}
		return bestAlong;
	}

	/**
	 * How far apart two distances round a loop are, whichever way round is shorter.
	 */
	private static double loopGap(double a, double b, double total)
	{
		double gap = Math.abs(a - b) % total;
		return Math.min(gap, total - gap);
	}

	private static double loopLength(double[][] points)
	{
		double total = 0;
		for (int i = 0; i < points.length; i++)
		{
			double[] next = points[(i + 1) % points.length];
			total += span(next[0] - points[i][0], next[1] - points[i][1]);
		}
		return total;
	}

	/**
	 * Drops the points of a curve that aren't needed to draw it: those within CURVE_TOLERANCE of the
	 * line through the points either side of them, once the ones between have gone. Long straight
	 * stretches come out as a couple of points; bends keep theirs.
	 */
	private static double[][] trim(double[][] curve)
	{
		int count = curve.length;
		if (count < 3)
		{
			return curve;
		}

		// The loop is trimmed as two halves, so its first point and the one opposite always stay.
		boolean[] keep = new boolean[count];
		keep[0] = true;
		keep[count / 2] = true;
		Deque<int[]> pending = new ArrayDeque<>();
		pending.push(new int[]{0, count / 2});
		pending.push(new int[]{count / 2, count});
		while (!pending.isEmpty())
		{
			int[] span = pending.pop();
			double[] from = curve[span[0]];
			double[] to = curve[span[1] % count];
			double worst = 0;
			int furthest = -1;
			for (int i = span[0] + 1; i < span[1]; i++)
			{
				double offset = distanceToSegment(curve[i], from, to);
				if (offset > worst)
				{
					worst = offset;
					furthest = i;
				}
			}

			if (furthest >= 0 && worst > CURVE_TOLERANCE)
			{
				keep[furthest] = true;
				pending.push(new int[]{span[0], furthest});
				pending.push(new int[]{furthest, span[1]});
			}
		}

		List<double[]> trimmed = new ArrayList<>();
		for (int i = 0; i < count; i++)
		{
			if (keep[i])
			{
				trimmed.add(curve[i]);
			}
		}
		return trimmed.toArray(new double[0][]);
	}

	private static double distanceToSegment(double[] point, double[] from, double[] to)
	{
		double dx = to[0] - from[0];
		double dy = to[1] - from[1];
		double lengthSquared = dx * dx + dy * dy;
		double t = lengthSquared == 0 ? 0
			: Math.max(0, Math.min(1, ((point[0] - from[0]) * dx + (point[1] - from[1]) * dy) / lengthSquared));
		return span(point[0] - (from[0] + t * dx), point[1] - (from[1] + t * dy));
	}

	/**
	 * Points spaced evenly round a closed loop, starting at its first point, as close to the given
	 * distance apart as divides the loop evenly.
	 */
	private static double[][] respace(double[][] points, double spacing)
	{
		int count = points.length;
		double[] reached = new double[count + 1];
		for (int i = 0; i < count; i++)
		{
			double[] next = points[(i + 1) % count];
			reached[i + 1] = reached[i] + span(next[0] - points[i][0], next[1] - points[i][1]);
		}

		int pieces = Math.max(3, (int) (reached[count] / spacing));
		double step = reached[count] / pieces;
		double[][] respaced = new double[pieces][];
		int segment = 0;
		for (int piece = 0; piece < pieces; piece++)
		{
			double at = piece * step;
			while (segment < count - 1 && reached[segment + 1] < at)
			{
				segment++;
			}
			double length = reached[segment + 1] - reached[segment];
			double fraction = length == 0 ? 0 : (at - reached[segment]) / length;
			respaced[piece] = lerp(points[segment], points[(segment + 1) % count], fraction);
		}
		return respaced;
	}

	private static double[][] subdivide(double[][] points, double spacing)
	{
		List<double[]> controls = new ArrayList<>();
		for (int i = 0; i < points.length; i++)
		{
			double[] a = points[i];
			double[] b = points[(i + 1) % points.length];
			int pieces = Math.max(1, (int) Math.ceil(span(b[0] - a[0], b[1] - a[1]) / spacing));
			for (int piece = 0; piece < pieces; piece++)
			{
				controls.add(lerp(a, b, (double) piece / pieces));
			}
		}
		return controls.toArray(new double[0][]);
	}

	private static double knot(double[] a, double[] b)
	{
		// Centripetal Catmull-Rom, which curves through every point without overshooting or looping at sharp turns:
		// the square root of the distance, as two square roots of its square, cheaper than a power. Coincident points
		// would divide by zero, so keep every knot interval above zero.
		double dx = b[0] - a[0];
		double dy = b[1] - a[1];
		return Math.max(1e-6, Math.sqrt(Math.sqrt(dx * dx + dy * dy)));
	}

	private static double[] catmullRomPoint(double[] p0, double[] p1, double[] p2, double[] p3, double t1, double t2, double t3, double t)
	{
		// Barry and Goldman's pyramidal form, with the first knot at zero.
		double[] a1 = lerp(p0, p1, t / t1);
		double[] a2 = lerp(p1, p2, (t - t1) / (t2 - t1));
		double[] a3 = lerp(p2, p3, (t - t2) / (t3 - t2));
		double[] b1 = lerp(a1, a2, t / t2);
		double[] b2 = lerp(a2, a3, (t - t1) / (t3 - t1));
		return lerp(b1, b2, (t - t1) / (t2 - t1));
	}

	private static double[] lerp(double[] a, double[] b, double fraction)
	{
		return new double[]{a[0] + (b[0] - a[0]) * fraction, a[1] + (b[1] - a[1]) * fraction};
	}

	/**
	 * How long a shoal sits at each stop on this route, in ticks, or 0 where it has not been timed.
	 */
	int stopTicks()
	{
		return stopTicks;
	}

	String getSpecies()
	{
		return species;
	}

	double length()
	{
		return length;
	}

	/**
	 * Whether the route's bounding box overlaps the given rectangle of world tiles.
	 */
	boolean overlaps(double fromX, double fromY, double toX, double toY)
	{
		return maxX >= fromX && minX <= toX && maxY >= fromY && minY <= toY;
	}

	/**
	 * How far a position is from the box the whole route fits inside, or 0 while it is inside it. The
	 * route is somewhere in that box, so this is never further than the route itself: a route whose box
	 * is already further off than the nearest found so far cannot win, and need not be looked through.
	 */
	double boxDistance(double x, double y)
	{
		double awayX = Math.max(0, Math.max(minX - x, x - maxX));
		double awayY = Math.max(0, Math.max(minY - y, y - maxY));
		return span(awayX, awayY);
	}

	/**
	 * The corners of the box the whole route fits inside, as world tiles: south west, south east,
	 * north east, north west. Enough to find out where a route sits on a map without walking it.
	 */
	double[][] corners()
	{
		return new double[][]{{minX, minY}, {maxX, minY}, {maxX, maxY}, {minX, maxY}};
	}

	/**
	 * Finds the point on the route nearest to a position.
	 */
	Projection project(double x, double y)
	{
		return project(x, y, -1);
	}

	/**
	 * Where a position sits on the route. Given where it was last found, the search is kept to that
	 * stretch of the route: a route that crosses itself has two places equally close to the crossing,
	 * and picking whichever is a hair nearer makes whatever is following it jump between the two. A
	 * negative distance, or a position that has strayed from that stretch, searches the whole route.
	 */
	Projection project(double x, double y, double near)
	{
		if (near >= 0)
		{
			Projection following = project(x, y, near, FOLLOW_WINDOW);
			if (following.offset <= FOLLOW_OFFSET)
			{
				return following;
			}
		}
		return project(x, y, -1, 0);
	}

	private Projection project(double x, double y, double near, double window)
	{
		int points = pathX.length;
		double bestOffset = Double.MAX_VALUE;
		double bestDistance = 0;
		for (int i = 0; i < points; i++)
		{
			int j = i + 1 == points ? 0 : i + 1;
			double dx = pathX[j] - pathX[i];
			double dy = pathY[j] - pathY[i];
			double lengthSquared = dx * dx + dy * dy;
			// Already measured when the route was built, rather than a square root for every piece on every call.
			double segmentLength = pathDistance(j) - pathDistance[i];

			if (near >= 0)
			{
				// Any piece reaching into the window, not only one starting inside it: a long straight starts
				// well behind a shoal partway along it, and leaving it out snapped the shoal ahead to the
				// corner at its far end. Measured from the back of the window, round the loop.
				double reach = forward(near - window, pathDistance[i]);
				if (reach > 2 * window && reach + segmentLength < length)
				{
					continue;
				}
			}

			double t = lengthSquared == 0 ? 0 : Math.max(0, Math.min(1, ((x - pathX[i]) * dx + (y - pathY[i]) * dy) / lengthSquared));
			// Compared squared, with one square root for the nearest at the end.
			double awayX = x - (pathX[i] + t * dx);
			double awayY = y - (pathY[i] + t * dy);
			double offset = awayX * awayX + awayY * awayY;
			if (offset < bestOffset)
			{
				bestOffset = offset;
				bestDistance = pathDistance[i] + t * segmentLength;
			}
		}
		return new Projection(bestDistance % length, Math.sqrt(bestOffset));
	}

	/**
	 * The index of the stop a shoal at the given distance round the route is heading for.
	 */
	int nextStop(double distance)
	{
		int best = 0;
		double bestGap = Double.MAX_VALUE;
		for (int i = 0; i < stopDistance.length; i++)
		{
			double gap = forward(distance, stopDistance[i]);
			if (gap <= AT_STOP_TILES)
			{
				// Sitting at this stop, or about to reach it: it comes round again last.
				gap += length;
			}
			if (gap < bestGap)
			{
				best = i;
				bestGap = gap;
			}
		}
		return best;
	}

	int stopCount()
	{
		return stops.length;
	}

	double stopX(int stop)
	{
		return stops[stop][0];
	}

	double stopY(int stop)
	{
		return stops[stop][1];
	}

	double stopDistance(int stop)
	{
		return stopDistance[stop];
	}

	int sampleCount()
	{
		return sampleX.length;
	}

	double sampleX(int sample)
	{
		return sampleX[sample];
	}

	double sampleY(int sample)
	{
		return sampleY[sample];
	}

	double sampleDistance(int sample)
	{
		return sampleDistance[sample];
	}

	/**
	 * Marks each drawn point within the given distance of any of this route's threats, in tiles, then marks any
	 * gap no longer than gapTiles between two marked stretches, so a brief dip out of range doesn't break a
	 * dangerous stretch in two, then clears every point inside a hand-marked safe circle, whatever threats are
	 * near it. Also works out which threats actually come close enough to threaten the route this way, and
	 * where to place a skull and crossbones for each: the average of only its spawn points that do.
	 */
	void markDanger(double tiles, double gapTiles)
	{
		boolean[] marked = new boolean[sampleX.length];
		List<DangerousThreat> found = new ArrayList<>();
		for (RouteData.Threat threat : threats)
		{
			double x = 0;
			double y = 0;
			int near = 0;
			for (int[] spawn : threat.points)
			{
				boolean spawnNear = false;
				for (int i = 0; i < sampleX.length; i++)
				{
					double awayX = sampleX[i] - spawn[0];
					double awayY = sampleY[i] - spawn[1];
					if (awayX * awayX + awayY * awayY <= tiles * tiles)
					{
						marked[i] = true;
						spawnNear = true;
					}
				}
				if (spawnNear)
				{
					x += spawn[0];
					y += spawn[1];
					near++;
				}
			}
			if (near > 0)
			{
				found.add(new DangerousThreat(x / near, y / near, threat.creature + " (level-" + threat.combat + ")"));
			}
		}
		closeGaps(marked, gapTiles);
		clearSafe(marked);
		danger = marked;
		boolean any = false;
		for (boolean sample : marked)
		{
			any |= sample;
		}
		anyDanger = any;
		dangerousThreats = found;
	}

	/**
	 * Whether any stretch of the route is marked dangerous.
	 */
	boolean hasDanger()
	{
		return anyDanger;
	}

	private void clearSafe(boolean[] marked)
	{
		for (double[] circle : safe)
		{
			for (int i = 0; i < sampleX.length; i++)
			{
				double awayX = sampleX[i] - circle[0];
				double awayY = sampleY[i] - circle[1];
				if (marked[i] && awayX * awayX + awayY * awayY <= circle[2] * circle[2])
				{
					marked[i] = false;
				}
			}
		}
	}

	/**
	 * Marks every unmarked run of points round the loop that sits between two marked ones no more than
	 * gapTiles apart along the route.
	 */
	private void closeGaps(boolean[] marked, double gapTiles)
	{
		int count = marked.length;
		int start = -1;
		for (int i = 0; i < count && start < 0; i++)
		{
			if (marked[i])
			{
				start = i;
			}
		}
		if (start < 0)
		{
			return;
		}

		// Walked once round the loop from a marked point, so every gap has a marked point at each end.
		int step = 1;
		while (step < count)
		{
			if (marked[(start + step) % count])
			{
				step++;
				continue;
			}

			int end = step;
			while (!marked[(start + end) % count])
			{
				end++;
			}

			int before = (start + step - 1) % count;
			int after = (start + end) % count;
			if (forward(sampleDistance[before], sampleDistance[after]) <= gapTiles)
			{
				for (int fill = step; fill < end; fill++)
				{
					marked[(start + fill) % count] = true;
				}
			}
			step = end;
		}
	}

	/**
	 * Whether this drawn point passes close to where sea creatures that attack boats spawn.
	 */
	boolean dangerAt(int sample)
	{
		return sample < danger.length && danger[sample];
	}

	/**
	 * Whether the piece of route at this distance round it is drawn as dangerous. A piece takes the colour of the
	 * point it starts from, so this reads that point rather than the one after.
	 */
	boolean dangerAtDistance(double distance)
	{
		return dangerAtDistance(distance, 1);
	}

	/**
	 * The same, for a line drawn through only every so many points, where a piece starts at a multiple of stride.
	 */
	boolean dangerAtDistance(double distance, int stride)
	{
		int count = sampleX.length;
		if (count == 0)
		{
			return false;
		}
		int index = Arrays.binarySearch(sampleDistance, forward(0, distance));
		int start = index >= 0 ? index : (-index - 2 + count) % count;
		return dangerAt(start - start % stride);
	}

	/**
	 * How many of this route's threats actually come close enough to threaten it.
	 */
	int dangerousThreatCount()
	{
		return dangerousThreats.size();
	}

	double dangerousThreatX(int threat)
	{
		return dangerousThreats.get(threat).x;
	}

	double dangerousThreatY(int threat)
	{
		return dangerousThreats.get(threat).y;
	}

	/**
	 * The creature at a dangerous threat with its level, as the game names it, such as "Tiger shark (level-125)".
	 */
	String dangerousThreatName(int threat)
	{
		return dangerousThreats.get(threat).name;
	}

	private static final class DangerousThreat
	{
		final double x;
		final double y;
		final String name;

		DangerousThreat(double x, double y, String name)
		{
			this.x = x;
			this.y = y;
			this.name = name;
		}
	}

	/**
	 * The point at a distance round the route and the direction the route runs there, as
	 * {x, y, dx, dy} with the direction a unit vector.
	 */
	double[] pointAt(double distance)
	{
		int count = sampleX.length;
		double at = forward(0, distance);
		int next = sampleAt(at);
		int previous = (next + count - 1) % count;
		double start = sampleDistance[previous];
		double end = sampleDistance[next];
		if (end <= start)
		{
			// The stretch between the last sample and the first, closing the loop.
			end += length;
		}
		if (at < start)
		{
			at += length;
		}

		double fraction = end == start ? 0 : (at - start) / (end - start);
		double dx = sampleX[next] - sampleX[previous];
		double dy = sampleY[next] - sampleY[previous];
		double step = span(dx, dy);
		return new double[]{
			sampleX[previous] + dx * fraction,
			sampleY[previous] + dy * fraction,
			step == 0 ? 0 : dx / step,
			step == 0 ? 0 : dy / step
		};
	}

	/**
	 * The index of the first drawing sample at or after the given distance round the route.
	 */
	int sampleAt(double distance)
	{
		int index = Arrays.binarySearch(sampleDistance, forward(0, distance));
		if (index < 0)
		{
			index = -index - 1;
		}
		return index == sampleDistance.length ? 0 : index;
	}

	/**
	 * How long a line across and down is. Math.hypot guards against overflow these sizes never reach, and costs many
	 * times as much for it.
	 */
	private static double span(double x, double y)
	{
		return Math.sqrt(x * x + y * y);
	}

	private double pathDistance(int point)
	{
		return point == 0 ? length : pathDistance[point];
	}

	/**
	 * How far it is going forwards round the route from one distance to another.
	 */
	double forward(double from, double to)
	{
		// Usually both are already round the route once at most, which needs no remainder.
		double gap = to - from;
		if (gap >= 0 && gap < length)
		{
			return gap;
		}
		gap %= length;
		return gap < 0 ? gap + length : gap;
	}

	static final class Projection
	{
		// Distance round the route to the nearest point on it.
		final double distance;
		// How far the position is from that point.
		final double offset;

		private Projection(double distance, double offset)
		{
			this.distance = distance;
			this.offset = offset;
		}
	}
}

