	/**
	 * Whether the player is sea spot fishing, which shows the hold's display: since they started fishing one of the
	 * spots aboard, until their boat has been away from the spots' regions, docks included, for 3 minutes. Stepping
	 * off to bank, logging out or a disconnect doesn't end it.
	 */
	boolean isSeaFishing()
	{
		return seaFishing;
	}

	/**
	 * Where the fishing spot at sea being fished is, in world tiles, for the arrow pointing to it: while sea spot
	 * fishing, not while the hold is 90% full, when the trip is to bank rather than back to the spot, and not from
	 * fishing until the boat moves off again. Null otherwise.
	 */
	double[] getFishedSpot()
	{
		return seaFishing && !spotHoldFull && !spotPaused ? fishedSpot : null;
	}

	/**
	 * The fishing spot at sea last fished, in world tiles, whatever the arrow's rules say, so the arrow can fade out
	 * where it was once they hide it. Null if none.
	 */
	double[] getRememberedSpot()
	{
		return fishedSpot;
	}

	/**
	 * Ends the arrow's pause for fishing once the boat has moved SPOT_MOVED_TILES from where it was then. Only while
	 * paused, and then every SPOT_MOVED_EVERY_TICKS, once where it was is known.
	 */
	private void checkSpotPaused(WorldEntity own)
	{
		if (!spotPaused || spotPausedAt != null && client.getTickCount() % SPOT_MOVED_EVERY_TICKS != 0)
		{
			return;
		}
		double[] boatAt = worldPlace(own.getLocalLocation());
		if (boatAt == null)
		{
			return;
		}
		if (spotPausedAt == null)
		{
			spotPausedAt = boatAt;
		}
		else if (squared(boatAt[0] - spotPausedAt[0], boatAt[1] - spotPausedAt[1]) > SPOT_MOVED_TILES * SPOT_MOVED_TILES)
		{
			spotPaused = false;
			spotPausedAt = null;
		}
	}

	/**
	 * Keeps where each fishing spot at sea is as it comes into sight. They never move, so where one was last seen is
	 * where it still is once out of sight.
	 */
	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (SEA_SPOTS.contains(npc.getId()))
		{
			double[] place = worldPlace(npc.getLocalLocation());
			if (place != null)
			{
				seaSpotPlaces.put(npc.getId(), place);
			}
		}
	}

	/**
	 * Whether the boat is still close enough to the spot already found for it to be the one being fished.
	 */
	private boolean nearFishedSpot()
	{
		double[] boatAt = fishedSpot == null || ownBoat == null ? null : worldPlace(ownBoat.getLocalLocation());
		return boatAt != null
			&& squared(fishedSpot[0] - boatAt[0], fishedSpot[1] - boatAt[1]) <= SEA_SPOT_REACH_TILES * SEA_SPOT_REACH_TILES;
	}

	/**
	 * The fishing spot at sea nearest the boat, if one is close enough to be the one being fished, or null.
	 */
	private double[] nearestSeaSpot()
	{
		double[] boatAt = ownBoat == null ? null : worldPlace(ownBoat.getLocalLocation());
		if (boatAt == null)
		{
			return null;
		}
		double[] nearest = null;
		double nearestDistance = SEA_SPOT_REACH_TILES * SEA_SPOT_REACH_TILES;
		for (double[] place : seaSpotPlaces.values())
		{
			double distance = squared(place[0] - boatAt[0], place[1] - boatAt[1]);
			if (distance <= nearestDistance)
			{
				nearest = place;
				nearestDistance = distance;
			}
		}
		return nearest;
	}

	/**
	 * Ends sea spot fishing, as stepping off does, once the boat has been away from all of them for
	 * SEA_AWAY_TICKS, which hides the hold's display until the player starts fishing one again. Near one is being
	 * in one of the map regions around it. Only worked out while fishing one.
	 */
	private void checkNearSpots(WorldEntity own)
	{
		if (!seaFishing)
		{
			awayFromSpotsTick = -1;
			return;
		}
		// Every few ticks: a few seconds either way on 3 minutes doesn't matter.
		if (client.getTickCount() % SPOT_MOVED_EVERY_TICKS != 0)
		{
			return;
		}
		double[] place = worldPlace(own.getLocalLocation());
		if (place == null)
		{
			return;
		}

		int region = ((int) place[0] >> 6) << 8 | ((int) place[1] >> 6);
		int tick = client.getTickCount();
		if (nearSeaSpot(region))
		{
			awayFromSpotsTick = -1;
		}
		else if (awayFromSpotsTick < 0)
		{
			awayFromSpotsTick = tick;
		}
		else if (tick - awayFromSpotsTick >= SEA_AWAY_TICKS)
		{
			seaFishing = false;
			awayFromSpotsTick = -1;
		}
	}

	private static boolean nearSeaSpot(int region)
	{
		for (int[] spot : SEA_SPOT_REGIONS)
		{
			for (int near : spot)
			{
				if (near == region)
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Whether the boat has a trawling net in either slot, kept up to date as the game changes the slots.
	 */
	boolean netsFitted()
	{
		return netsFitted;
	}

	private boolean readNetsFitted()
	{
		// Each slot names the hotspot its net is built on, so an empty slot names no hotspot.
		return client.getVarbitValue(NET_SLOTS[0]) > 0 || client.getVarbitValue(NET_SLOTS[1]) > 0;
	}

	private boolean readNetsLowered()
	{
		// A net's depth reads 0 while it is raised out of the water, and 1 to 3 at the fishing depths.
		return client.getVarbitValue(NET_DEPTHS[0]) > 0 || client.getVarbitValue(NET_DEPTHS[1]) > 0;
	}

	/**
	 * Keeps count of the fish in the nets from what the game says about them, since nothing else tells.
	 * Every catch, the crew's included, is announced with how many fish it brought in, and emptying the
	 * nets or taking everything from them leaves none.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (type == ChatMessageType.PUBLICCHAT)
		{
			restCrewmate(event);
			return;
		}
		if (type != ChatMessageType.SPAM && type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.MESBOX)
		{
			return;
		}

		String message = chatText(event.getMessage());
		if (message.startsWith("Your crew start moving the contents of the cargo hold"))
		{
			// Asking the crew on the dock to move everything in the hold to the bank empties it. This is said
			// off the boat, so it comes before the check for being aboard; what the crewmate says once it is
			// done is in their own words, so this is the line to go by.
			boatRecord().empty();
			return;
		}

		if (aboardBoat != null && message.startsWith(NETS_NUMB))
		{
			// Only said when the game knocks the player off, so stepping off by choice never notifies. Said on
			// anyone's boat.
			notifier.notify(config.notifyStoppedOperating(), config.plainNotifications()
				? "You stopped operating the net." : "Your numb hands slip from the net.");
			return;
		}

		// Sea spot fishing is only done from the player's own boat, whatever the guides are doing, as they have
		// nothing to do with the nets.
		if (ownBoat != null)
		{
			if (message.startsWith(NETS_START))
			{
				// Back on the nets, so the player's own catches are theirs again.
				fishingSpot = false;
			}

			boolean start = message.startsWith("You ") && SEA_START.matcher(message).find();
			boolean seaCatch = fishingSpot && message.startsWith("You catch ");
			if (start || seaCatch)
			{
				// Sea spot fishing, from the moment it starts, which puts nothing in the nets. Starting or
				// catching is being at a spot, wherever its regions say it is.
				seaFishing = true;
				fishingSpot = true;
				awayFromSpotsTick = -1;
				if (start && !nearFishedSpot())
				{
					// Only looked for again when fishing starts somewhere other than the spot already found.
					fishedSpot = nearestSeaSpot();
				}
				// Fishing, so the arrow hides until the boat moves off again.
				spotPaused = true;
				spotPausedAt = null;
				if (seaCatch)
				{
					// What it brings arrives in the inventory the same tick, which isn't taken out of the hold.
					seaCatchTick = client.getTickCount();
				}
				return;
			}
		}

		if (boatPlace == null)
		{
			return;
		}

		// The player's catches are counted on anyone's boat. Sea spot catches are never trawled fish, so a catch
		// naming one came from the nets.
		// Most lines are neither, so the pattern only runs on ones that could be a catch.
		Matcher catchLine = CATCH.matcher(message);
		int catchCount = mightBeCatch(message) && catchLine.find() ? number(catchLine.group(1)) : -1;
		// A catch, or a net trying for a shoal in reach ("Your net is not deep enough to catch fish from the nearby
		// bluefin shoal.", "Jolly Jim's net is too deep..."), shows that side is working a shoal rather than passing one.
		if (catchCount > 0)
		{
			proveNetTime(message.startsWith("You catch"));
		}
		else if (message.contains("catch fish from the nearby"))
		{
			proveNetTime(message.startsWith("Your net"));
		}
		boolean byCaptain = message.startsWith("You catch");
		noteCrewOnNet(crewOnNetSaying(message, catchCount > 0 && !byCaptain));
		// The crew's catches only count on the player's own boat, as their time on nets does.
		if (catchCount > 0 && (byCaptain || ownBoat != null))
		{
			countCatch(message.substring(catchLine.end()), catchCount, byCaptain);
			if (!byCaptain)
			{
				// "Jolly Jim catches three giant krill!"
				countLifetime(LIFETIME_CATCHER_KEY + message.substring(0, message.indexOf(" catches ")), catchCount);
			}
			if (heldTrawlTicks > 0)
			{
				countHeld(LIFETIME_TRAWL_TICKS_KEY, heldTrawlTicks);
			}
			heldTrawlTicks = 0;
			// Only fish caught while that side's time on nets counts, so fish per hour sets like against like.
			if (byCaptain ? captainNetProven : crewNetProven)
			{
				countLifetime(byCaptain ? LIFETIME_CAPTAIN_NET_FISH_KEY : LIFETIME_CREW_NET_FISH_KEY,
					catchCount);
			}
		}
		else if (catchCount <= 0 && message.startsWith("Trawler's trust"))
		{
			// "Trawler's trust: You catch an additional fish."
			countLifetime(LIFETIME_TRUST_KEY, 1);
		}

		if (ownBoat == null)
		{
			// Someone else's boat. There the player has a net of their own, 250 fish that only their catches fill and
			// only they empty or take from, so it is counted from their own messages; the boat's hold isn't theirs.
			otherBoatNet(message, catchCount > 0 && byCaptain ? catchCount : 0);
			return;
		}

		if (message.startsWith("Your crewmate on the chum station can"))
		{
			// "...can't find any offcuts in the cargo hold." Nothing was laid, and the hold has none of what the
			// nearest shoal takes.
			noBait();
			return;
		}

		// "You bait a nearby <species> shoal..." or "<crewmate> has baited a nearby <species> shoal...".
		if (message.startsWith("You bait a nearby") || message.contains("baited a nearby"))
		{
			baitAnnouncedTick = client.getTickCount();
			countLifetime(LIFETIME_BAIT_KEY, 1);
			return;
		}

		if (message.startsWith("There are no fish in"))
		{
			// What opening an empty net says, in a box of its own rather than the menu a net with fish opens.
			noteFish(0);
		}
		else if (message.startsWith("You empty the net"))
		{
			// "..., but there was not enough space in there to do so entirely." A hold without room for them
			// all keeps some back and doesn't say how many; one that took them all had room.
			boolean noRoom = message.contains("not enough");
			CargoHold record = boatRecord();
			if (noRoom && !record.fullWarning())
			{
				notifier.notify(config.notifyHoldFull(), config.plainNotifications()
					? "Your cargo hold is full." : "Your cargo hold is packed to the brim.");
			}
			record.setFullWarning(noRoom);
			if (noRoom)
			{
				setFish(-1);
			}
			else
			{
				if (fishInNets > 0)
				{
					record.addTrawled(fishInNets);
				}
				noteFish(0);
			}
		}
		else if (message.startsWith("You take all of the fish from the net"))
		{
			noteFish(0);
		}
		else if (message.startsWith("You take some fish from the net"))
		{
			// An inventory without room for them all takes as many as fit, and doesn't say how many. The
			// inventory does, and its update can come either side of this message on the same tick.
			if (inventoryTick == client.getTickCount())
			{
				takeFromNets(inventoryAdded);
			}
			else
			{
				takePending = true;
			}
		}
		else if (message.startsWith("Your net has no more space"))
		{
			// "Your net has no more space for any raw bluefin.", for the crew's attempts as well as the player's.
			// On its own it doesn't mean the nets are full: it turns up now and then with plenty of room left,
			// the nets catching again straight after. So it only notifies while the count says full as well,
			// and then every time it is said.
			if (netsFull())
			{
				notifier.notify(config.notifyNetsFull(), config.plainNotifications()
					? "Your trawling nets are full." : "Your nets are bursting with fish.");
			}
		}
		else if (netsFitted())
		{
			// Only with a net fitted: the messages above name the nets, but a catch could be ordinary fishing.
			// A catch whose count can't be read, like "You catch some shrimps" from ordinary fishing, is not a
			// trawling catch and changes nothing. "Trawler's trust: You catch an additional fish." doesn't
			// match either, which is right: that fish is already in the number of the catch line after it.
			Matcher caught = CATCH.matcher(message);
			int fish = caught.find() ? number(caught.group(1)) : -1;
			if (fish > 0)
			{
				lastCatchTick = client.getTickCount();
			}
			if (fish >= 0 && fishInNets >= 0)
			{
				if (netsEmptied && fishInNets + fish >= NETS_FILLED_AT)
				{
					countLifetime(LIFETIME_NETS_FILLED_KEY, 1);
					netsEmptied = false;
				}
				setFish(Math.min(NET_CAPACITY, fishInNets + fish));
			}
		}
	}

	/**
	 * Opening a net asks what to do with the fish in it and says how many there are, which puts the count
	 * right whatever it had drifted to.
	 */
	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.CHATMENU && aboardBoat != null && boatPlace != null)
		{
			// The menu's lines are filled in after it loads.
			clientThread.invokeLater(this::readNetMenu);
		}
		else if (event.getGroupId() == InterfaceID.SAILING_BOAT_CARGOHOLD && !onOtherBoat())
		{
			holdOpen = true;
			// What goes into or comes out of it while it is open is counted from the inventory as it opens.
			countTransfers(client.getItemContainer(InventoryID.INV));
			// Read here as well as when its contents arrive, since an empty hold sends none. Its numbers are filled
			// in after it loads.
			clientThread.invokeLater(this::readHoldSpace);
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.SAILING_BOAT_CARGOHOLD)
		{
			holdOpen = false;
			holdClosedTick = client.getTickCount();
		}
	}

	/**
	 * Stepping off the boat throws away whatever is in the nets, so they are empty once the player is no
	 * longer aboard: taken from the game's own flag rather than from where the player stands, which can
	 * look like being off the boat for a moment while the area loads. Also keeps track of which net slots
	 * have a net in them.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		int varbit = event.getVarbitId();
		if (varbit == VarbitID.SAILING_PLAYER_IS_ON_PLAYER_BOAT && event.getValue() == 0)
		{
			// Sea spot fishing carries on: stepping off at a dock to bank comes back to it, and its away timer is what
			// ends it, the docks being in the spots' regions.
			resetFish(0);
			fishingSpot = false;
		}
		else if (varbit == VarbitID.SAILING_LAST_PERSONAL_BOAT_BOARDED && event.getValue() != boatHoldNumber)
		{
			// Another boat, whose hold is looked for again. The same boat sent again keeps the one already found.
			boatHold = null;
		}
		else if (varbit == NET_SLOTS[0] || varbit == NET_SLOTS[1])
		{
			// Nets are only fitted or taken off ashore, and these arrive a few ticks after logging in, so the
			// answer is kept here as they change rather than asked for again every tick.
			netsFitted = readNetsFitted();
		}
		else if (varbit == NET_DEPTHS[0] || varbit == NET_DEPTHS[1])
		{
			boolean lowered = readNetsLowered();
			if (netsLowered && !lowered && client.getVarbitValue(VarbitID.SAILING_PLAYER_IS_ON_PLAYER_BOAT) == 1)
			{
				// Raising the nets keeps the fish line up a while after, but only while still aboard: nets
				// dropping out of the water as the player steps off or hops is not them being raised.
				fishActivityMillis = System.currentTimeMillis();
			}
			netsLowered = lowered;
		}
	}

	private void readNetMenu()
	{
		Widget options = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		Widget[] lines = options == null ? null : options.getDynamicChildren();
		if (lines == null || lines.length == 0 || lines[0].getText() == null)
		{
			return;
		}

		Matcher menu = NET_MENU.matcher(Text.removeTags(lines[0].getText()));
		int fish = menu.find() ? number(menu.group(1)) : -1;
		if (fish >= 0)
		{
			setFish(Math.min(NET_CAPACITY, fish));
		}
	}

	/** The nets to outline: true for full, false for lowered with nobody on it. */
	Map<GameObject, Boolean> getNetHighlights()
	{
		return netHighlights;
	}

	/**
	 * Works out which of the boat's nets to outline: each lowered net, yellow while the nets are full (on someone else's
	 * boat, only the net the player is on, as the count is their own net's), otherwise red with nobody on it. The
	 * player and crew count as on a net on any boat.
	 */
	private void findNetHighlights(WorldEntity boat, boolean ownDeck)
	{
		netHighlights.clear();
		Set<GameObject> nets = netsByView.get(boat.getWorldView().getId());
		if (nets == null || nets.isEmpty() || !config.highlightNets())
		{
			netIdleSince.clear();
			return;
		}

		Set<GameObject> worked = new HashSet<>();
		int playerSlot = playerNetSlot();
		if (playerSlot >= 0)
		{
			for (GameObject net : nets)
			{
				if (netSlot(net.getId()) == playerSlot)
				{
					worked.add(net);
				}
			}
		}
		Player player = client.getLocalPlayer();
		if (player != null && NET_ANIMATIONS.contains(player.getAnimation()))
		{
			markWorked(nets, player.getLocalLocation(), worked);
		}
		for (NPC npc : crewOnNets)
		{
			markWorked(nets, npc.getLocalLocation(), worked);
		}

		// On someone else's boat the count is the player's own net, so only the net they are on shows it.
		boolean full = netsFull();
		int tick = client.getTickCount();
		netIdleSince.keySet().retainAll(nets);
		for (GameObject net : nets)
		{
			int slot = netSlot(net.getId());
			boolean lowered = slot >= 0 && client.getVarbitValue(NET_DEPTHS[slot]) > 0;
			if (!lowered || worked.contains(net))
			{
				netIdleSince.remove(net);
			}
			else
			{
				netIdleSince.putIfAbsent(net, tick);
			}
			if (!lowered)
			{
				continue;
			}
			if (full && (ownDeck || slot == playerSlot))
			{
				netHighlights.put(net, true);
			}
			else if (netIdleSince.containsKey(net) && tick - netIdleSince.get(net) >= NET_IDLE_GRACE_TICKS)
			{
				netHighlights.put(net, false);
			}
		}
	}

	/**
	 * Finds the crew working a net on the boat the player is aboard, given its deck, or forgets them all given null. A
	 * crewmate starts working one when seen with a net animation, or named by a catch or net line while at one
	 * (noteCrewOnNet), and keeps working it while they stay on that tile, as their animation can drop out while they
	 * do; one wandering up to a net never shows it or says one, so never counts.
	 */
	private void findCrewOnNets(WorldView deck)
	{
		crewOnNets.clear();
		if (deck == null)
		{
			crewNetTiles.clear();
			return;
		}
		Map<NPC, Integer> still = crewNetTilesNext;
		still.clear();
		for (NPC npc : deck.npcs())
		{
			LocalPoint at = npc.getLocalLocation();
			if (at == null)
			{
				continue;
			}
			int tile = tileOf(at);
			Integer workedFrom = crewNetTiles.get(npc);
			if (NET_ANIMATIONS.contains(npc.getAnimation()) || workedFrom != null && workedFrom == tile)
			{
				still.put(npc, tile);
				crewOnNets.add(npc);
			}
		}
		crewNetTilesNext = crewNetTiles;
		crewNetTiles = still;
	}

	/**
	 * Counts the player's own net on someone else's boat from a chat line: their catches fill it, opening it empty,
	 * emptying it into the hold or taking all of it clears it, and taking some takes what reaches the inventory.
	 */
	private void otherBoatNet(String message, int caught)
	{
		if (caught > 0)
		{
			// Trawling there too, as the own boat's catches say.
			lastCatchTick = client.getTickCount();
			if (fishInNets >= 0)
			{
				setFish(Math.min(NET_CAPACITY, fishInNets + caught));
			}
		}
		else if (message.startsWith("There are no fish in")
			|| message.startsWith("You take all of the fish from the net"))
		{
			noteFish(0);
		}
		else if (message.startsWith("You empty the net"))
		{
			if (message.contains("not enough"))
			{
				// The hold had no room for them all, and doesn't say how many stayed. Not the player's hold to keep a
				// record of, so the message notifies every time it is said.
				notifier.notify(config.notifyHoldFull(), config.plainNotifications()
					? "The cargo hold is full." : "The cargo hold is packed to the brim.");
				setFish(-1);
			}
			else
			{
				noteFish(0);
			}
		}
		else if (message.startsWith("You take some fish from the net"))
		{
			if (inventoryTick == client.getTickCount())
			{
				takeFromNets(inventoryAdded);
			}
			else
			{
				takePending = true;
			}
		}
		else if (message.startsWith("Your net has no more space")
			&& (fishInNets >= 0 ? netsFull() : operatedNetAtDepth()))
		{
			// Said now and then with room left, so it goes by the count; with the count unknown, only from the net
			// the player is on, set to the shoal's depth, as a net at the wrong depth says it falsely.
			notifier.notify(config.notifyNetsFull(), config.plainNotifications()
				? "Your trawling net is full." : "Your net is bursting with fish.");
		}
	}

	/**
	 * The crewmate a chat line shows working a net, or null: their catch ("Jolly Jim catches three giant krill!"),
	 * their net trying for a shoal ("Jolly Jim's net is too deep to catch fish from the nearby...") or their lowering
	 * it ("Jolly Jim lowers the net.").
	 */
	private static String crewOnNetSaying(String message, boolean crewCatch)
	{
		if (crewCatch)
		{
			return message.substring(0, message.indexOf(" catches "));
		}
		int net = message.indexOf("'s net is ");
		if (net > 0 && message.contains("catch fish from the nearby"))
		{
			return message.substring(0, net);
		}
		if (!message.contains(" lowers the net."))
		{
			return null;
		}
		Matcher lowers = CREW_LOWERS.matcher(message);
		return lowers.find() ? lowers.group(1) : null;
	}

	/**
	 * A game message as plain text: without tags, and without the colour codes some lines lead with, such as
	 * "@mes_hl_red@", which removeTags leaves in. Each step only runs on a line that has what it removes.
	 */
	static String chatText(String raw)
	{
		String text = raw.indexOf('<') >= 0 ? Text.removeTags(raw) : raw;
		return text.startsWith("@") ? CHAT_COLOUR.matcher(text).replaceFirst("") : text;
	}

	/** Whether a line could be a catch, the player's or a crewmate's, before the catch patterns are run on it. */
	static boolean mightBeCatch(String message)
	{
		return message.startsWith("You catch ") || message.contains(" catches ");
	}

	/**
	 * Counts a crewmate on the boat the player is aboard as working the net they stand at, from a chat line saying so,
	 * as if seen with a net animation: one whose animation was already broken when first seen is picked up this way.
	 */
	private void noteCrewOnNet(String name)
	{
		WorldEntity boat = aboardBoat;
		if (name == null || boat == null)
		{
			return;
		}
		WorldView deck = boat.getWorldView();
		Set<GameObject> nets = netsByView.get(deck.getId());
		for (NPC npc : deck.npcs())
		{
			LocalPoint at = npc.getLocalLocation();
			if (name.equals(npc.getName()) && netAt(nets, at) != null)
			{
				crewNetTiles.put(npc, tileOf(at));
			}
		}
	}

	private static int tileOf(LocalPoint at)
	{
		return at.getSceneX() << 16 | at.getSceneY();
	}

	/** Stops counting a crewmate as working a net once the player tells them to rest: "Jolly Jim, take a rest!" */
	private void restCrewmate(ChatMessage event)
	{
		// Checked first, as most public chat isn't this.
		if (!event.getMessage().contains("take a rest!"))
		{
			return;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getName() == null
			|| !Text.sanitize(event.getName()).equals(Text.sanitize(player.getName())))
		{
			return;
		}
		Matcher rest = CREW_REST.matcher(Text.removeTags(event.getMessage()));
		if (rest.find())
		{
			String name = rest.group(1);
			crewNetTiles.keySet().removeIf(npc -> name.equals(npc.getName()));
		}
	}

	/** Marks the net nearest someone on a net as worked, if they stand within reach of it. */
	private static void markWorked(Set<GameObject> nets, LocalPoint at, Set<GameObject> worked)
	{
		GameObject net = netAt(nets, at);
		if (net != null)
		{
			worked.add(net);
		}
	}

	/** The net nearest a place, if within reach of it, or null. */
	private static GameObject netAt(Set<GameObject> nets, LocalPoint at)
	{
		if (nets == null || at == null)
		{
			return null;
		}
		GameObject nearest = null;
		long nearestSquared = Long.MAX_VALUE;
		for (GameObject net : nets)
		{
			LocalPoint netAt = net.getLocalLocation();
			long dx = netAt.getX() - at.getX();
			long dy = netAt.getY() - at.getY();
			long squared = dx * dx + dy * dy;
			if (squared < nearestSquared)
			{
				nearestSquared = squared;
				nearest = net;
			}
		}
		long reach = (long) NET_REACH_TILES * Perspective.LOCAL_TILE_SIZE;
		return nearestSquared <= reach * reach ? nearest : null;
	}

	/** Whether the player is on a net set to the nearest shoal's depth. */
	private boolean operatedNetAtDepth()
	{
		int slot = playerNetSlot();
		Player player = client.getLocalPlayer();
		WorldEntity boat = aboardBoat;
		if (slot < 0 && player != null && boat != null && NET_ANIMATIONS.contains(player.getAnimation()))
		{
			GameObject net = netAt(netsByView.get(boat.getWorldView().getId()), player.getLocalLocation());
			slot = net == null ? -1 : netSlot(net.getId());
		}
		int wanted = getNearestDepth().netDepth();
		return slot >= 0 && wanted > 0 && client.getVarbitValue(NET_DEPTHS[slot]) == wanted;
	}

	/**
	 * The net slot the player is locked into, 0 or 1, by the game's own record of the facility they are on, or -1 if
	 * not on a net. Unlike their animation, which can drop out while they work it, this holds until they step off.
	 */
	private int playerNetSlot()
	{
		if (client.getVarbitValue(VarbitID.SAILING_BOAT_FACILITY_LOCKEDIN) == 0)
		{
			return -1;
		}
		// Counted from 1, where the net slots name their hotspot counted from 0.
		int hotspot = client.getVarbitValue(VarbitID.SAILING_FACILITY_HOTSPOT_NUMBER) - 1;
		for (int slot = 0; slot < NET_SLOTS.length; slot++)
		{
			if (hotspot > 0 && client.getVarbitValue(NET_SLOTS[slot]) == hotspot)
			{
				return slot;
			}
		}
		return -1;
	}

	/**
	 * The slot a net object is in, 0 or 1, for its depth varbit, or -1 if it isn't fitted. The skiff's single net is
	 * whichever slot is filled; the sloop's are found by the hotspot each slot names.
	 */
	private int netSlot(int id)
	{
		if (SINGLE_NETS.contains(id))
		{
			return client.getVarbitValue(NET_SLOTS[0]) > 0 ? 0 : client.getVarbitValue(NET_SLOTS[1]) > 0 ? 1 : -1;
		}
		boolean starboard = STARBOARD_NETS.contains(id);
		int hotspot = starboard ? STARBOARD_HOTSPOT : PORT_HOTSPOT;
		for (int slot = 0; slot < NET_SLOTS.length; slot++)
		{
			if (client.getVarbitValue(NET_SLOTS[slot]) == hotspot)
			{
				return slot;
			}
		}
		return -1;
	}

	private static boolean isNet(int id)
	{
		return SINGLE_NETS.contains(id) || STARBOARD_NETS.contains(id) || PORT_NETS.contains(id);
	}

	/**
	 * The cargo hold on the player's own boat, or null if not aboard or it isn't in sight.
	 */
	GameObject getOwnHold()
	{
		WorldEntity own = ownBoat;
		return own == null ? null : holdByView.get(own.getWorldView().getId());
	}

	/**
	 * Whether trawling is under way: a net lowered, fish in the nets, a catch in the last 3 minutes, or trawled fish
	 * known to be in the hold. Without it, a display at the helm showing only "Fish: 0" or "Fish: ?" hides.
	 */
	boolean isTrawling()
	{
		CargoHold hold = boatHold;
		return netsLowered || fishInNets > 0 || caughtRecently() || hold != null && hold.trawled() > 0;
	}

	/** Whether a trawling catch, the player's or the crew's, came in the last 3 minutes. */
	boolean caughtRecently()
	{
		return within(lastCatchTick, client.getTickCount(), TRAWL_AWAY_TICKS);
	}

	/**
	 * Whether a tick noted earlier (-1 for none) is at most this many ticks before now. One that seems to be after now,
	 * as from before a logout if the tick count starts over, counts as too long ago.
	 */
	static boolean within(int then, int now, int ticks)
	{
		int since = now - then;
		return then >= 0 && since >= 0 && since <= ticks;
	}

	/**
	 * Whether the hold is to be outlined: while sea spot fishing with a full inventory, but not once the hold is 90%
	 * full, as for the spot arrow, as then it's time to bank.
	 */
	boolean isHoldHighlighted()
	{
		// The plain fields first, so the setting is only looked up while it could matter.
		return seaFishing && inventoryFilled >= INVENTORY_SLOTS && !spotHoldFull && config.highlightCargoHold();
	}

	private void countInventory(ItemContainer inventory)
	{
		int filled = 0;
		for (Item item : inventory == null ? new Item[0] : inventory.getItems())
		{
			if (item.getId() >= 0)
			{
				filled++;
			}
		}

		// Fish don't stack, so the slots that filled are the fish that arrived.
		inventoryAdded = inventoryFilled < 0 ? -1 : Math.max(0, filled - inventoryFilled);
		inventoryFilled = filled;
		inventoryTick = client.getTickCount();
		countTransfers(inventory);
		if (takePending)
		{
			takePending = false;
			takeFromNets(inventoryAdded);
		}
	}

	/**
	 * Counts the offcuts and sea spot catches in the inventory, and what of them just went into
	 * or came out of the hold, while its screen is open or just shut: the only times they can, and so only once its
	 * contents are known. Any other time they aren't looked for at all, and the count starts again from the inventory
	 * as the screen next opens.
	 */
	private void countTransfers(ItemContainer inventory)
	{
		int tick = client.getTickCount();
		if (inventory == null || !holdOpen && (holdClosedTick < 0 || tick - holdClosedTick > DEPOSIT_TICKS))
		{
			inventoryPlain = -1;
			inventoryFine = -1;
			inventorySea = null;
			return;
		}

		int plain = 0;
		int fine = 0;
		int[] sea = new int[CargoHold.SEA_FISH.length];
		for (Item item : inventory.getItems())
		{
			int id = item.getId();
			if (id == ItemID.BRUT_FISH_CUTS)
			{
				plain += item.getQuantity();
			}
			else if (id == ItemID.SAILING_FINE_FISH_OFFCUTS)
			{
				fine += item.getQuantity();
			}
			else
			{
				int kind = seaFishKind(id);
				if (kind >= 0)
				{
					sea[kind] += item.getQuantity();
				}
			}
		}
		countDeposits(plain, fine);
		countSeaTransfers(sea);
	}

	/**
	 * Adds offcuts that just left the inventory aboard to the hold's count. The hold is only sent while its
	 * screen is open, so offcuts put in just as it is shut never show up there; the inventory is always
	 * sent. When the hold's own contents came the same tick they already include the deposit, and win.
	 */
	private void countDeposits(int plain, int fine)
	{
		if (fineBait >= 0 && inventoryFine >= 0 && holdTick != client.getTickCount()
			&& (plain < inventoryPlain || fine < inventoryFine)
			&& client.getVarbitValue(VarbitID.SAILING_PLAYER_IS_ON_PLAYER_BOAT) == 1)
		{
			plainBait += Math.max(0, inventoryPlain - plain);
			fineBait += Math.max(0, inventoryFine - fine);
			if (plainBait + fineBait > 0)
			{
				ranOutOfBait = false;
			}
			depositTick = client.getTickCount();
			baitedLabel = baitLabel();
		}
		inventoryPlain = plain;
		inventoryFine = fine;
	}

	/**
	 * Moves sea spot catches between the inventory aboard and the hold's count, the same way
	 * as offcuts: not when its own contents came the same tick, and only into a hold whose contents are known.
	 * Those leaving the inventory went in, and those arriving came out, unless a catch was announced that tick.
	 */
	private void countSeaTransfers(int[] sea)
	{
		CargoHold record = boatRecord();
		int tick = client.getTickCount();
		if (record.known() && inventorySea != null && holdTick != tick
			&& client.getVarbitValue(VarbitID.SAILING_PLAYER_IS_ON_PLAYER_BOAT) == 1)
		{
			for (int kind = 0; kind < sea.length; kind++)
			{
				if (sea[kind] < inventorySea[kind])
				{
					record.deposit(kind, inventorySea[kind] - sea[kind], tick);
				}
				else if (sea[kind] > inventorySea[kind] && seaCatchTick != tick)
				{
					record.withdraw(kind, sea[kind] - inventorySea[kind]);
				}
			}
		}
		inventorySea = sea;
	}

	private static int seaFishKind(int item)
	{
		for (int kind = 0; kind < CargoHold.SEA_FISH.length; kind++)
		{
			if (CargoHold.SEA_FISH[kind] == item)
			{
				return kind;
			}
		}
		return -1;
	}

	/**
	 * The game's number for the player's boat last boarded, which is the one they are on while aboard: what each
	 * boat's hold is kept by.
	 */
	private int boatNumber()
	{
		return client.getVarbitValue(VarbitID.SAILING_LAST_PERSONAL_BOAT_BOARDED);
	}

	private void takeFromNets(int taken)
	{
		setFish(taken < 0 || fishInNets < 0 ? -1 : Math.max(0, fishInNets - taken));
	}

	private void setFish(int fish)
	{
		fishInNets = fish;
		fishLabel = fishLabel(fish);
	}

	/**
	 * Sets the count after the nets were just emptied or found empty, which keeps the fish line up for a
	 * while even though there is nothing in them. Anything that leaves fish in the nets, or an unknown count,
	 * shows the line anyway, so it goes through setFish.
	 */
	private void noteFish(int fish)
	{
		setFish(fish);
		if (fish == 0)
		{
			netsEmptied = true;
		}
		fishActivityMillis = System.currentTimeMillis();
	}

	/**
	 * Sets the count without anything having been done with the nets, for logging in, stepping off the boat
	 * or the plugin starting, and forgets any recent activity so the fish line doesn't come up by itself.
	 * Logging out and stepping off both empty the nets, so a known empty count here also counts as
	 * emptied, and the next time they fill is a fill from empty; an unknown count doesn't.
	 */
	private void resetFish(int fish)
	{
		setFish(fish);
		netsEmptied = fish == 0;
		fishActivityMillis = -1;
	}

	/**
	 * Whether the fish line is worth showing: whenever there are fish in the nets or the count is not known,
	 * whenever a net is lowered, since that is trawling under way, and otherwise for a minute after the nets
	 * were last emptied, found empty or raised.
	 */
	boolean fishLineWanted(long nowMillis)
	{
		return fishInNets != 0 || netsLowered
			|| (fishActivityMillis >= 0 && nowMillis - fishActivityMillis <= FISH_LINE_LINGER_MILLIS);
	}

	private static String fishLabel(int fish)
	{
		if (fish >= NET_CAPACITY)
		{
			return "Nets full";
		}
		return "Fish: " + (fish < 0 ? "?" : Integer.toString(fish));
	}

	/**
	 * Adds a catch to the count of its fish and to the total, and to the lifetime count of fish caught by the player
	 * or by the crew, the rest of a catch line after its count naming the fish. A catch of anything other than a
	 * trawled fish isn't counted.
	 */
	private void countCatch(String named, int fish, boolean byCaptain)
	{
		String lower = named.toLowerCase();
		for (String kind : CAUGHT_FISH.keySet())
		{
			if (lower.startsWith(kind))
			{
				caught.merge(kind, fish, Integer::sum);
				caughtTotal += fish;
				countLifetime(lifetimeKey(kind), fish);
				countLifetime(byCaptain ? LIFETIME_CAPTAIN_KEY : LIFETIME_CREW_KEY, fish);
				if (!catchBoxes.containsKey(kind))
				{
					addFishBox(kind);
				}
				return;
			}
		}
	}

	/**
	 * Puts up the info boxes for the total caught and the fish in the nets, and one for each fish already caught,
	 * as counts kept from before the plugin was last switched off.
	 */
	private void addCatchBoxes()
	{
		totalBox = new CatchInfoBox(itemManager.getImage(ItemID.FISH_BARREL_OPEN), this, "Fish caught",
			() -> caughtTotal, this::lifetimeTotal, () -> config.showTotalCaughtInfoBox() && caughtTotal > 0 && loggedIn());
		totalBox.getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_INFOBOX, RESET_SESSION, "Fish caught"));
		infoBoxManager.addInfoBox(totalBox);

		// The player's own boat's nets, or their own net on someone else's.
		netsBox = new CatchInfoBox(itemManager.getImage(ItemID.BIG_NET), this, "Fish in the nets", () -> fishInNets,
			null, () -> config.showFishInNetsInfoBox() && aboardBoat != null && netsFitted && loggedIn());
		infoBoxManager.addInfoBox(netsBox);

		for (String kind : caught.keySet())
		{
			addFishBox(kind);
		}
	}

	private void addFishBox(String kind)
	{
		String name = Character.toUpperCase(kind.charAt(0)) + kind.substring(1);
		CatchInfoBox box = new CatchInfoBox(itemManager.getImage(CAUGHT_FISH.get(kind)), this, name + " caught",
			() -> caught.getOrDefault(kind, 0), () -> lifetime(lifetimeKey(kind)), () -> config.showFishCaughtInfoBoxes() && loggedIn());
		catchBoxes.put(kind, box);
		infoBoxManager.addInfoBox(box);
	}

	private boolean loggedIn()
	{
		return client.getGameState() == GameState.LOGGED_IN;
	}

	/**
	 * Closing the client saves the lifetime catches straight away, rather than losing up to a minute of them.
	 */
	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		CompletableFuture<Void> saved = new CompletableFuture<>();
		clientThread.invoke(() ->
		{
			saveLifetime();
			saved.complete(null);
		});
		event.waitFor(saved);
	}

	/**
	 * Puts Reset lifetime on the total's menu while Shift is held, and takes it off again once it isn't.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		if (totalBox == null)
		{
			return;
		}

		boolean shift = client.isKeyPressed(KeyCode.KC_SHIFT);
		List<OverlayMenuEntry> entries = totalBox.getMenuEntries();
		if (shift != entries.contains(resetLifetimeEntry))
		{
			if (shift)
			{
				entries.add(resetLifetimeEntry);
			}
			else
			{
				entries.remove(resetLifetimeEntry);
			}
		}
	}

	/** Puts Reset session on the menu over the hold book's button, and Reset lifetime too while Shift is held. */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		addOpenLog();
		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || !holdBook.overButton(mouse.getX(), mouse.getY()))
		{
			return;
		}
		String target = ColorUtil.wrapWithColorTag("Trawling Log", JagexColors.MENU_TARGET);
		if (client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			client.getMenu().createMenuEntry(-1)
				.setOption(RESET_LIFETIME)
				.setTarget(target)
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> resetLifetime());
		}
		client.getMenu().createMenuEntry(-1)
			.setOption(RESET_SESSION)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.onClick(entry -> resetSession());
	}

	/** Resets each account's lifetime counts once, the first time it is seen with the flag unset. */
	private void freshStart()
	{
		String profile = configManager.getRSProfileKey();
		if (profile == null || profile.equals(freshChecked))
		{
			return;
		}
		freshChecked = profile;
		if (configManager.getRSProfileConfiguration(TrawlingPlusConfig.GROUP, LIFETIME_FRESH_KEY) == null)
		{
			resetLifetime();
			configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, LIFETIME_FRESH_KEY, true);
		}
	}

	/**
	 * Every lifetime count: each fish, the captain's and crew's catches and time on nets, each crewmate's time on
	 * nets, the bait used and the Statistics. The Curiosities found are a record, not a count, and are never cleared.
	 */
	private void resetLifetime()
	{
		for (String kind : CAUGHT_FISH.keySet())
		{
			configManager.unsetRSProfileConfiguration(TrawlingPlusConfig.GROUP, lifetimeKey(kind));
		}
		Set<String> keys = namedKeys(LIFETIME_WORKER_KEY);
		keys.addAll(namedKeys(LIFETIME_CATCHER_KEY));
		keys.addAll(List.of(LIFETIME_CAPTAIN_KEY, LIFETIME_CREW_KEY, LIFETIME_CAPTAIN_NET_KEY,
			LIFETIME_CREW_NET_KEY, LIFETIME_BAIT_KEY, LIFETIME_CAPTAIN_NET_FISH_KEY, LIFETIME_CREW_NET_FISH_KEY,
			LIFETIME_TRUST_KEY, LIFETIME_NETS_FILLED_KEY, LIFETIME_BEST_SESSION_KEY, LIFETIME_TRAWL_TICKS_KEY));
		lifetimeUnsaved.clear();
		heldCaptainNetTicks = 0;
		heldCrewNetTicks.clear();
		heldTrawlTicks = -1;
		heldBeforeSession.clear();
		savedNamedKeys.clear();
		caughtBeforeReset = caughtTotal;
		for (String key : keys)
		{
			configManager.unsetRSProfileConfiguration(TrawlingPlusConfig.GROUP, key);
		}
	}

	/**
	 * Reset session on the total's info box starts every count of fish caught over, and Reset lifetime, there while
	 * Shift is held, every lifetime count.
	 */
	@Subscribe
	public void onInfoBoxMenuClicked(InfoBoxMenuClicked event)
	{
		if (event.getInfoBox() != totalBox)
		{
			return;
		}

		if (event.getEntry() == resetLifetimeEntry)
		{
			resetLifetime();
			return;
		}

		if (RESET_SESSION.equals(event.getEntry().getOption()))
		{
			resetSession();
		}
	}

	/**
	 * Puts Open Trawling Log on a cargo hold's right-click menu, just below its Examine, so the book can be read from
	 * anywhere on the boat. It only opens the book: nothing is sent to the game, and the hold's own options are left
	 * as they are.
	 */
	private void addOpenLog()
	{
		if (!config.showHoldBook() || !config.holdMenuOpensBook())
		{
			return;
		}
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		for (int i = 0; i < entries.length; i++)
		{
			MenuEntry entry = entries[i];
			if (entry.getType() == MenuAction.EXAMINE_OBJECT && CARGO_HOLDS.contains(entry.getIdentifier()))
			{
				client.getMenu().createMenuEntry(i)
					.setOption("Open")
					.setTarget(ColorUtil.wrapWithColorTag("Trawling Log", JagexColors.MENU_TARGET))
					.setType(MenuAction.RUNELITE)
					.onClick(clicked -> holdBook.openAnywhere());
				return;
			}
		}
	}

	/** Starts the session over: every count of fish caught and the session's statistics. */
	private void resetSession()
	{
		caught.clear();
		caughtTotal = 0;
		caughtBeforeReset = 0;
		sessionCounts.clear();
		holdBackFromSession();
		for (CatchInfoBox box : catchBoxes.values())
		{
			infoBoxManager.removeInfoBox(box);
		}
		catchBoxes.clear();
	}

	/**
	 * The trawling log's pages: two pages to open the book, the fish caught since the counts were last reset and the
	 * account's lifetime catches, each with a total, the rates for this session and lifetime, the other statistics,
	 * then the Worker log, each over two pages. Client thread only.
	 */
	List<BookPage> bookPages()
	{
		List<BookPage.Line> session = new ArrayList<>();
		List<BookPage.Line> life = new ArrayList<>();
		// The lifetime total is added up here rather than with lifetimeTotal(), which would read every fish's saved
		// count from the profile a second time; this runs once a tick while the book is open.
		int lifeTotal = 0;
		for (String kind : BOOK_FISH)
		{
			String name = Character.toUpperCase(kind.charAt(0)) + kind.substring(1);
			int lifetime = lifetime(lifetimeKey(kind));
			lifeTotal += lifetime;
			session.add(BookPage.row(name, QuantityFormatter.formatNumber(caught.getOrDefault(kind, 0))));
			life.add(config.showLifetimeStars() ? starredRow(kind, name, lifetime)
				: BookPage.row(name, QuantityFormatter.formatNumber(lifetime)));
		}
		// Half a blank line sets the total apart from the fish above it.
		session.add(BookPage.blank());
		life.add(BookPage.blank());
		session.add(BookPage.row("Total", QuantityFormatter.formatNumber(caughtTotal)));
		life.add(BookPage.row("Total", QuantityFormatter.formatNumber(lifeTotal)));
		Player player = client.getLocalPlayer();
		String name = player != null && player.getName() != null ? player.getName() : "";
		// Signed with the player's name at the foot of the page, beside a wax seal.
		BookPage cover = new BookPage("Trawling Log", List.of(
			BookPage.text("A record of the fish hauled aboard, and of the hands who brought them in.")),
			name.isEmpty() ? null : name);
		BookPage foreword = new BookPage("On trawling", List.of(
			BookPage.text("Shoals of fish ride predictable currents across the seas, pausing to feed before "
				+ "moving on."),
			BookPage.blank(),
			BookPage.text("Lower the nets to the depth they swim at, keep the boat steady, and the nets "
				+ "will fill.")));
		BookPage workers = new BookPage("Worker log", List.of(
			BookPage.heading("Catches"),
			BookPage.row("Captain", QuantityFormatter.formatNumber(lifetime(LIFETIME_CAPTAIN_KEY))),
			BookPage.row("Crew", QuantityFormatter.formatNumber(lifetime(LIFETIME_CREW_KEY))),
			BookPage.blank(),
			BookPage.heading("Time working nets").tip("Time spent working a net while trawling a shoal."),
			BookPage.row("Captain", hoursMinutes(lifetime(LIFETIME_CAPTAIN_NET_KEY))),
			BookPage.row("Crew", hoursMinutes(lifetime(LIFETIME_CREW_NET_KEY)))));
		// The Worker log's second page, across from it, so it has no title of its own.
		BookPage hardest = new BookPage("", hardestWorkerLines());
		// The rates for this session and lifetime across from each other, then the other statistics.
		BookPage sessionRates = new BookPage("This session", rateLines(caughtTotal, sessionCounts::get));
		BookPage lifetimeRates = new BookPage("Lifetime", rateLines(
			lifetime(LIFETIME_CAPTAIN_KEY) + lifetime(LIFETIME_CREW_KEY), this::lifetime));
		BookPage statistics = new BookPage("Statistics", List.of(
			BookPage.heading("Trawler's trust").tip(TRUST_TIP),
			BookPage.centred(QuantityFormatter.formatNumber(lifetime(LIFETIME_TRUST_KEY))).tip(TRUST_TIP),
			BookPage.blank(),
			BookPage.heading("Nets filled from empty").tip(FILLED_TIP),
			BookPage.centred(QuantityFormatter.formatNumber(lifetime(LIFETIME_NETS_FILLED_KEY))).tip(FILLED_TIP)));
		// The Statistics' second page, across from it.
		BookPage moreStatistics = new BookPage("", List.of(
			BookPage.heading("Best session").tip(BEST_TIP),
			BookPage.centred(QuantityFormatter.formatNumber(
				Math.max(caughtTotal - caughtBeforeReset, savedLifetime(LIFETIME_BEST_SESSION_KEY)))).tip(BEST_TIP),
			BookPage.blank(),
			BookPage.heading("Bait used").tip(BAIT_TIP),
			BookPage.centred(QuantityFormatter.formatNumber(lifetime(LIFETIME_BAIT_KEY))).tip(BAIT_TIP)));
		// Each section's first page carries its tab.
		List<BookPage> book = new ArrayList<>(List.of(cover, foreword,
			new BookPage("This session", session).withTab("Catches"), new BookPage("Lifetime", life),
			sessionRates, lifetimeRates, statistics.withTab("Statistics"), moreStatistics,
			workers.withTab("Worker log"), hardest));
		addCuriosities(book);
		return book;
	}

	/**
	 * The Curiosities at the back of the book: a page saying how many have been found, then one per curiosity found,
	 * earliest first (those from before the log was kept first of all), its entry, date found and picture, then those
	 * not yet found, each with its hint and a faint shape of it.
	 */
	private void addCuriosities(List<BookPage> book)
	{
		// Found pages by the date they were found, as saved ("2026-11-12" sorts by date), the log's before any.
		List<Map.Entry<String, BookPage>> found = new ArrayList<>();
		List<BookPage> unfound = new ArrayList<>();
		for (Curiosity curiosity : Curiosity.values())
		{
			String date = configManager.getRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.foundKey());
			if (date == null)
			{
				unfound.add(new BookPage(curiosity.getUnfoundTitle(), List.of(BookPage.hint(curiosity.getHint())),
					null, curiosity.getItemId(), true));
				continue;
			}
			boolean beforeTheLog = Curiosity.FROM_LOG.equals(date);
			String finder = configManager.getRSProfileConfiguration(TrawlingPlusConfig.GROUP, curiosity.finderKey());
			found.add(Map.entry(beforeTheLog ? "" : date, new BookPage(curiosity.getName(), List.of(
				BookPage.heading(beforeTheLog ? Curiosity.BEFORE_THE_LOG : journalDate(date)),
				BookPage.blank(),
				BookPage.entry(curiosity.entryFor(finder, beforeTheLog))),
				null, curiosity.getItemId(), false)));
		}
		// A stable sort, so finds on the same day keep the curiosities' own order.
		found.sort(Map.Entry.comparingByKey());
		book.add(new BookPage("Curiosities", List.of(
			BookPage.centred("Odd things the sea has given up, written down as they were found."),
			BookPage.blank(),
			BookPage.heading("Found"),
			BookPage.centred(found.size() + " of " + Curiosity.values().length))).withTab("Curiosities"));
		found.forEach(entry -> book.add(entry.getValue()));
		book.addAll(unfound);
	}

	/** A saved date ("2026-11-12") as the journal writes it ("12 Nov 2026"), or as saved if it can't be read. */
	private static String journalDate(String saved)
	{
		try
		{
			return LocalDate.parse(saved).format(JOURNAL_DATE);
		}
		catch (DateTimeParseException e)
		{
			return saved;
		}
	}

	/**
	 * A rates page's lines: fish per hour while trawling, then on the nets for the captain and the crew, from a fish
	 * total and the other counts by their lifetime keys.
	 */
	private static List<BookPage.Line> rateLines(int fish, Function<String, Integer> counts)
	{
		ToIntFunction<String> count = key ->
		{
			Integer value = counts.apply(key);
			return value != null ? value : 0;
		};
		return List.of(
			BookPage.heading("Fish per hour").tip(FISH_PER_HOUR_TIP),
			BookPage.centred(fishPerHour(fish, count.applyAsInt(LIFETIME_TRAWL_TICKS_KEY))).tip(FISH_PER_HOUR_TIP),
			BookPage.blank(),
			BookPage.heading("Working the nets").tip("Fish caught per hour while working a net"
				+ "</br>near a shoal, leaving out sailing and banking."),
			BookPage.row("Captain", fishPerHour(count.applyAsInt(LIFETIME_CAPTAIN_NET_FISH_KEY),
				count.applyAsInt(LIFETIME_CAPTAIN_NET_KEY))).tip("Your catches over your time on a net."),
			BookPage.row("Crew", fishPerHour(count.applyAsInt(LIFETIME_CREW_NET_FISH_KEY),
				count.applyAsInt(LIFETIME_CREW_NET_KEY))).tip("Your crew's catches over their time on nets,"
				+ "</br>each crewmate's time added together."));
	}

	/**
	 * Fish caught per hour, from a count of fish and the ticks they took, or a dash with under a minute of time, which
	 * a few quick catches would make far too high.
	 */
	private static String fishPerHour(int fish, int ticks)
	{
		if (ticks < RATE_MIN_TICKS)
		{
			return "-";
		}
		// 6,000 ticks to the hour.
		return QuantityFormatter.formatNumber(Math.round(fish * 6000.0 / ticks));
	}

	/** A fish's row on the Lifetime page, with its stars and a tooltip saying how far to the next one. */
	private static BookPage.Line starredRow(String kind, String name, int caught)
	{
		int[] milestones = STAR_MILESTONES.get(kind);
		int reached = 0;
		while (reached < milestones.length && caught >= milestones[reached])
		{
			reached++;
		}
		String tip = reached == milestones.length ? "All stars earned."
			: QuantityFormatter.formatNumber(milestones[reached] - caught) + " more " + kind + " to the next star.";
		return BookPage.row(name, QuantityFormatter.formatNumber(caught)).withStars(reached).tip(tip);
	}

	/** Ticks as hours and two-digit minutes, such as "12h 34m". */
	private static String hoursMinutes(int ticks)
	{
		long minutes = ticks * 600L / 60_000;
		return String.format("%dh %02dm", minutes / 60, minutes % 60);
	}

	/**
	 * Adds a tick on a net for the player, on any boat, and one for each crewmate on a net when the deck is the
	 * player's own, while a trawling shoal is in view. Until a catch or an attempt in reach by that side proves the
	 * visit, its ticks are held back, and dropped if the shoal leaves view first, so passing a shoal isn't counted.
	 */
	private void countNetTime(boolean ownDeck)
	{
		Player player = client.getLocalPlayer();
		if (!shoalInView())
		{
			heldCaptainNetTicks = 0;
			heldCrewNetTicks.clear();
			heldBeforeSession.keySet().retainAll(Set.of(LIFETIME_TRAWL_TICKS_KEY));
			captainNetProven = false;
			crewNetProven = false;
			return;
		}
		if (player == null)
		{
			return;
		}
		if (playerNetSlot() >= 0 || NET_ANIMATIONS.contains(player.getAnimation()))
		{
			if (captainNetProven)
			{
				countLifetime(LIFETIME_CAPTAIN_NET_KEY, 1);
			}
			else
			{
				heldCaptainNetTicks++;
			}
		}

		if (!ownDeck)
		{
			return;
		}
		ObjIntConsumer<String> into = crewNetProven ? this::countLifetime
			: (key, ticks) -> heldCrewNetTicks.merge(key, ticks, Integer::sum);
		for (NPC npc : crewOnNets)
		{
			if (npc.getName() != null)
			{
				into.accept(LIFETIME_WORKER_KEY + npc.getName(), 1);
			}
		}
		if (!crewOnNets.isEmpty())
		{
			into.accept(LIFETIME_CREW_NET_KEY, crewOnNets.size());
		}
	}

	/**
	 * Counts the captain's or the crew's net time held back for the shoal in view, and every tick of theirs on nets
	 * after it while one stays in view.
	 */
	private void proveNetTime(boolean captain)
	{
		if (!shoalInView())
		{
			return;
		}
		if (captain && !captainNetProven)
		{
			captainNetProven = true;
			countHeld(LIFETIME_CAPTAIN_NET_KEY, heldCaptainNetTicks);
			heldCaptainNetTicks = 0;
		}
		else if (!captain && !crewNetProven)
		{
			crewNetProven = true;
			heldCrewNetTicks.forEach(this::countHeld);
			heldCrewNetTicks.clear();
		}
	}

	/** Whether any trawling shoal is loaded in the scene, which time on nets needs to count. */
	private boolean shoalInView()
	{
		// Kept from spawns whatever Show guides is set to, unlike the shoals followed for the guides.
		return !clickboxByView.isEmpty();
	}

	/** Each crewmate's lifetime key with this prefix in the account's profile, saved or not yet. */
	private Set<String> namedKeys(String prefix)
	{
		String profile = configManager.getRSProfileKey();
		if (profile != null && !profile.equals(savedNamedKeysProfile))
		{
			savedNamedKeys.clear();
			savedNamedKeysProfile = profile;
		}
		Set<String> saved = savedNamedKeys.get(prefix);
		if (saved == null && profile != null)
		{
			// Looking keys up by prefix goes through every setting RuneLite holds, so it is done once per account,
			// then kept up to date as crewmates' counts are saved.
			saved = new HashSet<>(configManager.getRSProfileConfigurationKeys(TrawlingPlusConfig.GROUP, profile,
				prefix));
			savedNamedKeys.put(prefix, saved);
		}
		Set<String> keys = saved != null ? new HashSet<>(saved) : new HashSet<>();
		for (String key : lifetimeUnsaved.keySet())
		{
			if (key.startsWith(prefix))
			{
				keys.add(key);
			}
		}
		return keys;
	}

	/** The crewmate with the highest lifetime count under this prefix, with the count, or null with none yet. */
	private Map.Entry<String, Integer> topCrewmate(String prefix)
	{
		Map.Entry<String, Integer> top = null;
		for (String key : namedKeys(prefix))
		{
			int count = lifetime(key);
			if (count > 0 && (top == null || count > top.getValue()))
			{
				top = Map.entry(key.substring(prefix.length()), count);
			}
		}
		return top;
	}

	/** The hardest worker page's lines: the crewmate longest on the nets, and the one who has caught the most. */
	private List<BookPage.Line> hardestWorkerLines()
	{
		List<BookPage.Line> lines = new ArrayList<>();
		String hardestTip = "The crewmate who has spent longest working the nets.";
		lines.add(BookPage.heading("Hardest worker").tip(hardestTip));
		Map.Entry<String, Integer> hardest = topCrewmate(LIFETIME_WORKER_KEY);
		if (hardest == null)
		{
			lines.add(BookPage.centred("None yet").tip(hardestTip));
		}
		else
		{
			lines.add(BookPage.centred(hardest.getKey()).tip(hardestTip));
			lines.add(BookPage.centred(hoursMinutes(hardest.getValue())).tip(hardestTip));
		}
		lines.add(BookPage.blank());
		String catcherTip = "The crewmate who has caught the most fish.";
		lines.add(BookPage.heading("Top catcher").tip(catcherTip));
		Map.Entry<String, Integer> catcher = topCrewmate(LIFETIME_CATCHER_KEY);
		if (catcher == null)
		{
			lines.add(BookPage.centred("None yet").tip(catcherTip));
		}
		else
		{
			lines.add(BookPage.centred(catcher.getKey()).tip(catcherTip));
			lines.add(BookPage.centred(QuantityFormatter.formatNumber(catcher.getValue()) + " fish").tip(catcherTip));
		}
		return lines;
	}

	/**
	 * Adds held time to a lifetime count, and to the same count for this session, less whatever of it was already held
	 * when the session's counts were reset.
	 */
	private void countHeld(String key, int amount)
	{
		lifetimeUnsaved.merge(key, amount, Integer::sum);
		int session = amount - heldBeforeSession.getOrDefault(key, 0);
		heldBeforeSession.remove(key);
		if (session > 0)
		{
			sessionCounts.merge(key, session, Integer::sum);
		}
	}

	/** Notes everything being held as the session's counts reset, so none of it goes to the new session. */
	private void holdBackFromSession()
	{
		heldBeforeSession.clear();
		if (heldTrawlTicks > 0)
		{
			heldBeforeSession.put(LIFETIME_TRAWL_TICKS_KEY, heldTrawlTicks);
		}
		if (heldCaptainNetTicks > 0)
		{
			heldBeforeSession.put(LIFETIME_CAPTAIN_NET_KEY, heldCaptainNetTicks);
		}
		heldBeforeSession.putAll(heldCrewNetTicks);
	}

	/** Adds to a lifetime count, and to the same count for this session. */
	private void countLifetime(String key, int amount)
	{
		lifetimeUnsaved.merge(key, amount, Integer::sum);
		sessionCounts.merge(key, amount, Integer::sum);
	}

	/** A lifetime count, by its key in the account's profile: what is saved there, and what hasn't been yet. */
	private int lifetime(String key)
	{
		return savedLifetime(key) + lifetimeUnsaved.getOrDefault(key, 0);
	}

	private int lifetimeTotal()
	{
		int total = 0;
		for (String kind : CAUGHT_FISH.keySet())
		{
			total += lifetime(lifetimeKey(kind));
		}
		return total;
	}

	private int savedLifetime(String key)
	{
		String saved = configManager.getRSProfileConfiguration(TrawlingPlusConfig.GROUP, key);
		try
		{
			return saved == null ? 0 : Integer.parseInt(saved);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/**
	 * Adds the lifetime catches not yet saved to what the account's profile has.
	 */
	private void saveLifetime()
	{
		if (lifetimeUnsaved.isEmpty() || configManager.getRSProfileKey() == null)
		{
			return;
		}

		// Every catch adds to what is unsaved, so the best session is never left behind.
		int session = caughtTotal - caughtBeforeReset;
		if (session > savedLifetime(LIFETIME_BEST_SESSION_KEY))
		{
			configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, LIFETIME_BEST_SESSION_KEY, session);
		}

		for (Map.Entry<String, Integer> unsaved : lifetimeUnsaved.entrySet())
		{
			String key = unsaved.getKey();
			configManager.setRSProfileConfiguration(TrawlingPlusConfig.GROUP, key,
				savedLifetime(key) + unsaved.getValue());
			if (configManager.getRSProfileKey().equals(savedNamedKeysProfile))
			{
				for (Map.Entry<String, Set<String>> named : savedNamedKeys.entrySet())
				{
					if (key.startsWith(named.getKey()))
					{
						named.getValue().add(key);
					}
				}
			}
		}
		lifetimeUnsaved.clear();
	}

	private static String lifetimeKey(String kind)
	{
		return LIFETIME_KEY + kind.replace(' ', '_');
	}

	/**
	 * A count as the game writes it, in figures or in words, or -1 for one it isn't known to write.
	 */
	private static int number(String written)
	{
		if (!written.isEmpty() && written.length() < 5 && written.chars().allMatch(Character::isDigit))
		{
			return Integer.parseInt(written);
		}
		return NUMBER_WORDS.getOrDefault(written.toLowerCase(), -1);
	}

	/**
	 * How much bait is left that the nearest shoal takes, or -1 when that is not known. A shoal that takes
	 * either kind counts both together; every other shoal counts only the fine offcuts.
	 */
	private int baitLeft()
	{
		if (fineBait < 0 || nearestShoal == null)
		{
			return -1;
		}
		return takesPlainOffcuts(nearestShoal) ? plainBait + fineBait : fineBait;
	}

	/**
	 * A crewmate on the chum station found no offcuts in the hold, so the nearest shoal isn't baited and the
	 * hold has none of the offcuts it takes. On a shoal that takes plain offcuts that is both kinds; on one
	 * that takes only fine, the fine count is known to be empty, but the plain count is left alone while it
	 * isn't known, since the two are only ever known together.
	 */
	private void noBait()
	{
		baitFailedTick = client.getTickCount();
		baitedShoal = null;
		baited = false;
		// Offcuts counted into the hold this same tick went in after the attempt that found none.
		boolean justDeposited = depositTick == client.getTickCount();
		if (!justDeposited && nearestShoal != null && takesPlainOffcuts(nearestShoal))
		{
			plainBait = 0;
			fineBait = 0;
		}
		else if (!justDeposited && plainBait >= 0)
		{
			fineBait = 0;
		}
		ranOutOfBait = baitLeft() == 0;
		baitedLabel = baitLabel();
	}

	/**
	 * Takes one offcut off the count for a bait just laid on the nearest shoal. A shoal that takes plain
	 * offcuts takes fine ones too, but uses the plain first, so fine ones only go once the plain have run out.
	 */
	private void useBait()
	{
		if (fineBait < 0 || nearestShoal == null)
		{
			return;
		}

		if (takesPlainOffcuts(nearestShoal) && plainBait > 0)
		{
			plainBait--;
		}
		else if (fineBait > 0)
		{
			fineBait--;
		}
		if (baitLeft() == 0)
		{
			ranOutOfBait = true;
		}
	}


	/**
	 * Whether a shoal is a special one: shimmering, glistening or vibrant.
	 */
	boolean isSpecial(Shoal shoal)
	{
		return MIXED_BY_CLICKBOX.containsKey(shoal.getClickbox());
	}

	/**
	 * Whether plain fish offcuts bait this shoal as well as fine ones. A kind with no entry is taken to
	 * need fine ones, which every kind of shoal accepts.
	 */
	private boolean takesPlainOffcuts(Shoal shoal)
	{
		String name = SPECIES_BY_CLICKBOX.get(shoal.getClickbox());
		return plainBaitSpecies.contains(name != null ? name : MIXED_BY_CLICKBOX.get(shoal.getClickbox()));
	}

	private String baitLabel()
	{
		// Asked every tick, but only made again when what it says has changed.
		int left = baitLeft();
		boolean out = isOutOfBait();
		if (left != labelLeft || out != labelOut)
		{
			labelLeft = left;
			labelOut = out;
			return label(left, out);
		}
		return baitedLabel;
	}

	private static String label(int left, boolean outOfBait)
	{
		if (outOfBait)
		{
			return "No bait";
		}
		// Counted in full, but a hold stocked with thousands only needs to say it has plenty.
		return "Baited (" + (left < 0 ? "?" : left > MAX_BAIT_SHOWN ? MAX_BAIT_SHOWN + "+" : Integer.toString(left)) + " left)";
	}

	/**
	 * Works out whether the nearest shoal is baited. The game records which step of its route a shoal was
	 * last baited at rather than how long the bait lasts, and never says when it wears off: the number
	 * stays where it is long after a bait, while the shoal swims on. A bait lasts until the
	 * shoal next arrives at a stop. Baited at a stop, it lasts the rest of that stop and the swim to the
	 * next; baited on the way, until the stop it is heading for. So a new number is a fresh bait on the
	 * nearest shoal, which stays baited until that shoal next arrives somewhere.
	 */
	private boolean stillBaited()
	{
		int step = client.getVarbitValue(VarbitID.SAILING_PLAYER_TRAWLING_SHOAL_BAITED_STEP);
		// A change on the tick a crewmate found nothing to bait with, or the one after, is that failed attempt.
		int tick = client.getTickCount();
		boolean laid = baitedStep != null && baitedStep != step
			&& (tick - baitFailedTick > 1 || tick - baitAnnouncedTick <= 1);
		baitedStep = step;

		if (laid && nearestShoal != null)
		{
			baitedShoal = nearestShoal;
			baitedWasStopped = nearestShoal.stopped();
			ticksSinceBait = 0;
			if (holdTick != tick)
			{
				// The hold's contents sent on the same tick as the bait already have that offcut taken out.
				useBait();
			}
		}
		else if (baitedShoal != null)
		{
			ticksSinceBait++;
			boolean stopped = baitedShoal.stopped();
			// An arrival right after the bait is the shoal settling in as it was baited, which the bait
			// outlasts. Any later one is the next stop, where it runs out.
			if (stopped && !baitedWasStopped && ticksSinceBait > ARRIVAL_GRACE_TICKS)
			{
				baitedShoal = null;
			}
			baitedWasStopped = stopped;
		}
		return nearestShoal != null && nearestShoal == baitedShoal;
	}

	/**
	 * Whether anything should be drawn at all, as worked out on the last tick, which is as much of the
	 * Show guides setting as the overlays need to know.
	 */
	boolean showGuides()
	{
		return showGuides;
	}

	/**
	 * Whether the setting is satisfied, on a boat that is already known to be underfoot: either that is
	 * enough on its own, or the boat has to be fitted with a trawling net as well.
	 */
	private boolean guidesWanted()
	{
		// Only ever asked while aboard, so what is left to settle is whether a net has to be fitted too.
		if (config.showGuides() == TrawlingPlusConfig.ShowGuides.ALWAYS)
		{
			return true;
		}

		return netsFitted;
	}

	/**
	 * Whether the player is stood on another player's boat, as of the last tick.
	 */
	boolean onOtherBoat()
	{
		return aboardBoat != null && ownBoat == null;
	}

	/**
	 * The player's boat they are stood on, theirs or another player's, or null. Everyone aboard stands in the
	 * boat's own world view rather than the one the sea is in, and the boat is looked up straight from that
	 * view's id rather than searched for among every world entity in the scene. What comes back is checked to
	 * be that same view and a player's boat.
	 */
	private WorldEntity boardedBoat()
	{
		Player player = client.getLocalPlayer();
		WorldView standing = player == null ? null : player.getWorldView();
		WorldView top = client.getTopLevelWorldView();
		if (standing == null || top == null || standing.isTopLevel() || standing.getId() < 0)
		{
			return null;
		}

		WorldEntity boat = top.worldEntities().byIndex(standing.getId());
		WorldView deck = boat == null ? null : boat.getWorldView();
		return deck != null && deck.getId() == standing.getId()
			&& (boat.getOwnerType() == WorldEntity.OWNER_TYPE_SELF_PLAYER
			|| boat.getOwnerType() == WorldEntity.OWNER_TYPE_OTHER_PLAYER) ? boat : null;
	}

	/**
	 * The shoal nearest the boat of the player, or null if there is no boat or no shoal to measure to.
	 */
	private Shoal nearest()
	{
		double[] afloat = boatPlace;
		if (afloat == null)
		{
			return null;
		}

		Shoal nearest = null;
		double nearestGap = Double.MAX_VALUE;
		for (Shoal shoal : shoals.values())
		{
			double[] at = isShown(shoal) ? shoal.position(client) : null;
			if (at == null)
			{
				continue;
			}

			double gap = squared(at[0] - afloat[0], at[1] - afloat[1]);
			if (gap < nearestGap)
			{
				nearestGap = gap;
				nearest = shoal;
			}
		}
		return nearest;
	}

	/**
	 * The square of a distance, for comparing distances without a square root.
	 */
	private static double squared(double x, double y)
	{
		return x * x + y * y;
	}

	/**
	 * A local point in world tile coordinates, including the fraction of a tile, or null.
	 */
	private double[] worldPlace(LocalPoint local)
	{
		WorldView view = local == null ? null : client.getWorldView(local.getWorldView());
		if (view == null)
		{
			return null;
		}

		return new double[]{
			view.getBaseX() + (double) (local.getX() - Perspective.LOCAL_HALF_TILE_SIZE) / Perspective.LOCAL_TILE_SIZE,
			view.getBaseY() + (double) (local.getY() - Perspective.LOCAL_HALF_TILE_SIZE) / Perspective.LOCAL_TILE_SIZE
		};
	}

	/**
	 * How long the shoal nearest the boat has left at its stop, in seconds, or -1 if there is no such
	 * shoal or it is on the move.
	 */
	double getSecondsAtStop()
	{
		return nearestShoal == null ? -1 : nearestShoal.secondsAtStop();
	}

	/**
	 * How full the bar over the shoal nearest the boat is at its stop, from 0 to 1, or -1 if there is no such shoal
	 * or it is on the move.
	 */
	double getStopBarFraction()
	{
		return nearestShoal == null ? -1 : nearestShoal.stopBarFraction();
	}

	/**
	 * Reads what the fish inside a shoal say about it, in one walk of them: how deep it is swimming,
	 * from the animation they play, falling back to the depth its species rests at until they are
	 * close enough to be animating; and how much is left of the bar drawn over it while it sits at a
	 * stop, which the game draws the way it draws a health bar. Both come off the same handful of
	 * NPCs, so they are taken together rather than walking them again for each.
	 */
	private static void read(WorldEntity entity, ShoalDepth resting, Shoal shoal)
	{
		WorldView view = entity.getWorldView();
		ShoalDepth depth = resting;
		boolean swimming = false;
		int bar = -1;
		int scale = -1;

		for (NPC npc : view == null ? Collections.<NPC>emptyList() : view.npcs())
		{
			if (!swimming)
			{
				ShoalDepth animating = ShoalDepth.fromAnimation(npc.getAnimation());
				if (animating != null)
				{
					depth = animating;
					swimming = true;
				}
			}

			if (scale < 0 && npc.getHealthScale() > 0)
			{
				bar = npc.getHealthRatio();
				scale = npc.getHealthScale();
			}

			if (swimming && scale >= 0)
			{
				// Both found, so the rest of the shoal has nothing left to say.
				break;
			}
		}

		shoal.setDepth(depth, swimming);
		shoal.setStopBar(bar, scale);
	}

	private ShoalRoute nearestRoute(double x, double y, String species)
	{
		ShoalRoute nearest = null;
		double nearestOffset = MAX_ROUTE_OFFSET;
		for (ShoalRoute route : routes)
		{
			if (species != null && !species.equals(route.getSpecies()))
			{
				continue;
			}

			double offset = route.project(x, y).offset;
			if (offset <= nearestOffset)
			{
				nearest = route;
				nearestOffset = offset;
			}
		}
		return nearest;
	}

	private static boolean isShoalClickbox(int id)
	{
		return SPECIES_BY_CLICKBOX.containsKey(id) || MIXED_BY_CLICKBOX.containsKey(id);
	}

	private void clearShoals()
	{
		entities.clear();
		clickboxByView.clear();
		holdByView.clear();
		netsByView.clear();
		netHighlights.clear();
		netIdleSince.clear();
		findCrewOnNets(null);
		shoals.clear();
		showGuides = false;
		stopTracking();
	}

	/**
	 * Forgets everything read off the boat and the shoals around it, leaving the shoals themselves
	 * alone: they come and go with their own events, and the world map still marks the ones in view.
	 */
	private void stopTracking()
	{
		boat = null;
		boatPlace = null;
		nearestShoal = null;
		nearestRoute = null;
		contender = null;
		contenderTicks = 0;
		baitedStep = null;
		baited = false;
		baitedShoal = null;
		netsAtDepth = false;
		leavingShoal = null;
		depthWarnedShoal = null;
	}

	@Provides
	TrawlingPlusConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TrawlingPlusConfig.class);
	}
}

package com.trawlingplus;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ShoalRouteTest
{
	// A 10 by 10 square swum from the origin, 40 tiles round, with stops at 10 and 30 tiles.
	private static final ShoalRoute SQUARE = new ShoalRoute("Test", "Square", 0,
		new double[][]{{0, 0}, {10, 0}, {10, 10}, {0, 10}},
		new double[][]{{10, 0}, {0, 10}}, null, null);

	@Test
	public void projectsOntoTheNearestPointOfTheLoop()
	{
		ShoalRoute.Projection onPath = SQUARE.project(5, 0);
		assertEquals(5, onPath.distance, 1e-9);
		assertEquals(0, onPath.offset, 1e-9);

		ShoalRoute.Projection offPath = SQUARE.project(5, -2);
		assertEquals(5, offPath.distance, 1e-9);
		assertEquals(2, offPath.offset, 1e-9);

		// The closing edge, from the last point back to the first.
		assertEquals(35, SQUARE.project(0, 5).distance, 1e-9);
	}

	@Test
	public void followingAlongALongStraightNeverJumpsAhead()
	{
		// Sides far longer than the stretch of route a shoal is followed within.
		ShoalRoute big = new ShoalRoute("Test", "Big", 0,
			new double[][]{{0, 0}, {40, 0}, {40, 40}, {0, 40}},
			new double[][]{{40, 0}}, null, null);
		double distance = big.project(0, 0).distance;
		for (double x = 0.5; x < 40; x += 0.5)
		{
			distance = big.project(x, 0, distance).distance;
			assertEquals("following at x = " + x, x, distance, 1e-9);
		}
	}

	@Test
	public void nextStopIsTheFirstOneAhead()
	{
		assertEquals(0, SQUARE.nextStop(5));
		assertEquals(1, SQUARE.nextStop(15));
	}

	@Test
	public void nextStopWrapsRoundTheLoop()
	{
		assertEquals(0, SQUARE.nextStop(35));
	}

	@Test
	public void aShoalSittingAtAStopIsHeadingForTheOneAfter()
	{
		assertEquals(1, SQUARE.nextStop(10));
		assertEquals(1, SQUARE.nextStop(8.5));
		assertEquals(0, SQUARE.nextStop(29));
	}

	@Test
	public void piecesShorterThanTheSpacingAreNotSplit()
	{
		ShoalRoute small = new ShoalRoute("Test", "Small", 0,
			new double[][]{{0, 0}, {2, 0}, {2, 2}, {0, 2}},
			new double[][]{{2, 0}}, null, null);
		assertEquals(4, small.sampleCount());
	}

	@Test
	public void samplesCoverTheLoopInOrder()
	{
		// Each 10 tile side is a straight, split into four pieces no longer than 3 tiles.
		assertEquals(16, SQUARE.sampleCount());
		assertEquals(0, SQUARE.sampleAt(0));
		assertEquals(4, SQUARE.sampleAt(10));
		// Past the last sample wraps back round to the first.
		assertEquals(0, SQUARE.sampleAt(39.5));
	}

	@Test
	public void pointAtFollowsTheRouteAndTheWayItRuns()
	{
		assertPoint(SQUARE.pointAt(5), 5, 0, 1, 0);
		assertPoint(SQUARE.pointAt(12.5), 10, 2.5, 0, 1);
		// On the closing edge, heading back to the start.
		assertPoint(SQUARE.pointAt(39.5), 0, 0.5, 0, -1);
		// Distances past the end wrap round.
		assertPoint(SQUARE.pointAt(45), 5, 0, 1, 0);
	}

	@Test
	public void overlapsOnlyRectanglesItReachesInto()
	{
		assertTrue(SQUARE.overlaps(5, 5, 20, 20));
		// Touching a corner counts.
		assertTrue(SQUARE.overlaps(-5, -5, 0, 0));
		assertFalse(SQUARE.overlaps(11, 11, 30, 30));
	}

	@Test
	public void lightSmoothingPassesThroughEveryPoint()
	{
		double[][] points = {{0, 0}, {10, 0}, {10, 10}, {0, 10}};
		double[][] curve = ShoalRoute.catmullRom(points);
		for (double[] point : points)
		{
			boolean found = false;
			for (double[] c : curve)
			{
				found |= Math.abs(c[0] - point[0]) < 1e-9 && Math.abs(c[1] - point[1]) < 1e-9;
			}
			assertTrue("curve misses " + point[0] + ", " + point[1], found);
		}
	}

	@Test
	public void heavySmoothingRunsThroughEveryStop()
	{
		// Heavy smoothing would cut these corners by over a tile, so stops on two of them have to be pulled onto.
		double[][] points = {{0, 0}, {20, 0}, {20, 20}, {0, 20}};
		double[][] stops = {{20, 0}, {0, 20}};
		ShoalRoute route = new ShoalRoute("Test", "Corners", 0, ShoalRoute.bSpline(points, stops), stops, null, null);
		for (int stop = 0; stop < route.stopCount(); stop++)
		{
			assertEquals(0, route.project(route.stopX(stop), route.stopY(stop)).offset, 0.01);
		}
	}

	@Test
	public void smoothingKeepsStraightStretchesStraight()
	{
		// Between (10, 0) and (20, 0) the neighbouring points are in line too, so neither curve can bend.
		double[][] points = {{0, 0}, {10, 0}, {20, 0}, {30, 0}, {30, 10}, {0, 10}};
		for (double[][] curve : new double[][][]{ShoalRoute.catmullRom(points), ShoalRoute.bSpline(points, new double[0][])})
		{
			for (double[] c : curve)
			{
				if (c[0] >= 10 && c[0] <= 20 && c[1] < 5)
				{
					assertEquals(0, c[1], 1e-9);
				}
			}
		}
	}

	@Test
	// Two tiles leaves room under the 3 a shoal may stray from its route before it stops being matched.
	public void smoothingNeverPullsARouteMoreThanTwoTilesOffItsPath() throws IOException
	{
		RouteData data = ShoalRoute.read(new Gson());
		for (RouteData.Species species : data.species)
		{
			for (RouteData.Route route : species.routes)
			{
				ShoalRoute original = new ShoalRoute(species.name, route.name, route.stopTicks,
					route.path, route.stops, route.safe, route.threats);
				for (double[][] curve : new double[][][]{ShoalRoute.catmullRom(route.path), ShoalRoute.bSpline(route.path, route.stops)})
				{
					for (double[] point : curve)
					{
						double offset = original.project(point[0], point[1]).offset;
						assertTrue(route.name + " curve is " + offset + " tiles off its path", offset <= 2);
					}
				}
			}
		}
	}

	@Test
	public void buildsEveryRouteWithItsStopsOnThePath() throws IOException
	{
		RouteData data = ShoalRoute.read(new Gson());
		for (TrawlingPlusConfig.Smoothing smoothing : TrawlingPlusConfig.Smoothing.values())
		{
			List<ShoalRoute> routes = ShoalRoute.build(data, smoothing);
			assertFalse(routes.isEmpty());
			for (int index = 0; index < routes.size(); index++)
			{
				ShoalRoute route = routes.get(index);
				for (int stop = 0; stop < route.stopCount(); stop++)
				{
					double offset = route.project(route.stopX(stop), route.stopY(stop)).offset;
					assertTrue(smoothing + " " + route.getSpecies() + " route " + index + " stop " + stop + " is " + offset + " tiles off its path", offset <= 1);
				}
			}
		}
	}

	private static void assertPoint(double[] point, double x, double y, double dx, double dy)
	{
		assertEquals(x, point[0], 1e-9);
		assertEquals(y, point[1], 1e-9);
		assertEquals(dx, point[2], 1e-9);
		assertEquals(dy, point[3], 1e-9);
	}
}

package com.trawlingplus;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ShoalTest
{
	@Test
	public void headingArrowShowsTheTickTheShoalMovesOff()
	{
		Shoal shoal = new Shoal(null);
		shoal.update(new double[]{0, 0}, null);
		shoal.update(new double[]{2, 0}, null);
		for (int tick = 0; tick < 70; tick++)
		{
			shoal.update(new double[]{2, 0}, null);
		}
		assertEquals(0, shoal.headingArrowOpacity(0), 1e-9);
		assertEquals(0, shoal.headingArrowOpacity(600), 1e-9);

		shoal.update(new double[]{4, 0}, null);
		assertEquals(1, shoal.headingArrowOpacity(1200), 1e-9);
	}

	@Test
	public void headingArrowStaysHiddenForAShoalFirstSeenSittingStill()
	{
		Shoal shoal = new Shoal(null);
		for (int tick = 0; tick < 200; tick++)
		{
			shoal.update(new double[]{5, 5}, null);
			assertEquals("opacity on tick " + tick, 0, shoal.headingArrowOpacity(tick * 600L), 1e-9);
		}

		// Until it swims off.
		shoal.update(new double[]{7, 5}, null);
		assertEquals(1, shoal.headingArrowOpacity(200 * 600L), 1e-9);
	}

	@Test
	public void headingArrowFadesInOverATick()
	{
		Shoal shoal = new Shoal(null);
		shoal.update(new double[]{0, 0}, null);
		shoal.update(new double[]{2, 0}, null);

		// It starts invisible; the first frame just starts the clock.
		assertEquals(0, shoal.headingArrowOpacity(1000), 1e-9);
		assertEquals(0.5, shoal.headingArrowOpacity(1300), 1e-9);
		assertEquals(1, shoal.headingArrowOpacity(1600), 1e-9);
		assertEquals(1, shoal.headingArrowOpacity(5000), 1e-9);
	}

	@Test
	public void stoppedTheTickTheDestinationStopsChanging()
	{
		Shoal shoal = new Shoal(null);
		shoal.update(new double[]{0, 0}, new double[]{1, 0});
		shoal.update(new double[]{0.5, 0}, new double[]{2, 0});
		assertFalse(shoal.stopped());

		// Still gliding towards its last destination, but no new one was sent, so it has stopped.
		shoal.update(new double[]{1.5, 0}, new double[]{2, 0});
		assertTrue(shoal.stopped());

		// A new destination means it has set off, before it has visibly moved.
		shoal.update(new double[]{2, 0}, new double[]{3, 0});
		assertFalse(shoal.stopped());
	}

	@Test
	public void headingArrowFadesOutWhenTheShoalStops()
	{
		Shoal shoal = new Shoal(null);
		shoal.update(new double[]{0, 0}, null);
		shoal.update(new double[]{2, 0}, null);
		shoal.headingArrowOpacity(0);
		assertEquals(1, shoal.headingArrowOpacity(600), 1e-9);

		// Sits still on the next tick, so the arrow fades away.
		shoal.update(new double[]{2, 0}, null);
		assertEquals(0.5, shoal.headingArrowOpacity(900), 1e-9);
		assertEquals(0, shoal.headingArrowOpacity(1200), 1e-9);
	}

	@Test
	public void routeDrawsOutToANewNextStopOverTheAnimationDuration()
	{
		Shoal shoal = new Shoal(null);
		shoal.headFor(2, 1000);
		assertEquals(0, shoal.routeReveal(1000, 7000), 1e-9);
		// Waits half a second for the shoal to settle in first.
		assertFalse(shoal.revealStarted(1400));
		assertTrue(shoal.revealStarted(1500));
		assertEquals(0, shoal.routeReveal(1500, 7000), 1e-9);
		assertEquals(0.28 / 3, shoal.routeReveal(2900, 7000), 1e-9);
		assertEquals(11.0 / 24, shoal.routeReveal(5000, 7000), 1e-9);
		assertEquals(1, shoal.routeReveal(8500, 7000), 1e-9);
		assertEquals(1, shoal.routeReveal(11000, 7000), 1e-9);

		// A shorter animation gets there sooner.
		assertEquals(11.0 / 24, shoal.routeReveal(3000, 3000), 1e-9);
		assertEquals(1, shoal.routeReveal(4500, 3000), 1e-9);
	}

	@Test
	public void nextStopFadesInOnceTheRouteReachesIt()
	{
		Shoal shoal = new Shoal(null);
		shoal.headFor(2, 1000);
		assertEquals(0, shoal.nextStopReveal(4500, 7000), 1e-9);
		assertEquals(0, shoal.nextStopReveal(8500, 7000), 1e-9);
		assertEquals(0.5, shoal.nextStopReveal(8650, 7000), 1e-9);
		assertEquals(1, shoal.nextStopReveal(8800, 7000), 1e-9);
	}

	@Test
	public void remembersTheStopJustReachedUntilCleared()
	{
		Shoal shoal = new Shoal(null);
		shoal.headFor(2, 1000);
		assertEquals(-1, shoal.arrivedStop());

		shoal.headFor(3, 2000);
		assertEquals(2, shoal.arrivedStop());

		shoal.clearArrivedStop();
		assertEquals(-1, shoal.arrivedStop());
	}

	@Test
	public void revealOnlyRestartsWhenTheNextStopChanges()
	{
		Shoal shoal = new Shoal(null);
		shoal.headFor(2, 1000);
		shoal.headFor(2, 7800);
		assertEquals(1, shoal.routeReveal(8500, 7000), 1e-9);

		shoal.headFor(3, 9000);
		assertEquals(0, shoal.routeReveal(9000, 7000), 1e-9);
		assertEquals(0, shoal.nextStopReveal(9000, 7000), 1e-9);
	}
}

package com.trawlingplus;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TrawlingPlusPluginTest
{
